function planModal(){modal(`<div class="mh"><div><h2>Criar um plano</h2><p class="sub">Crie uma meta e deixe o Smart Life preparar os primeiros passos.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>O que você quer alcançar?</label><input id="plTitle" class="field" placeholder="Ex.: 500 dias de ofensiva no Duolingo"><label>Tipo de plano</label><select id="plType" class="field"><option value="count">Meta numérica</option><option value="money">Meta financeira</option><option value="progress">Projeto por progresso</option></select><label>Descrição</label><textarea id="plDesc" class="field" placeholder="Explique brevemente sua meta"></textarea><label>Prazo</label><input id="plDue" class="field" type="date" min="${tomorrowISO()}"><div id="plNumeric"><div class="profileEditGrid"><div><label>Meta final</label><input id="plTarget" class="field" type="number" min="0" step="any" placeholder="500"></div><div><label>Quanto já fez?</label><input id="plCurrent" class="field" type="number" min="0" step="any" value="0"></div></div><label>Unidade</label><input id="plUnit" class="field" value="dias" placeholder="dias, km, aulas..."></div><div id="plMoney" style="display:none"><div class="profileEditGrid"><div><label>Valor final</label><input id="plMoneyTarget" class="field" type="number" min="0" step="0.01" placeholder="5000"></div><div><label>Valor atual</label><input id="plMoneyCurrent" class="field" type="number" min="0" step="0.01" value="0"></div></div></div><div id="plProgress" style="display:none"><label>Progresso atual (%)</label><input id="plPct" class="field" type="number" min="0" max="100" value="0"></div><div class="planPreview"><b>O plano vai criar:</b><span>1 meta acompanhável + 5 missões iniciais ligadas a ela.</span></div><button class="btn" id="plSave" style="margin-top:14px">Criar plano</button></div>`);let sync=()=>{let t=plType.value;plNumeric.style.display=t==="count"?"block":"none";plMoney.style.display=t==="money"?"block":"none";plProgress.style.display=t==="progress"?"block":"none"};byId("cx").onclick=closeM;plType.onchange=sync;sync();plSave.onclick=()=>{let title=plTitle.value.trim(),type=plType.value,due=plDue.value;if(!title)return toast("Informe o objetivo do plano.","warn");if(!requireFutureDate(due,"O prazo da meta"))return;let project={id:id(),title,desc:plDesc.value.trim(),type,due,progress:type==="progress"?Math.max(0,Math.min(100,Number(plPct.value)||0)):0,target:type==="count"?Math.max(0,Number(plTarget.value)||0):type==="money"?Math.max(0,Number(plMoneyTarget.value)||0):0,current:type==="count"?Math.max(0,Number(plCurrent.value)||0):type==="money"?Math.max(0,Number(plMoneyCurrent.value)||0):0,unit:type==="count"?(plUnit.value.trim()||"unidades"):"",updates:[],done:false,createdAt:new Date().toISOString()};if((type==="count"||type==="money")&&project.target<=0)return toast("Informe uma meta final maior que zero.","warn");project.done=type==="progress"?project.progress>=100:project.current>=project.target;D.projects.push(project);D.missions.push(...buildPlanMissions(project,type));evaluateTitles(true);save();closeM();nav="projects";render();toast("Meta criada com 5 missões iniciais para ajudar você a avançar.","success","Plano criado")}}
function projectModal(existing){let p=existing||{id:id(),title:"",desc:"",type:"progress",progress:0,target:0,current:0,unit:"dias",due:"",updates:[]};p.updates=Array.isArray(p.updates)?p.updates:[];modal(`<div class="mh"><div><h2>${existing?"Editar":"Novo"} projeto</h2><p class="sub">Use porcentagem, meta numérica ou meta de dinheiro.</p></div><button class="x" id="cx">×</button></div><div class="form" id="projectForm"><label>Nome</label><input id="pjTitle" class="field" value="${esc(p.title)}"><label>Tipo</label><select id="pjType" class="field"><option value="progress" ${p.type==="progress"||(!p.type)?"selected":""}>Progresso (%)</option><option value="count" ${p.type==="count"?"selected":""}>Meta numérica</option><option value="money" ${p.type==="money"?"selected":""}>Meta de dinheiro</option></select><label>Descrição</label><textarea id="pjDesc" class="field">${esc(p.desc||"")}</textarea><label>Prazo</label><input id="pjDue" type="date" min="${tomorrowISO()}" class="field" value="${esc(p.due||"")}"><div id="pjProgressWrap"><label>Progresso (%)</label><input id="pjProgress" type="number" min="0" max="100" step="0.1" class="field" value="${Number(p.progress||0)}"></div><div id="pjCountWrap"><div class="profileEditGrid"><div><label>Meta final</label><input id="pjCountTarget" type="number" min="0" step="any" class="field" value="${p.type==='count'?Number(p.target||0):0}" placeholder="Ex.: 500"></div><div><label>Valor atual</label><input id="pjCountCurrent" type="number" min="0" step="any" class="field" value="${p.type==='count'?Number(p.current||0):0}" placeholder="Ex.: 479"></div></div><label>Unidade</label><input id="pjUnit" class="field" value="${esc(p.unit||'dias')}" placeholder="dias, aulas, km, livros..."><p class="sub">Ex.: meta 500 e atual 479 = 95,8% automaticamente.</p></div><div id="pjMoneyWrap"><div class="profileEditGrid"><div><label>Valor final</label><input id="pjTarget" type="number" min="0" step="0.01" class="field" value="${p.type==='money'?Number(p.target||0):0}"></div><div><label>Valor atual</label><input id="pjCurrent" type="number" min="0" step="0.01" class="field" value="${p.type==='money'?Number(p.current||0):0}"></div></div></div><button class="btn" id="pjSave" style="margin-top:16px">Salvar projeto</button></div>`);let sync=()=>{let t=pjType.value;pjMoneyWrap.style.display=t==="money"?"block":"none";pjCountWrap.style.display=t==="count"?"block":"none";pjProgressWrap.style.display=t==="progress"?"block":"none"};cx.onclick=closeM;pjType.onchange=sync;sync();pjSave.onclick=()=>{if(!pjTitle.value.trim())return toast("Informe o nome do projeto.","warn");let t=pjType.value,due=pjDue.value;if(!requireFutureDate(due,"O prazo da meta",existing?p.due:""))return;let obj={...p,title:pjTitle.value.trim(),desc:pjDesc.value.trim(),type:t,due,progress:Math.max(0,Math.min(100,+pjProgress.value||0)),target:t==="money"?Math.max(0,+pjTarget.value||0):t==="count"?Math.max(0,+pjCountTarget.value||0):0,current:t==="money"?Math.max(0,+pjCurrent.value||0):t==="count"?Math.max(0,+pjCountCurrent.value||0):0,unit:t==="count"?(pjUnit.value.trim()||"unidades"):""};if((t==="money"||t==="count")&&obj.target<=0)return toast("Informe uma meta final maior que zero.","warn");obj.done=t==="money"||t==="count"?obj.target>0&&obj.current>=obj.target:obj.progress>=100;let i=D.projects.findIndex(x=>x.id===obj.id);i>=0?D.projects[i]=obj:D.projects.push(obj);evaluateTitles(true);save();closeM();render();toast(t==="count"?`Progresso calculado: ${pctText(projectPct(obj))}%.`:"Projeto e progresso foram atualizados.","success","Projeto salvo")}}
function projectMoneyModal(p){let target=Number(p.target||0);modal(`<div class="mh"><div><div class="kicker">META FINANCEIRA</div><h2>Atualizar valor</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Objetivo final</span><b>${target.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</b></div><div class="form"><label>Valor atual</label><div class="moneyInput"><span>R$</span><input id="pmValue" class="field" inputmode="decimal" value="${Number(p.current||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})}"></div><p class="sub">Informe quanto você já possui para esta meta.</p><div class="modalActions"><button class="pill" id="pmCancel">Cancelar</button><button class="btn" id="pmSave">Salvar valor</button></div></div>`);cx.onclick=closeM;pmCancel.onclick=closeM;setTimeout(()=>{pmValue.focus();pmValue.select()},0);pmSave.onclick=()=>{let raw=pmValue.value.trim().replace(/\./g,"").replace(",","."),n=Number(raw);if(!Number.isFinite(n)||n<0)return toast("Informe um valor válido.","warn");p.current=n;p.done=p.target>0&&p.current>=p.target;evaluateTitles(true);save();closeM();render();toast(`Valor atual: ${n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}.`,"success","Meta atualizada")}}
function projectCountModal(p){let target=Number(p.target||0),unit=esc(p.unit||"unidades");modal(`<div class="mh"><div><div class="kicker">META NUMÉRICA</div><h2>Atualizar progresso</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Meta final</span><b>${target.toLocaleString("pt-BR")} ${unit}</b></div><div class="form"><label>Valor atual</label><input id="pcValue" class="field" inputmode="decimal" type="number" min="0" step="any" value="${Number(p.current||0)}"><p class="sub" id="pcPreview">Progresso: ${pctText(projectPct(p))}%</p><div class="modalActions"><button class="pill" id="pcCancel">Cancelar</button><button class="btn" id="pcSave">Salvar progresso</button></div></div>`);cx.onclick=closeM;pcCancel.onclick=closeM;pcValue.oninput=()=>{let n=Number(pcValue.value||0),pct=target>0?Math.max(0,Math.min(100,n/target*100)):0;pcPreview.textContent=`Progresso: ${pctText(pct)}%`};setTimeout(()=>{pcValue.focus();pcValue.select()},0);pcSave.onclick=()=>{let n=Number(pcValue.value);if(!Number.isFinite(n)||n<0)return toast("Informe um valor válido.","warn");p.current=n;p.done=p.target>0&&p.current>=p.target;evaluateTitles(true);save();closeM();render();toast(`Progresso: ${pctText(projectPct(p))}% (${n.toLocaleString("pt-BR")} de ${target.toLocaleString("pt-BR")} ${unit}).`,"success","Meta atualizada")}}
function addProjectValue(p,amount){amount=Number(amount);if(!p||!Number.isFinite(amount)||amount<=0)return toast("Informe um valor maior que zero.","warn");p.current=Number(p.current||0)+amount;p.updates=Array.isArray(p.updates)?p.updates:[];p.updates.unshift({id:id(),amount,date:new Date().toLocaleDateString("pt-BR"),time:new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})});p.updates=p.updates.slice(0,100);p.done=Number(p.target||0)>0&&p.current>=Number(p.target||0);hist("project_add",{project:p.title,amount,type:p.type});evaluateTitles(true);save();render();let msg=p.type==="money"?`${amount.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})} adicionados. Total: ${Number(p.current).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}.`:`+${amount.toLocaleString("pt-BR")} ${p.unit||"unidades"}. Total: ${Number(p.current).toLocaleString("pt-BR")} de ${Number(p.target||0).toLocaleString("pt-BR")}.`;toast(msg,"success","Progresso adicionado")}
function projectAddModal(p){let money=p.type==="money",unit=esc(p.unit||"unidades");modal(`<div class="mh"><div><div class="kicker">${money?"META FINANCEIRA":"META NUMÉRICA"}</div><h2>Adicionar ao progresso</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Total atual</span><b>${money?Number(p.current||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}):`${Number(p.current||0).toLocaleString("pt-BR")} ${unit}`}</b></div><div class="form"><label>Quanto deseja adicionar?</label>${money?`<div class="moneyInput"><span>R$</span><input id="paValue" class="field" inputmode="decimal" placeholder="0,00"></div>`:`<input id="paValue" class="field" type="number" min="0" step="any" inputmode="decimal" placeholder="Ex.: 1">`}<p class="sub">O valor será somado ao total atual e a porcentagem será recalculada automaticamente.</p><div class="projectAddPresets">${(money?[10,100,500]:[1,5,10]).map(n=>`<button class="pill" type="button" data-pa-preset="${n}">+${money?` R$ ${n}`:n}</button>`).join("")}</div><div class="modalActions"><button class="pill" id="paCancel">Cancelar</button><button class="btn" id="paSave">Adicionar</button></div></div>`);cx.onclick=closeM;paCancel.onclick=closeM;document.querySelectorAll("[data-pa-preset]").forEach(b=>b.onclick=()=>{paValue.value=money?Number(b.dataset.paPreset).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2}):b.dataset.paPreset;paValue.focus()});setTimeout(()=>paValue.focus(),0);paSave.onclick=()=>{let raw=String(paValue.value||"").trim();if(money)raw=raw.replace(/\./g,"").replace(",",".");let n=Number(raw);if(!Number.isFinite(n)||n<=0)return toast("Informe um valor maior que zero.","warn");closeM();addProjectValue(p,n)}}
function organize(){let p=D.pages.find(x=>x.id===D.activePage)||D.pages[0];D.activePage=p?.id;return header("Organização","Seu espaço estilo Notion",`<button class="btn" data-act="newPage">＋ Página</button>`)+`<div class="notion"><div class="card pages">${D.pages.map(x=>`<button class="${x.id===p?.id?"on":""}" data-page="${x.id}">▤ ${esc(x.title)}</button>`).join("")}</div><div class="card editor">${p?`<input id="pt" class="field" value="${esc(p.title)}" style="font-size:24px;font-weight:900;border:0;padding-left:0"><div id="pe" contenteditable="true">${esc(p.content).replace(/\n/g,"<br>")}</div><div class="row"><button class="btn" data-savepage="${p.id}">Salvar</button><button class="btn red" data-delpage="${p.id}">Excluir</button></div>`:`<p class="sub">Crie uma página.</p>`}</div></div>`}
function profile(){let r=rank(),eq=D.titles.find(t=>t.equipped),x=levelCalc();return header("Perfil","Sua identidade e evolução dentro do sistema",`<div class="row profileHeaderActions"><button class="pill" data-act="shareProgress">↗ Compartilhar</button><button class="pill" data-nav="settings">⚙ Configurações</button><button class="pill" data-act="editProfile">✎ Editar perfil</button></div>`)+`<div class="profileHero card glow"><div class="profileHeroAvatar avatar">${avatarHTML()}</div><div class="profileHeroMain"><span class="kicker">JOGADOR • RANK ${r[0]}</span><h1>${esc(D.profile.name)}</h1><p class="sub">@${esc(D.profile.username)} • ${esc(r[1])}</p><div class="profileBadges"><span>🏆 ${esc(eq?.name||"Sem título")}</span><span>✦ Level ${D.level}</span><span>ϟ ${D.totalXP.toLocaleString("pt-BR")} XP</span></div><div class="label"><span>Próximo nível</span><b>${x.x}/${x.n} XP</b></div><div class="bar"><i style="width:${x.x/x.n*100}%"></i></div></div></div><div class="stats profileStats"><div class="stat">🔥 Melhor Streak<b>${D.bestStreak}</b><small>dias</small></div><div class="stat">✓ Conclusões<b>${D.history.filter(x=>x.type==="habit_done").length}</b><small>hábitos</small></div><div class="stat">⚑ Missões<b>${D.missions.filter(x=>x.done).length}</b><small>concluídas</small></div><div class="stat">◆ Projetos<b>${D.projects.filter(x=>x.done).length}</b><small>finalizados</small></div></div><div class="section"><h2>Perfil de Habilidades</h2><span class="sub">Seus Status de forma clara e comparável.</span></div>${skillProfile()}`}
function resetPlayerProgress(){
 let keepProfile={...D.profile},keepSettings={...D.settings},keepFinance=JSON.parse(JSON.stringify(D.finance||emptyFinance())),keepOnboarding=D.onboardingProfile,clean=fresh(false);
 clean.onboarded=true;clean.onboardingProfile=keepOnboarding;clean.finance=keepFinance;clean.profile={...clean.profile,...keepProfile};clean.settings={...clean.settings,...keepSettings};
 D=clean;if(Array.isArray(D.onboardingProfile?.answers))createOnboardingMissionPlan(D.onboardingProfile.answers);save();applyTheme();closeM();nav="missions";render();toast("Progresso zerado e um novo plano inicial foi criado com base nas suas respostas.","success","Personagem reiniciado")
}
function resetPlayerModal(){modal(`<div class="mh"><div><h2>Reiniciar personagem?</h2><p class="sub">Zera apenas o progresso do personagem e mantém sua identidade e preferências.</p></div><button class="x" id="cx">×</button></div><div class="dangerBox"><b>O que será zerado</b><p>XP, nível, atributos, sequência, títulos, hábitos, missões, projetos, histórico e registros das ferramentas.</p><p><b>Seu nome, foto, nome de usuário, tema e preferências serão mantidos.</b></p></div><div class="modalActions"><button class="pill" id="playerResetCancel">Cancelar</button><button class="btn red" id="playerResetConfirm">Reiniciar personagem</button></div>`);byId("playerResetCancel").onclick=closeM;byId("playerResetConfirm").onclick=resetPlayerProgress}

function financeOwnerId(){return Number(D.finance?.selectedOwnerId||0)}
function financeOwn(r,owner=financeOwnerId()){return Number(r?.owner_id)===Number(owner)}
function moneyBR(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}
function financeMonth(){return iso().slice(0,7)}
function financeMonthLabel(month){if(!/^\d{4}-\d{2}$/.test(String(month||"")))return month||"";let [y,m]=month.split("-").map(Number);return new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(new Date(y,m-1,1))}
function financeShiftMonth(month,delta){let [y,m]=String(month||financeMonth()).split("-").map(Number),d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function financeDateForMonthDay(month,day){let [y,m]=String(month).split("-").map(Number),last=new Date(y,m,0).getDate(),d=Math.max(1,Math.min(last,Number(day)||1));return `${y}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}`}
function financeRecordMonth(r,kind){let v=kind==="expense"?(r.list_month||r.billing_month||r.due_date||r.purchase_date):(r.expected_date||r.received_date);return String(v||"").slice(0,7)}
function financeCatName(id){return D.finance.categories.find(c=>Number(c.id)===Number(id))?.name||"Sem categoria"}
function financeCardName(id){return D.finance.cards.find(a=>Number(a.id)===Number(id))?.name||""}
function financeSummary(month=financeMonthSelected){let o=financeOwnerId(),inc=D.finance.incomes.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"income")===month),exp=D.finance.expenses.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"expense")===month),expected=inc.reduce((s,x)=>s+Number(x.amount_expected||0),0),received=inc.reduce((s,x)=>s+Number(x.amount_received||0),0),totalExp=exp.reduce((s,x)=>s+Number(x.amount||0),0),paid=exp.filter(x=>String(x.status)==="paid"||x.paid_date).reduce((s,x)=>s+Number(x.amount||0),0),pending=Math.max(0,totalExp-paid);return{inc,exp,expected,received,totalExp,paid,pending,balance:received-paid,commit:expected?Math.min(999,totalExp/expected*100):0}}
function financeMonthControls(){return `<div class="financeMonthControls"><button class="iconAction" data-fin-month-step="-1" title="Mês anterior">‹</button><input id="financeMonthInput" class="field financeMonthInput" type="month" value="${financeMonthSelected}"><button class="iconAction" data-fin-month-step="1" title="Próximo mês">›</button><button class="pill" data-fin-month-current>Hoje</button></div>`}
function financeTabs(){let tabs=[["dashboard","Visão geral"],["incomes","Receitas"],["expenses","Despesas"],["cards","Cartões"],["loans","Empréstimos"],["recurring","Recorrentes"],["planning","Planejamento"]];return `<div class="financeTabs">${tabs.map(t=>`<button class="${financeTab===t[0]?"on":""}" data-fin-tab="${t[0]}">${t[1]}</button>`).join("")}</div>`}
function financeRecurrenceActiveForMonth(r,month){let start=String(r.start_month||month).slice(0,7),end=String(r.end_month||"").slice(0,7);return Number(r.active)!==0&&month>=start&&(!end||month<=end)}
function ensureFinanceRecurringForMonth(month){let o=financeOwnerId(),added=0;D.finance.recurring_expenses.filter(x=>financeOwn(x,o)&&financeRecurrenceActiveForMonth(x,month)).forEach(r=>{if(D.finance.expenses.some(e=>Number(e.recurrence_id)===Number(r.id)&&financeRecordMonth(e,"expense")===month))return;let due=financeDateForMonthDay(month,r.due_day);D.finance.expenses.push({id:nextFinanceId(D.finance.expenses),owner_id:o,description:r.description,amount:Number(r.amount||0),purchase_date:due,due_date:due,paid_date:null,category_id:r.category_id??null,expense_type:"fixed",payment_method:r.payment_method||"pix",merchant:r.merchant||"",notes:"",status:"pending",account_id:r.account_id??null,card_id:null,attachment_path:null,recurrence_id:r.id,installment_group:null,installment_number:null,total_installments:null,billing_month:month,list_month:month,created_at:new Date().toISOString(),external_id:null});added++});D.finance.recurring_incomes.filter(x=>financeOwn(x,o)&&financeRecurrenceActiveForMonth(x,month)).forEach(r=>{if(D.finance.incomes.some(e=>Number(e.recurrence_id)===Number(r.id)&&financeRecordMonth(e,"income")===month))return;let date=financeDateForMonthDay(month,r.expected_day);D.finance.incomes.push({id:nextFinanceId(D.finance.incomes),owner_id:o,description:r.description,amount_expected:Number(r.amount||0),amount_received:0,expected_date:date,received_date:null,status:"pending",account_id:r.account_id??null,category_id:r.category_id??null,notes:r.notes||"",created_at:new Date().toISOString(),recurrence_id:r.id,external_id:null,attachment_path:null});added++});return added}
function finance(){let owner=financeOwnerId(),user=D.finance.users.find(u=>Number(u.id)===owner);let added=ensureFinanceRecurringForMonth(financeMonthSelected);if(added)try{localStorage.setItem(KEY,JSON.stringify(D))}catch{};let top=header("Finanças","Smart Finance integrado ao Smart Life",`<div class="row financeHeadActions"><button class="pill" data-fin-export>⇩ Exportar</button><button class="pill" data-fin-import>⇧ Importar</button></div>`)+`<div class="financeSource"><span>Dados importados do Smart Finance${user?` • ${esc(user.display_name||user.username)}`:""}</span><small>As contas bancárias continuam preservadas no backup para compatibilidade, mas foram removidas da interface do Smart Life para deixar o módulo mais simples.</small></div>`+`<div class="financeTopRow">${financeMonthControls()}<span class="financeMonthLabel">${esc(financeMonthLabel(financeMonthSelected))}</span></div>`+financeTabs();return top+(financeTab==="dashboard"?financeDashboard():financeTab==="incomes"?financeIncomes():financeTab==="expenses"?financeExpenses():financeTab==="cards"?financeCards():financeTab==="loans"?financeLoans():financeTab==="recurring"?financeRecurring():financePlanning())}
