function hrow(h){let current=Number(h.toolProgress?.[iso()]||0),goal=Number(h.toolGoal||0);return`<div class="habit ${sameId(focusHabitId,h.id)?"focusItemHalo":""}" data-habit-card="${h.id}"><button class="check ${done(h)?"done":""}" data-h="${h.id}">✓</button><div class="grow habitOpenArea" data-open-habit="${h.id}" tabindex="0" role="button" title="Abrir e destacar este hábito"><div class="ht">${esc(h.title)}</div><div class="meta">${(h.bonus||[]).map(b=>`<span class="tag ${b.k==="hydration"?"blue":b.k==="focus"?"green":""}">${ATTR.find(a=>a[0]===b.k)?.[4]} +${b.n}</span>`).join("")}${goal?`<span class="habitLinkedProgress">${current}/${goal} ${esc(h.toolUnit||"")}</span>`:""}</div></div><div class="xp">ϟ ${h.xp}</div></div>`}
function missionRewardCap(m){return{E:1,D:1,C:2,B:3,A:4,S:5}[missionRank(m)]||1}
function missionSuggestedRewardKeys(m){let text=`${m?.title||""} ${m?.desc||""} ${m?.category||""}`.toLocaleLowerCase("pt-BR"),rules=[["hydration",["água","agua","hidrata","litro"]],["strength",["treino","força","forca","muscul","exercício","exercicio"]],["vitality",["sono","dorm","saúde","saude","energia","aliment"]],["intelligence",["leitura","livro","estud","curso","aprender"]],["focus",["foco","concentr","prioridade","pomodoro"]],["charisma",["convers","social","apresent","comunica"]],["agility",["corrida","caminh","mobilidade","agilidade"]],["discipline",["organiza","rotina","planej","constância","constancia"]]],keys=[];rules.forEach(([k,words])=>{if(words.some(w=>text.includes(w)))keys.push(k)});return keys.length?keys:["discipline"]}
function missionRewards(m){let cap=missionRewardCap(m),source=Array.isArray(m?.attributeRewards)&&m.rewardMode==="custom"?m.attributeRewards:missionSuggestedRewardKeys(m).map(k=>({k,n:1})),out=[],left=cap;source.forEach(r=>{if(left<=0||!ATTR.some(a=>a[0]===r.k)||out.some(x=>x.k===r.k))return;let n=Math.max(1,Math.min(left,Number(r.n)||1));out.push({k:r.k,n});left-=n});if(m?.rewardMode!=="custom"&&out.length&&left>0)out[0].n+=left;return out}
function missionRewardBadges(m,rewards=missionRewards(m)){return rewards.map(r=>{let a=ATTR.find(x=>x[0]===r.k);return`<span class="tag ${r.k==="hydration"?"blue":r.k==="focus"?"green":""}">${a?.[4]||"ATR"} +${r.n}</span>`}).join("")}
function completeMission(m,fromTool=false){if(!m||m.done||(m.subtasks||[]).some(x=>!x.done))return false;m.done=true;m.completedAt=new Date().toISOString();m.earnedXP=addXP(m.xp,m.title,`mission:${m.id}`);m.earnedAttributes=missionRewards(m);m.earnedAttributes.forEach(r=>applyAttr(r.k,r.n,m.title));hist("mission_done",{title:m.title,missionId:m.id,amount:m.earnedXP,attributes:m.earnedAttributes,completedAt:m.completedAt,fromTool});evaluateTitles(true);save();if(!fromTool)taskFx(m.title);return true}
function openMissionTarget(mid){if(!mid)return;let mission=D.missions.find(x=>sameId(x.id,mid));if(!mission)return toast("Esta missão não foi encontrada.","warn","Item indisponível");if(nav==="missions"){focusMissionId="";return}focusMissionId=String(mission.id);missionTab=mission.done?"completed":"open";if(mission.done)completedMissionFilter=missionIsRecent(mission)?"recent":"archive";nav="missions";render();scrollTo(0,0);setTimeout(()=>{let el=document.querySelector(`[data-mission-card="${String(mission.id)}"]`);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("focusItemHalo");setTimeout(()=>{el.classList.remove("focusItemHalo");if(sameId(focusMissionId,mission.id))focusMissionId=""},3200)}},160)}
function openProjectTarget(pid){if(!pid)return;let project=D.projects.find(x=>sameId(x.id,pid));if(!project)return toast("Este projeto não foi encontrado.","warn","Item indisponível");focusProjectId=String(project.id);nav="projects";render();scrollTo(0,0);setTimeout(()=>{let el=document.querySelector(`[data-project-card="${String(project.id)}"]`);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("focusItemHalo");setTimeout(()=>{el.classList.remove("focusItemHalo");if(sameId(focusProjectId,project.id))focusProjectId=""},3200)}},140)}
function postponeMission(m){if(!m||m.done)return;m.due=tomorrowISO();m.scheduleDate=m.due;m.expired=false;save();render();toast(`“${m.title}” foi adiada para amanhã.`,"success","Missão reagendada")}
function missionSubtasksModal(m){if(!m)return;m.subtasks=Array.isArray(m.subtasks)?m.subtasks:[];modal(`<div class="mh"><div><h2>Subtarefas da missão</h2><p class="sub">${esc(m.title)}</p></div><button class="x" id="cx">×</button></div><div class="missionSubtaskList">${m.subtasks.length?m.subtasks.map(s=>`<label class="item ${s.done?"done":""}"><input type="checkbox" data-mission-subtask="${s.id}" ${s.done?"checked":""}><span>${esc(s.title)}</span></label>`).join(""):`<p class="sub">Esta missão ainda não possui subtarefas.</p>`}</div><div class="modalActions"><button class="pill" data-close>Fechar</button><button class="btn" id="missionSubtasksSave">Salvar progresso</button></div>`);byId("missionSubtasksSave").onclick=()=>{document.querySelectorAll("[data-mission-subtask]").forEach(x=>{let s=m.subtasks.find(q=>sameId(q.id,x.dataset.missionSubtask));if(s)s.done=x.checked});save();closeM();render();toast("Subtarefas atualizadas.","success","Missão atualizada")}}
function missionCard(m){let mr=missionRank(m),mins=missionMinutes(m),priority=Number(m.priority||m.aiPriority||0),progress=Number(m.toolProgress?.[iso()]||0),goal=Number(m.toolGoal||0);return`<div class="item missionItem ${m.source==="smart-daily"?"smartDailyMission":""} ${sameId(focusMissionId,m.id)?"focusItemHalo":""}" data-mission-card="${m.id}"><div class="missionRankBadge rank-${mr.toLowerCase()}">${mr}</div><button class="grow missionOpenArea" data-open-mission="${m.id}" title="Abrir e destacar esta missão"><div class="missionTitleLine"><b>${esc(m.title)}</b>${missionSourceBadge(m)}${priority?`<span class="priorityPill p${priority}">P${priority}</span>`:""}</div><p class="sub">${esc(m.desc||"")}</p>${goal?`<div class="linkedProgress"><span>${progress}/${goal} ${esc(m.toolUnit||"")}</span><i style="width:${Math.min(100,progress/goal*100)}%"></i></div>`:""}<div class="missionMeta"><span>⏱ ${mins} min</span><span>ϟ ${m.xp} XP</span>${missionRewardBadges(m)}${(m.subtasks||[]).length?`<span>☑ ${(m.subtasks||[]).filter(x=>x.done).length}/${m.subtasks.length}</span>`:""}${m.due?`<span>📅 ${esc(m.due.split("-").reverse().join("/"))}</span>`:""}${m.category?`<span>${esc(m.category)}</span>`:""}</div></button><div class="missionActions">${m.targetHabitId?`<button class="pill" data-open-habit="${m.targetHabitId}">Abrir hábito</button>`:""}${(m.subtasks||[]).length?`<button class="pill" data-mission-subtasks="${m.id}">☑ Subtarefas</button>`:""}<button class="pill" data-postpone-mission="${m.id}">Amanhã</button><button class="pill" data-edit-mission="${m.id}">Editar</button><button class="iconAction danger" data-delete-mission="${m.id}" title="Excluir">×</button><button class="btn" data-complete="${m.id}">Concluir</button></div></div>`}
function completedMissionCard(m){let stamp=missionCompletionISO(m),when=stamp?new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(new Date(stamp)):"Registro anterior",earned=Number(m.earnedXP??m.xp??0),rewards=Array.isArray(m.earnedAttributes)?m.earnedAttributes:missionRewards(m);return`<div class="item missionItem completedMissionCard ${sameId(focusMissionId,m.id)?"focusItemHalo":""}" data-mission-card="${m.id}"><div class="completedCheck">✓</div><button class="grow missionOpenArea" data-open-mission="${m.id}" title="Abrir e destacar esta missão"><b>${esc(m.title)}</b><p class="sub">${esc(m.desc||"")}</p><div class="missionMeta"><span>Concluída em ${esc(when)}</span><span>ϟ ${earned} XP</span>${missionRewardBadges(m,rewards)}</div></button><button class="iconAction danger" data-delete-mission="${m.id}" title="Excluir do histórico">×</button></div>`}
function missionEditor(existing=null){let m=existing?{...existing,id:String(existing.id??"").trim()||id()}:{id:id(),title:"",desc:"",due:"",xp:100,estimatedMinutes:30,done:false,source:"user",rewardMode:"auto",createdAt:new Date().toISOString()},selected=(Array.isArray(m.attributeRewards)?m.attributeRewards:[]).map(x=>({...x}));modal(`<div class="mh"><div><h2>${existing?"Editar":"Nova"} missão</h2><p class="sub">O sistema sugere os Status; você pode personalizar dentro do limite da dificuldade.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Título</label><input id="mt" class="field" maxlength="80" value="${esc(m.title)}"><label>Descrição</label><textarea id="md" class="field" maxlength="400">${esc(m.desc||"")}</textarea><label>Subtarefas <small class="fieldLimit">uma por linha</small></label><textarea id="missionSubtasks" class="field" maxlength="1000" placeholder="Ex.: Pesquisar referências\nPreparar primeira versão">${esc((m.subtasks||[]).map(x=>x.title).join("\n"))}</textarea><label>Prazo</label><input id="mdu" class="field" type="date" min="${tomorrowISO()}" value="${esc(m.due||"")}"><p class="sub">Novas datas devem começar amanhã. Missões antigas continuam visíveis sem alteração.</p><div class="profileEditGrid"><div><label>XP</label><input id="mx" class="field" type="number" min="10" max="500" value="${Number(m.xp||100)}"></div><div><label>Tempo estimado (min)</label><input id="mmin" class="field" type="number" min="5" max="180" value="${missionMinutes(m)}"></div></div><label>Prioridade</label><select id="missionPriority" class="field"><option value="3" ${Number(m.priority||m.aiPriority||3)===3?"selected":""}>Normal</option><option value="2" ${Number(m.priority||m.aiPriority||3)===2?"selected":""}>Média</option><option value="1" ${Number(m.priority||m.aiPriority||3)===1?"selected":""}>Alta</option></select><label>Recompensa de Status</label><select id="missionRewardMode" class="field"><option value="auto" ${m.rewardMode!=="custom"?"selected":""}>Sugerida pelo sistema</option><option value="custom" ${m.rewardMode==="custom"?"selected":""}>Personalizar recompensa</option></select><div id="missionRewardEditor" class="missionRewardEditor"></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="ms">${existing?"Salvar alterações":"Criar missão"}</button></div></div>`);let draft=()=>({...m,title:byId("mt")?.value||"",desc:byId("md")?.value||"",xp:Math.max(10,Math.min(500,Number(byId("mx")?.value)||100)),estimatedMinutes:Math.max(5,Math.min(180,Number(byId("mmin")?.value)||30))}),drawRewards=()=>{let box=byId("missionRewardEditor"),mode=byId("missionRewardMode").value,cap=missionRewardCap(draft());if(!box)return;if(mode==="auto"){let preview=missionRewards({...draft(),rewardMode:"auto"});box.innerHTML=`<p class="sub">Tempo: ${missionMinutes(draft())} min • Rank ${missionRank(draft())} • limite: ${cap} ponto(s). Sugestão equilibrada: <span class="meta">${missionRewardBadges(draft(),preview)}</span></p>`;return}box.innerHTML=`<p class="sub">Distribua até ${cap} ponto(s). Total atual: ${selected.reduce((s,x)=>s+Number(x.n||0),0)}.</p><div class="chips">${ATTR.map(a=>`<button type="button" class="chip ${selected.some(x=>x.k===a[0])?"sel":""}" data-mission-attr="${a[0]}">${a[2]} ${a[1]}</button>`).join("")}</div><div class="missionRewardRows">${selected.map(r=>{let a=ATTR.find(x=>x[0]===r.k);return`<div class="item"><b class="grow">${a?.[2]||"✦"} ${a?.[1]||r.k}</b><button type="button" class="pill" data-mission-minus="${r.k}">−</button><b>${r.n}</b><button type="button" class="pill" data-mission-plus="${r.k}">＋</button></div>`}).join("")}</div>`;box.querySelectorAll("[data-mission-attr]").forEach(b=>b.onclick=()=>{let i=selected.findIndex(x=>x.k===b.dataset.missionAttr);if(i>=0)selected.splice(i,1);else if(selected.reduce((s,x)=>s+x.n,0)<cap)selected.push({k:b.dataset.missionAttr,n:1});else return toast(`Limite de ${cap} ponto(s) para esta missão.`,"warn");drawRewards()});box.querySelectorAll("[data-mission-minus]").forEach(b=>b.onclick=()=>{let r=selected.find(x=>x.k===b.dataset.missionMinus);if(!r)return;r.n--;if(r.n<=0)selected=selected.filter(x=>x!==r);drawRewards()});box.querySelectorAll("[data-mission-plus]").forEach(b=>b.onclick=()=>{if(selected.reduce((s,x)=>s+x.n,0)>=cap)return toast(`Limite de ${cap} ponto(s) para esta missão.`,"warn");let r=selected.find(x=>x.k===b.dataset.missionPlus);if(r)r.n++;drawRewards()})};byId("missionRewardMode").onchange=drawRewards;["mt","md","mx","mmin"].forEach(k=>byId(k).addEventListener("input",drawRewards));drawRewards();byId("ms").onclick=()=>{let title=String(byId("mt")?.value||"").trim().slice(0,80),due=byId("mdu")?.value||"";if(!title)return toast("Informe o título da missão.","warn");if(!requireFutureDate(due,"O prazo da missão",existing?m.due:""))return;let mode=byId("missionRewardMode").value,obj={...m,title,desc:String(byId("md")?.value||"").trim().slice(0,400),due,subtasks:String(byId("missionSubtasks")?.value||"").split(/\n+/).map(x=>x.trim().slice(0,100)).filter(Boolean).slice(0,20).map(title=>(m.subtasks||[]).find(x=>x.title===title)||{id:id(),title,done:false}),xp:Math.max(10,Math.min(500,Number(byId("mx")?.value)||100)),estimatedMinutes:Math.max(5,Math.min(180,Number(byId("mmin")?.value)||30)),priority:Number(byId("missionPriority")?.value)||3,rewardMode:mode,attributeRewards:mode==="custom"?selected:[]};let cap=missionRewardCap(obj),total=obj.attributeRewards.reduce((s,x)=>s+Number(x.n||0),0);if(mode==="custom"&&!total)return toast("Escolha pelo menos um Status ou use a sugestão do sistema.","warn");if(total>cap)return toast(`Distribua no máximo ${cap} ponto(s) nesta missão.`,"warn");let idx=D.missions.findIndex(x=>sameId(x.id,obj.id));idx>=0?D.missions[idx]=obj:D.missions.push(obj);save();closeM();missionTab="open";nav="missions";render();setTimeout(()=>openMissionTarget(obj.id),60);toast(existing?"Missão atualizada.":"Missão criada.","success","Missão salva")}}
function missionV46(existing){missionEditor(existing||null)}

function inferGoalFromTitle(title,type){let s=String(title||"").toLocaleLowerCase("pt-BR"),n=Number((s.match(/(\d+(?:[.,]\d+)?)\s*(litro|l\b|ml\b|minuto|min\b|hora|h\b|página|pagina|páginas|paginas|pág\b|pag\b)/)||[])[1]?.replace(",","."));if(!n)return 0;if(/litro/.test(s)||type==="nutrition"&&/\bl\b/.test(s))return n*1000;return n}
function toolAmount(type,entry){if(type==="nutrition"&&entry.kind==="water")return Number(entry.ml||0);if(type==="study")return Number(entry.minutes||0);if(type==="reading")return Number(entry.pages||0);if(type==="organization")return Number(entry.minutes||0);if(type==="mood")return 1;if(type==="exercise")return Number(entry.minutes||0);if(type==="sleep")return Number(entry.hours||0);if(type==="appearance")return 1;return 0}
function toolKeywords(type){return{nutrition:["água","agua","hidrata","litro"],study:["estud","curso","aula"],reading:["leitura","ler","livro","página","pagina"],organization:["organiza","arrumar","limpar","planejar"],mood:["humor","energia","emoção","emocao","bem-estar"],exercise:["treino","exerc","caminh","corrida"],sleep:["sono","dorm"],appearance:["autocuidado","higiene","cabelo","pele"]}[type]||[]}
function toolLink(type,entry=null){D.toolSettings.links=D.toolSettings.links||{};let link=D.toolSettings.links[type],find=()=>{let words=toolKeywords(type),all=[...D.habits.filter(h=>!done(h)).map(h=>({targetType:"habit",target:h})),...D.missions.filter(m=>!m.done&&!m.expired).map(m=>({targetType:"mission",target:m}))];return all.find(x=>words.some(w=>String(x.target.title||"").toLocaleLowerCase("pt-BR").includes(w)))};if(link&&!linkedTarget(link)){delete D.toolSettings.links[type];link=null}if(!link&&entry){let auto=find();if(auto){let goal=inferGoalFromTitle(auto.target.title,type)||Number(D.toolSettings[type==="nutrition"?"waterGoal":type==="sleep"?"sleepGoal":""]||0)||toolAmount(type,entry);link={targetType:auto.targetType,targetId:auto.target.id,goal,unit:type==="nutrition"?"ml":type==="sleep"?"h":type==="appearance"?"rotina(s)":"min"};D.toolSettings.links[type]=link}}return link||null}
function linkedTarget(link){return link?.targetType==="habit"?D.habits.find(x=>sameId(x.id,link.targetId)):D.missions.find(x=>x.id===link?.targetId)}
function syncToolProgress(type,entry){let amount=toolAmount(type,entry);if(amount<=0)return null;let link=toolLink(type,entry),target=linkedTarget(link);if(!link||!target)return null;let day=iso();target.toolProgress=target.toolProgress||{};target.toolProgress[day]=Math.max(0,Number(target.toolProgress[day]||0)+amount);target.toolGoal=Math.max(1,Number(link.goal)||amount);target.toolUnit=link.unit||"";entry.linkedProgress={targetType:link.targetType,targetId:target.id,amount,day};if(target.toolProgress[day]>=target.toolGoal){if(link.targetType==="habit"&&!done(target,day)){target.autoCompletedByTool=target.autoCompletedByTool||{};target.autoCompletedByTool[day]=true;toggle(target.id,day)}else if(link.targetType==="mission"&&!target.done&&completeMission(target,true)){target.autoCompletedByTool=target.autoCompletedByTool||{};target.autoCompletedByTool[day]=true}}return{target,link,current:target.toolProgress[day]}}
function configureToolLink(type){let current=D.toolSettings.links?.[type],targets=[...D.habits.map(h=>({type:"habit",id:h.id,title:`Hábito • ${h.title}`})),...D.missions.filter(m=>!m.done&&!m.expired).map(m=>({type:"mission",id:m.id,title:`Missão • ${m.title}`}))],units={nutrition:"ml",study:"min",reading:"páginas",organization:"min",mood:"registro(s)",exercise:"min",sleep:"h",appearance:"rotina(s)"},defaultGoal=Number(current?.goal||(type==="nutrition"?D.toolSettings.waterGoal:type==="sleep"?D.toolSettings.sleepGoal:type==="reading"?D.toolSettings.readingDailyGoal:type==="organization"?D.toolSettings.organizationDailyGoal:30));modal(`<div class="mh"><div><h2>Vincular ferramenta</h2><p class="sub">Cada registro avançará o item escolhido. Ao atingir a meta, ele será concluído automaticamente uma única vez.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Hábito ou missão</label><select id="toolLinkTarget" class="field"><option value="">Sem vínculo</option>${targets.map(x=>`<option value="${x.type}:${x.id}" ${current?.targetType===x.type&&current?.targetId===x.id?"selected":""}>${esc(x.title)}</option>`).join("")}</select><div class="formGrid2"><div><label>Meta</label><input id="toolLinkGoal" class="field" type="number" min="0.1" step="0.1" value="${defaultGoal}"></div><div><label>Unidade</label><input id="toolLinkUnit" class="field" maxlength="20" value="${esc(current?.unit||units[type]||"")}"></div></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="toolLinkSave">Salvar vínculo</button></div></div>`);byId("toolLinkSave").onclick=()=>{let value=byId("toolLinkTarget").value;D.toolSettings.links=D.toolSettings.links||{};if(!value)delete D.toolSettings.links[type];else{let [targetType,targetId]=value.split(":"),goal=Math.max(.1,Number(byId("toolLinkGoal").value)||1);D.toolSettings.links[type]={targetType,targetId,goal,unit:String(byId("toolLinkUnit").value||"").trim().slice(0,20)}}save();closeM();render();toast(value?"Os próximos registros atualizarão o item escolhido.":"Vínculo removido.","success","Ferramenta configurada")}}
function toolsV46(){let base=tools(),names={study:"Estudos",nutrition:"Nutrição / água",appearance:"Autocuidado",exercise:"Exercícios",sleep:"Sono"};return base+`<div class="card toolLinkCenter"><div><span class="kicker">INTEGRAÇÃO COM SEU PLANO</span><h2>Ferramentas que avançam hábitos e missões</h2><p class="sub">Vincule cada ferramenta a um item. Exemplo: cada copo registrado soma ml ao hábito “Beber 2 litros de água”.</p></div><div class="toolLinkList">${Object.keys(names).map(type=>{let link=D.toolSettings.links?.[type],target=linkedTarget(link);return`<button data-tool-link="${type}"><span>${target?"✓":"＋"}</span><div><b>${names[type]}</b><small>${target?`Ligado a ${link.targetType==="habit"?"hábito":"missão"}: ${esc(target.title)} • meta ${link.goal} ${esc(link.unit||"")}`:"Escolher hábito ou missão"}</small></div></button>`}).join("")}</div></div>`}
function toolRecordV46(type,entry,attr,source){let record={id:id(),date:iso(),createdAt:new Date().toISOString(),attr,...entry};D.tools[type].unshift(record);D.tools[type]=D.tools[type].slice(0,500);if(attr)applyAttr(attr,1,source);let progress=syncToolProgress(type,record);evaluateTitles(true);save();if(progress)toast(`Progresso relacionado: ${progress.current}/${progress.target.toolGoal} ${progress.target.toolUnit||""}.`,"success",progress.target.title);return record}
function rollbackToolMission(m,day){if(!m?.autoCompletedByTool?.[day])return;let earned=Number(m.earnedXP||0);(m.earnedAttributes||[]).forEach(r=>undoAttr(r.k,Number(r.n)||0));m.done=false;m.completedAt="";m.earnedXP=0;m.earnedAttributes=[];delete m.autoCompletedByTool[day];D.totalXP=Math.max(0,D.totalXP-earned);D.history=D.history.filter(x=>!(sameId(x.missionId,m.id)&&x.date===day)&&!(x.type==="xp"&&x.rewardKey===`mission:${m.id}`));D.level=levelCalc().l}
function toolDeleteV46(type,recordId,reopen){let arr=D.tools[type]||[],record=arr.find(x=>x.id===recordId);if(!record)return;confirmDialog({title:"Excluir registro?",message:"Este item será removido do histórico da ferramenta.",description:record.linkedProgress?"O valor também será retirado do progresso do hábito ou missão vinculada.":"O registro será removido do histórico.",danger:true,confirmText:"Excluir",onConfirm:()=>{if(record.attr)undoAttr(record.attr,1);let lp=record.linkedProgress,target=lp?.targetType==="habit"?D.habits.find(x=>sameId(x.id,lp.targetId)):D.missions.find(x=>x.id===lp?.targetId);if(target&&lp){target.toolProgress=target.toolProgress||{};target.toolProgress[lp.day]=Math.max(0,Number(target.toolProgress[lp.day]||0)-Number(lp.amount||0));if(target.toolProgress[lp.day]<Number(target.toolGoal||0)&&target.autoCompletedByTool?.[lp.day]){if(lp.targetType==="habit"){toggle(target.id,lp.day);delete target.autoCompletedByTool[lp.day]}else rollbackToolMission(target,lp.day)}}D.tools[type]=arr.filter(x=>x.id!==recordId);save();reopen();toast("Registro e progresso relacionado foram atualizados.","info","Registros atualizados")}})}

function projectsV46(){let html=projects();D.projects.forEach(p=>{html=html.replace('<div class="card projectCard">',`<div class="card projectCard ${sameId(focusProjectId,p.id)?"focusItemHalo":""}" data-project-card="${p.id}">`)});return html}
function habitsV46(){let html=habits();D.habits.forEach(h=>{html=html.replace('<div class="card pr historyCard"><div class="historyInfo">',`<div class="card pr historyCard ${sameId(focusHabitId,h.id)?"focusItemHalo":""}" data-habit-card="${h.id}"><button class="iconAction habitHistoryEdit" data-edit-habit="${h.id}" title="Editar hábito">✎</button><div class="historyInfo habitHistoryOpen" data-open-habit="${h.id}" tabindex="0" role="button" title="Abrir e destacar este hábito">`)});return html}
function smartDailyPanel(){let s=todaySystemSummary(),date=new Intl.DateTimeFormat("pt-BR",{weekday:"long",day:"2-digit",month:"long"}).format(new Date()),rows=s.daily.map(m=>`<div class="dailyMissionMiniRow ${m.done?"done":""}"><div class="dailyRank rank-${missionRank(m).toLowerCase()}">${missionRank(m)}</div><div class="grow"><b>${esc(m.title)}</b><small>${esc(m.category||"Smart Daily")} • ⏱ ${missionMinutes(m)} min • ${m.xp} XP</small></div>${m.done?`<span class="dailyDone">✓ Concluída</span>`:`<div class="missionActions"><button class="pill" ${m.targetHabitId?`data-open-habit="${m.targetHabitId}"`:`data-open-mission="${m.id}"`}>${m.targetHabitId?"Abrir hábito":"Abrir missão"}</button><button class="pill" data-complete="${m.id}">Concluir</button></div>`}</div>`).join("");let projectRows=s.projects.map(p=>`<div class="dailyMissionMiniRow projectMini"><div class="dailyRank">◆</div><div class="grow"><b>${esc(p.title)}</b><small>Projeto • prazo ${p.due.split("-").reverse().join("/")}</small></div><button class="pill" data-open-project="${p.id}">Abrir projeto</button></div>`).join("");return`<div class="card smartDailyCard"><div class="smartDailyHead"><div><span class="kicker">SMART DAILY // HOJE</span><h2>Seu painel do dia</h2><p class="sub">${esc(date.charAt(0).toUpperCase()+date.slice(1))}</p></div><button class="pill" data-nav="missions">Abrir missões</button></div><div class="todayMetrics"><button ${s.firstPendingHabit?`data-open-habit="${s.firstPendingHabit.id}"`:`data-nav="habits"`}><span>✓</span><div><b>${s.habitPending}</b><small>hábitos pendentes</small></div></button><button data-nav="missions"><span>⚑</span><div><b>${s.dailyPending}</b><small>missões do dia</small></div></button><button data-nav="projects"><span>◆</span><div><b>${s.projects.length}</b><small>projetos com prazo</small></div></button><button data-nav="finance"><span>💰</span><div><b>${s.fin.length}</b><small>${s.fin.length?moneyBR(s.finAmount):"vencimentos próximos"}</small></div></button></div><div class="systemPriority"><span>PRIORIDADE DO SISTEMA</span><p>${esc(s.priority)}</p><small>XP disponível hoje: <b>${s.xpLeft}/500</b></small></div><div class="dailyMissionMini">${rows}${projectRows}</div></div>`}

const TRASH_TYPES={habit:["habits","Hábito"],mission:["missions","Missão"],project:["projects","Projeto"],page:["pages","Página"],expense:["finance.expenses","Despesa"],income:["finance.incomes","Receita"]};
function trashArray(type){let path=TRASH_TYPES[type]?.[0];if(!path)return null;return path.split(".").reduce((o,k)=>o?.[k],D)}
function moveToTrash(type,item){if(!item)return;D.trash=D.trash||[];D.trash.unshift({id:id(),type,item:JSON.parse(JSON.stringify(item)),deletedAt:new Date().toISOString()});D.trash=D.trash.filter(x=>Date.now()-new Date(x.deletedAt).getTime()<2592000000).slice(0,300)}
function restoreTrashItem(tid){let row=D.trash.find(x=>x.id===tid),arr=row&&trashArray(row.type);if(!row||!arr)return;let copy=JSON.parse(JSON.stringify(row.item));if(arr.some(x=>String(x.id)===String(copy.id)))copy.id=id();arr.push(copy);D.trash=D.trash.filter(x=>x.id!==tid);save();trashModal();toast(`${TRASH_TYPES[row.type]?.[1]||"Item"} restaurado.`,"success","Lixeira")}
function trashModal(){D.trash=D.trash.filter(x=>Date.now()-new Date(x.deletedAt||0).getTime()<2592000000);modal(`<div class="mh"><div><span class="kicker">RECUPERAÇÃO POR 30 DIAS</span><h2>Lixeira</h2><p class="sub">Itens excluídos podem ser restaurados antes da remoção automática.</p></div><button class="x" id="cx">×</button></div><div class="trashList">${D.trash.length?D.trash.map(x=>`<div class="item"><span class="trashIcon">⌫</span><div class="grow"><b>${esc(x.item?.title||x.item?.description||TRASH_TYPES[x.type]?.[1]||"Item")}</b><small>${esc(TRASH_TYPES[x.type]?.[1]||x.type)} • excluído em ${new Date(x.deletedAt).toLocaleString("pt-BR")}</small></div><button class="pill" data-trash-restore="${x.id}">Restaurar</button><button class="iconAction danger" data-trash-delete="${x.id}" title="Excluir definitivamente">×</button></div>`).join(""):`<div class="card sub">A lixeira está vazia.</div>`}</div>${D.trash.length?`<div class="modalActions"><button class="btn red" id="trashEmpty">Esvaziar lixeira</button></div>`:""}`);document.querySelectorAll("[data-trash-restore]").forEach(b=>b.onclick=()=>restoreTrashItem(b.dataset.trashRestore));document.querySelectorAll("[data-trash-delete]").forEach(b=>b.onclick=()=>confirmDialog({title:"Excluir definitivamente?",message:"Este item não poderá ser restaurado.",danger:true,confirmText:"Excluir definitivamente",onConfirm:()=>{D.trash=D.trash.filter(x=>x.id!==b.dataset.trashDelete);save();trashModal()}}));if(byId("trashEmpty"))byId("trashEmpty").onclick=()=>confirmDialog({title:"Esvaziar lixeira?",message:"Todos os itens serão excluídos definitivamente.",danger:true,confirmText:"Esvaziar",onConfirm:()=>{D.trash=[];save();trashModal()}})}

function weekStart(date=new Date()){let d=new Date(date),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);d.setHours(12,0,0,0);return d}
function agendaDates(){let start=weekStart(),dates=Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return d}),todayIndex=dates.findIndex(d=>iso(d)===iso());return todayIndex>0?[...dates.slice(todayIndex),...dates.slice(0,todayIndex)]:dates}
function agendaEntries(date){let ds=iso(date),entries=[];D.habits.filter(h=>!rest(h,ds)).forEach(h=>entries.push({type:"habit",id:h.id,title:h.title,time:h.agendaTimes?.[ds]||reminderTimes(h)[0]||"",done:done(h,ds)}));D.missions.filter(m=>!m.done&&!m.expired&&(m.scheduleDate||m.due||iso())===ds).forEach(m=>entries.push({type:"mission",id:m.id,title:m.title,time:m.scheduleTime||"",done:m.done}));D.projects.filter(p=>!p.done&&(p.scheduleDate||p.due||"")===ds).forEach(p=>entries.push({type:"project",id:p.id,title:p.title,time:p.scheduleTime||"",done:p.done}));return entries.sort((a,b)=>String(a.time||"99:99").localeCompare(String(b.time||"99:99")))}
function agenda(){let dates=agendaDates();return header("Agenda semanal","Hoje aparece primeiro; os dias anteriores ficam ao final da semana",`<button class="pill" data-week-review>✦ Revisão semanal</button>`)+`<div class="agendaWeek">${dates.map(d=>{let ds=iso(d),items=agendaEntries(d);return`<section class="agendaDay ${ds===iso()?"today":""}" data-agenda-day="${ds}"><div class="agendaDayHead"><small>${d.toLocaleDateString("pt-BR",{weekday:"short"}).replace(".","").toUpperCase()}</small><b>${d.getDate()}</b></div><div class="agendaDrop">${items.length?items.map(x=>{let open=x.type==="habit"?`data-open-habit="${x.id}"`:x.type==="mission"?`data-open-mission="${x.id}"`:`data-open-project="${x.id}"`;return`<div class="agendaItem ${x.done?"done":""}" draggable="true" data-agenda-item="${x.type}:${x.id}" data-agenda-date="${ds}"><button class="agendaItemOpen" ${open}><span>${x.time||"—"}</span><b>${esc(x.title)}</b><small>${x.type==="habit"?"Hábito":x.type==="mission"?"Missão":"Projeto"} • toque para abrir</small></button><button class="agendaSchedule" data-agenda-edit="${x.type}:${x.id}:${ds}" title="Editar data, horário e lembrete">◷</button></div>`}).join(""):`<span class="agendaEmpty">Solte um item aqui</span>`}</div></section>`}).join("")}</div><div class="card agendaHelp"><b>Como organizar</b><p>Toque no nome para abrir e destacar o item. Use o botão de relógio para editar data, horário e lembrete. No computador, você também pode arrastar entre os dias.</p></div>`}
function agendaTarget(type,id){return type==="habit"?D.habits.find(x=>sameId(x.id,id)):type==="mission"?D.missions.find(x=>sameId(x.id,id)):D.projects.find(x=>sameId(x.id,id))}
function agendaItemModal(type,id,date=""){let target=agendaTarget(type,id);if(!target)return;let currentDate=date||target.scheduleDate||target.due||iso(),time=type==="habit"?(target.agendaTimes?.[currentDate]||reminderTimes(target)[0]||""):(target.scheduleTime||"");modal(`<div class="mh"><div><h2>Agendar item</h2><p class="sub">${esc(target.title)}</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Data</label><input id="agendaDate" class="field" type="date" value="${currentDate}"><label>Horário</label><input id="agendaTime" class="field" type="time" value="${time}"><label class="settingRow"><span><b>Criar lembrete</b><small class="sub">Disponível no APK Android.</small></span><input id="agendaNotify" type="checkbox" ${target.agendaNotify?"checked":""}></label><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="agendaSave">Salvar agenda</button></div></div>`);byId("agendaSave").onclick=async()=>{let ds=byId("agendaDate").value||iso(),tm=byId("agendaTime").value||"";if(type==="habit"){target.agendaTimes=target.agendaTimes||{};target.agendaTimes[ds]=tm;if(byId("agendaNotify").checked&&tm){target.reminder={enabled:true,times:[...new Set([...(target.reminder?.times||[]),tm])]};await syncHabitNotifications(target,false)}}else{target.scheduleDate=ds;target.scheduleTime=tm}target.agendaNotify=byId("agendaNotify").checked;save();closeM();render();toast("Item posicionado na agenda.","success","Agenda atualizada")}}

function automationSourceLabel(type){return{study:"Estudo",reading:"Leitura",nutrition:"Água",organization:"Organização",mood:"Humor e energia",appearance:"Autocuidado",exercise:"Exercício",sleep:"Sono"}[type]||type}
function automationModal(existing=null){let a=existing||{id:id(),sourceType:"nutrition",targetType:"habit",targetId:"",goal:2000,unit:"ml",active:true},targets=[...D.habits.map(h=>({type:"habit",id:h.id,title:`Hábito • ${h.title}`})),...D.missions.filter(m=>!m.done&&!m.expired).map(m=>({type:"mission",id:m.id,title:`Missão • ${m.title}`}))];modal(`<div class="mh"><div><h2>${existing?"Editar":"Nova"} automação</h2><p class="sub">Registros concedem +1 no Status correspondente, até 3 por dia, e também podem atualizar o item escolhido.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Quando eu registrar</label><select id="autoSource" class="field">${["nutrition","reading","study","organization","mood","exercise","sleep","appearance"].map(x=>`<option value="${x}" ${a.sourceType===x?"selected":""}>${automationSourceLabel(x)}</option>`).join("")}</select><label>Atualizar</label><select id="autoTarget" class="field"><option value="">Escolha um item</option>${targets.map(x=>`<option value="${x.type}:${x.id}" ${a.targetType===x.type&&a.targetId===x.id?"selected":""}>${esc(x.title)}</option>`).join("")}</select><div class="formGrid2"><div><label>Meta para concluir</label><input id="autoGoal" class="field" type="number" min="0.1" step="0.1" value="${Number(a.goal||1)}"></div><div><label>Unidade</label><input id="autoUnit" class="field" maxlength="20" value="${esc(a.unit||"")}"></div></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="autoSave">Salvar automação</button></div></div>`);byId("autoSave").onclick=()=>{let target=byId("autoTarget").value;if(!target)return toast("Escolha um hábito ou missão.","warn");let[targetType,targetId]=target.split(":"),obj={...a,sourceType:byId("autoSource").value,targetType,targetId,goal:Math.max(.1,Number(byId("autoGoal").value)||1),unit:String(byId("autoUnit").value||"").trim().slice(0,20),active:true},idx=D.automations.findIndex(x=>x.id===obj.id);idx>=0?D.automations[idx]=obj:D.automations.push(obj);save();closeM();render();toast("Automação pronta. O registro seguirá o limite diário de Status e atualizará o item escolhido.","success","Automação salva")}}
function applyAutomation(rule,entry){let target=agendaTarget(rule.targetType,rule.targetId),amount=toolAmount(rule.sourceType,entry);if(!target||amount<=0)return null;let day=iso();target.toolProgress=target.toolProgress||{};target.toolProgress[day]=Math.max(0,Number(target.toolProgress[day]||0)+amount);target.toolGoal=Number(rule.goal)||amount;target.toolUnit=rule.unit||"";entry.automationProgress=entry.automationProgress||[];entry.automationProgress.push({ruleId:rule.id,targetType:rule.targetType,targetId:target.id,amount,day});if(target.toolProgress[day]>=target.toolGoal){if(rule.targetType==="habit"&&!done(target,day)){target.autoCompletedByTool=target.autoCompletedByTool||{};target.autoCompletedByTool[day]=true;toggle(target.id,day)}if(rule.targetType==="mission"&&!target.done&&completeMission(target,true)){target.autoCompletedByTool=target.autoCompletedByTool||{};target.autoCompletedByTool[day]=true}}return target}
function toolRecordV47(type,entry,attr,source){let record={id:id(),date:iso(),createdAt:new Date().toISOString(),...entry};D.tools[type].unshift(record);D.tools[type]=D.tools[type].slice(0,500);let rules=D.automations.filter(a=>a.active&&a.sourceType===type),targets=rules.map(a=>applyAutomation(a,record)).filter(Boolean);if(!rules.length){let legacy=syncToolProgress(type,record);if(legacy)targets.push(legacy.target)}save();if(targets.length)toast(`Progresso atualizado em ${targets.length} item(ns).`,"success","Automação executada");else toast("Registro salvo sem conceder XP ou Status.","success","Ferramenta atualizada");return record}
function toolDeleteV47(type,recordId,reopen){let arr=D.tools[type]||[],record=arr.find(x=>x.id===recordId);if(!record)return;confirmDialog({title:"Excluir registro?",message:"O registro será removido e o progresso das automações será recalculado.",danger:true,confirmText:"Excluir registro",onConfirm:()=>{let links=[...(record.automationProgress||[]),...(record.linkedProgress?[record.linkedProgress]:[])];links.forEach(lp=>{let target=agendaTarget(lp.targetType,lp.targetId);if(!target)return;target.toolProgress=target.toolProgress||{};target.toolProgress[lp.day]=Math.max(0,Number(target.toolProgress[lp.day]||0)-Number(lp.amount||0));if(target.toolProgress[lp.day]<Number(target.toolGoal||0)&&target.autoCompletedByTool?.[lp.day]){if(lp.targetType==="habit"&&done(target,lp.day)){toggle(target.id,lp.day);delete target.autoCompletedByTool[lp.day]}else if(lp.targetType==="mission")rollbackToolMission(target,lp.day)}});D.tools[type]=arr.filter(x=>x.id!==recordId);save();reopen();toast("Registro e progresso removidos.","info","Automação recalculada")}})}
function toolsV47(){let base=toolsV46().replace(/<div class="card toolLinkCenter">[\s\S]*$/,""),items=D.automations||[];base=base.replace("<h1 class=\"title\">Ferramentas<\/h1>","<h1 class=\"title\">Registros & Automações<\/h1>").replace("Recursos práticos para registrar, acompanhar e evoluir","Utilidades sem pontos artificiais; progresso somente quando ligado ao seu plano");return base+`<div class="card automationCenter"><div class="row between"><div><span class="kicker">REGRAS PERSONALIZADAS</span><h2>Automações</h2><p class="sub">Ex.: registrar 300 ml soma 300 ml ao hábito de beber água. O registro sozinho não aumenta Vitalidade, Força ou outros Status.</p></div><button class="btn" data-new-automation>＋ Automação</button></div><div class="automationList">${items.length?items.map(a=>{let t=agendaTarget(a.targetType,a.targetId);return`<div class="item"><span class="automationArrow">${a.active?"↳":"Ⅱ"}</span><div class="grow"><b>${automationSourceLabel(a.sourceType)} → ${esc(t?.title||"Item removido")}</b><small>Concluir em ${a.goal} ${esc(a.unit||"")} • ${a.active?"ativa":"pausada"}</small></div><button class="pill" data-auto-toggle="${a.id}">${a.active?"Pausar":"Ativar"}</button><button class="iconAction" data-auto-edit="${a.id}">✎</button><button class="iconAction danger" data-auto-delete="${a.id}">×</button></div>`}).join(""):`<div class="sub">Nenhuma automação criada. As ferramentas continuarão apenas registrando informações.</div>`}</div></div>`}

function projectPctV47(p){if(Array.isArray(p.subtasks)&&p.subtasks.length)return p.subtasks.filter(x=>x.done).length/p.subtasks.length*100;let target=Number(p.target||0),current=Number(p.current||0);if((p.type==="money"||p.type==="count")&&target>0)return Math.max(0,Math.min(100,current/target*100));return Math.max(0,Math.min(100,Number(p.progress||0)))}
function projectsV47(){let html=projectsV46();D.projects.forEach(p=>{let subtasks=Array.isArray(p.subtasks)?p.subtasks:[],block=`<div class="projectSubtasks"><div class="row between"><b>Etapas e marcos</b><button class="link" data-subtask-add="${p.id}">＋ Etapa</button></div>${subtasks.length?subtasks.map(s=>`<div class="projectSubtask ${s.done?"done":""}"><button data-subtask-toggle="${p.id}:${s.id}">${s.done?"✓":""}</button><span>${esc(s.title)}</span><button class="iconAction" data-subtask-edit="${p.id}:${s.id}">✎</button><button class="iconAction danger" data-subtask-delete="${p.id}:${s.id}">×</button></div>`).join(""):`<small class="sub">Adicione etapas para calcular o progresso automaticamente.</small>`}</div>`;html=html.replace('<div class="projectActions">',block+'<div class="projectActions">')});return html}
function subtaskModal(project,subtask=null){let s=subtask||{id:id(),title:"",done:false};modal(`<div class="mh"><div><h2>${subtask?"Editar":"Nova"} etapa</h2><p class="sub">${esc(project.title)}</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Descrição da etapa</label><input id="subtaskTitle" class="field" maxlength="100" value="${esc(s.title)}" placeholder="Ex.: Concluir a primeira aula"><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="subtaskSave">Salvar etapa</button></div></div>`);byId("subtaskSave").onclick=()=>{let title=String(byId("subtaskTitle").value||"").trim().slice(0,100);if(!title)return toast("Informe a etapa.","warn");project.subtasks=project.subtasks||[];let idx=project.subtasks.findIndex(x=>x.id===s.id),obj={...s,title};idx>=0?project.subtasks[idx]=obj:project.subtasks.push(obj);project.progress=projectPctV47(project);project.done=project.progress>=100;save();closeM();render()}}

function weeklyReviewModal(){let m=weeklyMetrics(),dates=Array.from({length:7},(_,i)=>addDaysISO(-i)),dateSet=new Set(dates),open=D.missions.filter(x=>!x.done&&!x.expired).length,done7=D.missions.filter(x=>x.done&&missionCompletionISO(x)&&Date.now()-new Date(missionCompletionISO(x)).getTime()<604800000).length,habitDone=D.history.filter(x=>x.type==="habit_done"&&dateSet.has(x.date)).length,waterDays=new Set((D.tools.nutrition||[]).filter(x=>x.kind==="water"&&dateSet.has(x.date)).map(x=>x.date)).size,readingPages=(D.tools.reading||[]).filter(x=>dateSet.has(x.date)).reduce((s,x)=>s+Number(x.pages||0),0),weekStartDate=dates[6],spent=(D.finance.expenses||[]).filter(x=>{let d=String(x.paid_date||x.due_date||"").slice(0,10);return d>=weekStartDate&&d<=dates[0]}).reduce((s,x)=>s+Number(x.amount||0),0),rate=done7+open?Math.round(done7/(done7+open)*100):0;modal(`<div class="mh"><div><span class="kicker">ÚLTIMOS 7 DIAS</span><h2>Revisão semanal automática</h2><p class="sub">Resumo local criado a partir dos registros do Smart Life.</p></div><button class="x" id="cx">×</button></div><div class="reviewMetrics reviewMetricsExpanded"><div><b>${rate}%</b><span>missões concluídas</span></div><div><b>${waterDays}/7</b><span>dias com água</span></div><div><b>${readingPages}</b><span>páginas lidas</span></div><div><b>${habitDone}</b><span>hábitos concluídos</span></div><div><b>${m.xp||0}</b><span>XP</span></div><div><b>${moneyBR(spent)}</b><span>gastos registrados</span></div></div><div class="card reviewInsight"><h3>${done7||habitDone||readingPages?"Você construiu progresso nesta semana":"Semana com pouco registro"}</h3><p>${readingPages?`Leitura: ${readingPages} páginas. `:""}${waterDays?`Hidratação registrada em ${waterDays} de 7 dias. `:""}${rate?`Taxa de missões: ${rate}%. `:""}Escolha um resultado para proteger na próxima semana.</p></div><div class="modalActions"><button class="pill" data-close>Fechar</button>${aiConfig().apiKey?`<button class="btn" id="reviewWithAi">Aprofundar com Gemini</button>`:""}</div>`);if(byId("reviewWithAi"))byId("reviewWithAi").onclick=()=>{closeM();aiWeeklyReview()}}

function globalSearchResults(q){q=String(q||"").trim().toLocaleLowerCase("pt-BR");if(!q)return[];let out=[];D.habits.forEach(x=>{if(`${x.title} ${x.desc||""}`.toLocaleLowerCase("pt-BR").includes(q))out.push({type:"habit",id:x.id,title:x.title,sub:"Hábito"})});D.missions.forEach(x=>{if(`${x.title} ${x.desc||""}`.toLocaleLowerCase("pt-BR").includes(q))out.push({type:"mission",id:x.id,title:x.title,sub:x.done?"Missão concluída":"Missão"})});D.projects.forEach(x=>{if(`${x.title} ${x.desc||""}`.toLocaleLowerCase("pt-BR").includes(q))out.push({type:"project",id:x.id,title:x.title,sub:"Projeto"})});D.pages.forEach(x=>{if(`${x.title} ${x.content||""}`.toLocaleLowerCase("pt-BR").includes(q))out.push({type:"page",id:x.id,title:x.title||"Sem título",sub:"Organização"})});let recordTypes={study:"Estudo",reading:"Leitura",nutrition:"Nutrição",organization:"Organização",mood:"Humor",appearance:"Autocuidado",exercise:"Exercício",sleep:"Sono",weight:"Peso",gratitude:"Gratidão",notes:"Nota"};Object.entries(recordTypes).forEach(([type,label])=>(D.tools[type]||[]).forEach(x=>{let text=[x.book,x.subject,x.meal,x.action,x.area,x.note,x.text,x.type,x.period,x.kg,x.pages,x.minutes].filter(v=>v!==undefined&&v!=="").join(" ");if(text.toLocaleLowerCase("pt-BR").includes(q))out.push({type:`record-${type}`,id:x.id,title:String(x.book||x.subject||x.meal||x.action||x.text||x.type||`${label}${x.kg?` • ${x.kg} kg`:""}`),sub:`Registro • ${label}`})}));[...(D.finance.expenses||[]),...(D.finance.incomes||[])].forEach(x=>{if(String(x.description||"").toLocaleLowerCase("pt-BR").includes(q))out.push({type:"finance",id:x.id,title:x.description,sub:"Finanças"})});return out.slice(0,40)}
function openSearchResult(type,id){closeM();if(type==="habit")return openHabitTarget(id);if(type==="mission")return openMissionTarget(id);if(type==="project")return openProjectTarget(id);if(type==="page"){D.activePage=id;nav="organize";render();return}if(type==="finance"){nav="finance";financeTab="expenses";render();return}if(type.startsWith("record-")){nav="tools";render();setTimeout(()=>tool(type.slice(7)),40)}}
function globalSearchModal(){modal(`<div class="mh"><div><span class="kicker">BUSCA GLOBAL</span><h2>Encontrar no Smart Life</h2></div><button class="x" id="cx">×</button></div><input id="globalSearchInput" class="field globalSearchInput" maxlength="100" placeholder="Buscar hábitos, missões, registros, notas, páginas e finanças..."><div id="globalSearchResults" class="globalSearchResults"><p class="sub">Digite para pesquisar em todos os módulos.</p></div>`);let input=byId("globalSearchInput"),box=byId("globalSearchResults");input.oninput=()=>{let list=globalSearchResults(input.value);box.innerHTML=list.length?list.map(x=>`<button data-search-open="${x.type}:${x.id}"><span>${x.type==="habit"?"✓":x.type==="mission"?"⚑":x.type==="project"?"◆":x.type==="page"?"▦":x.type.startsWith("record-")?"＋":"▣"}</span><div><b>${esc(x.title)}</b><small>${x.sub}</small></div></button>`).join(""):`<p class="sub">Nenhum resultado encontrado.</p>`;box.querySelectorAll("[data-search-open]").forEach(b=>b.onclick=()=>{let[type,id]=b.dataset.searchOpen.split(":");openSearchResult(type,id)})};setTimeout(()=>input.focus(),50)}
function todayCardKeys(){let valid=["missions","habits","records","finance"],saved=Array.isArray(D.settings.todayCards)?D.settings.todayCards.filter(x=>valid.includes(x)):[];return[...saved,...valid.filter(x=>!saved.includes(x))]}
function todayDashboard(){let pendingMissions=D.missions.filter(m=>!m.done&&!m.expired&&(m.due===iso()||m.scheduleDate===iso())).length,pendingHabits=D.habits.filter(h=>!rest(h)&&!done(h)).length,water=toolToday("nutrition").filter(x=>x.kind==="water").reduce((s,x)=>s+Number(x.ml||0),0),pages=toolToday("reading").reduce((s,x)=>s+Number(x.pages||0),0),month=financeMonth(),expenses=(D.finance.expenses||[]).filter(x=>String(x.due_date||x.paid_date||"").slice(0,7)===month).reduce((s,x)=>s+Number(x.amount||0),0),income=(D.finance.incomes||[]).filter(x=>String(x.expected_date||x.received_date||"").slice(0,7)===month).reduce((s,x)=>s+Number(x.amount_expected||x.amount_received||0),0),cards={missions:`<button data-nav="missions"><span>⚑</span><b>${pendingMissions}</b><small>missões de hoje</small></button>`,habits:`<button data-nav="habits"><span>✓</span><b>${pendingHabits}</b><small>hábitos pendentes</small></button>`,records:`<button data-act="quickAdd"><span>＋</span><b>${water} ml • ${pages} pág.</b><small>registros de hoje</small></button>`,finance:`<button data-nav="finance"><span>▣</span><b>${moneyBR(income-expenses)}</b><small>saldo previsto do mês</small></button>`},visible=todayCardKeys().filter(x=>(D.settings.todayCards||[]).includes(x));return`<section class="todayCommand card"><div class="row between"><div><span class="kicker">HOJE // ACESSO CENTRAL</span><h2>Seu dia em um só lugar</h2></div><button class="pill" data-today-customize>⚙ Cards</button></div><div class="todayCommandGrid">${visible.map(x=>cards[x]).join("")}</div><div class="todayQuickStrip"><button data-quick-direct="water">💧 +250 ml</button><button data-tool="reading">📖 Leitura</button><button data-quick-direct="note">✎ Nota</button><button data-quick-direct="finance">💰 Lançamento</button><button data-act="quickAdd">＋ Mais</button></div></section>`}
function homeV53(){let base=home(),marker='<div class="card homeStreakCard';return base.includes(marker)?base.replace(marker,todayDashboard()+marker):todayDashboard()+base}
function customizeTodayModal(){let labels={missions:["⚑","Missões"],habits:["✓","Hábitos"],records:["＋","Registros"],finance:["▣","Finanças"]},order=todayCardKeys();modal(`<div class="mh"><div><h2>Personalizar a tela Hoje</h2><p class="sub">Escolha os cards e use as setas para definir a ordem.</p></div><button class="x" id="cx">×</button></div><div id="todayCardEditor" class="todayCardEditor"></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="todayCardsSave">Salvar painel</button></div>`);let draw=()=>{let box=byId("todayCardEditor"),enabled=new Set(D.settings.todayCards||[]);box.innerHTML=order.map((k,i)=>`<div class="item"><label class="grow"><input type="checkbox" data-today-card="${k}" ${enabled.has(k)?"checked":""}> ${labels[k][0]} <b>${labels[k][1]}</b></label><button class="pill" data-card-up="${k}" ${i===0?"disabled":""}>↑</button><button class="pill" data-card-down="${k}" ${i===order.length-1?"disabled":""}>↓</button></div>`).join("");box.querySelectorAll("[data-card-up]").forEach(b=>b.onclick=()=>{let i=order.indexOf(b.dataset.cardUp);[order[i-1],order[i]]=[order[i],order[i-1]];draw()});box.querySelectorAll("[data-card-down]").forEach(b=>b.onclick=()=>{let i=order.indexOf(b.dataset.cardDown);[order[i+1],order[i]]=[order[i],order[i+1]];draw()})};draw();byId("todayCardsSave").onclick=()=>{let enabled=new Set([...document.querySelectorAll("[data-today-card]:checked")].map(x=>x.dataset.todayCard));D.settings.todayCards=order.filter(x=>enabled.has(x));if(!D.settings.todayCards.length)D.settings.todayCards=["missions"];save();closeM();render();toast("A tela Hoje foi personalizada.","success","Painel atualizado")}}
function contextualNotices(){let a=[];D.missions.forEach(m=>{if(m.done||m.expired||!m.due)return;let d=daysUntil(m.due);if(d<0)a.push({k:"danger",nav:"missions",type:"mission",id:m.id,t:"Missão atrasada",s:`${m.title} • venceu ${m.due.split("-").reverse().join("/")}`});else if(d<=2)a.push({k:"warn",nav:"missions",type:"mission",id:m.id,t:d===0?"Missão vence hoje":"Missão perto do prazo",s:`${m.title} • ${d===0?"hoje":d+" dia(s)"}`})});D.projects.forEach(p=>{if(p.done||!p.due)return;let d=daysUntil(p.due);if(d<0)a.push({k:"danger",nav:"projects",type:"project",id:p.id,t:"Projeto atrasado",s:`${p.title} • prazo vencido`});else if(d<=7)a.push({k:"warn",nav:"projects",type:"project",id:p.id,t:d===0?"Projeto vence hoje":"Prazo de projeto próximo",s:`${p.title} • ${d===0?"hoje":d+" dia(s)"}`})});let owner=financeOwnerId();D.finance.expenses.filter(e=>financeOwn(e,owner)&&String(e.status||"pending")!=="paid"&&e.due_date).forEach(e=>{let d=daysUntil(String(e.due_date).slice(0,10));if(d<0)a.push({k:"danger",nav:"finance",t:"Despesa vencida",s:`${e.description} • ${moneyBR(e.amount)}`});else if(d<=2)a.push({k:"warn",nav:"finance",t:d===0?"Despesa vence hoje":"Despesa perto do vencimento",s:`${e.description} • ${moneyBR(e.amount)}`})});return a.slice(0,20)}
function renderTopUIV51(){updateGreeting();let list=contextualNotices(),b=document.querySelector("#notifyBadge"),nl=document.querySelector("#notifyList"),tg=document.querySelector("#topThemes");if(b){b.textContent=list.length>9?"9+":list.length;b.classList.toggle("zero",!list.length)}if(nl)nl.innerHTML=list.length?list.map(n=>`<button class="notifyItem ${n.k}" data-notice-nav="${n.nav}" ${n.type&&n.id!==undefined?`data-notice-type="${n.type}" data-notice-id="${n.id}"`:""}><b>${esc(n.t)}</b><small>${esc(n.s)}</small></button>`).join(""):`<div class="notifyEmpty">Nada urgente por enquanto.</div>`;if(tg)tg.innerHTML=themeList().map(x=>`<button class="topTheme ${D.profile.theme===x[0]?"sel":""}" data-theme-choice="${x[0]}" style="background:${x[2]}"><span>${x[1]}</span></button>`).join("")}

function cloudCfg(){return D.settings.cloud=Object.assign({enabled:false,url:"",anonKey:"",syncId:"",passphrase:"",lastSync:"",autoSync:false},D.settings.cloud||{})}
function randomSyncId(){let a=new Uint8Array(18);crypto.getRandomValues(a);return[...a].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function deriveCloudKey(pass,salt){let raw=await crypto.subtle.importKey("raw",new TextEncoder().encode(pass),"PBKDF2",false,["deriveKey"]);return crypto.subtle.deriveKey({name:"PBKDF2",salt:new TextEncoder().encode(salt),iterations:180000,hash:"SHA-256"},raw,{name:"AES-GCM",length:256},false,["encrypt","decrypt"])}
function b64(bytes){let out="";for(let i=0;i<bytes.length;i+=32768)out+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(out)}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function cloudEncrypt(data,cfg){let iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveCloudKey(cfg.passphrase,cfg.syncId),cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,new TextEncoder().encode(JSON.stringify(data)));return JSON.stringify({v:1,iv:b64(iv),data:b64(new Uint8Array(cipher))})}
async function cloudDecrypt(blob,cfg){let p=JSON.parse(blob),key=await deriveCloudKey(cfg.passphrase,cfg.syncId),plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:unb64(p.iv)},key,unb64(p.data));return JSON.parse(new TextDecoder().decode(plain))}
function cloudHeaders(cfg){return{"Content-Type":"application/json",apikey:cfg.anonKey,Authorization:`Bearer ${cfg.anonKey}`}}
function safeCloudState(){let data=JSON.parse(JSON.stringify(D));data.settings.ai.apiKey="";data.settings.cloud={enabled:false,url:"",anonKey:"",syncId:"",passphrase:"",lastSync:"",autoSync:false};return data}
async function cloudPush(show=true){let cfg=cloudCfg();if(!cfg.enabled||!cfg.url||!cfg.anonKey||!cfg.syncId||!cfg.passphrase)throw new Error("Configure a sincronização antes de enviar.");let payload=await cloudEncrypt(safeCloudState(),cfg),res=await fetch(`${cfg.url.replace(/\/$/,"")}/rest/v1/smart_life_sync?on_conflict=sync_id`,{method:"POST",headers:{...cloudHeaders(cfg),Prefer:"resolution=merge-duplicates"},body:JSON.stringify({sync_id:cfg.syncId,payload,updated_at:new Date().toISOString()})});if(!res.ok)throw new Error(`Falha ao enviar (${res.status}). Confira a tabela e as chaves.`);cfg.lastSync=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(D));if(show)toast("Dados criptografados enviados para a nuvem.","success","Sincronização concluída")}
async function cloudPull(){let cfg=cloudCfg();if(!cfg.enabled||!cfg.url||!cfg.anonKey||!cfg.syncId||!cfg.passphrase)throw new Error("Configure a sincronização antes de baixar.");let res=await fetch(`${cfg.url.replace(/\/$/,"")}/rest/v1/smart_life_sync?sync_id=eq.${encodeURIComponent(cfg.syncId)}&select=payload&limit=1`,{headers:cloudHeaders(cfg)});if(!res.ok)throw new Error(`Falha ao baixar (${res.status}).`);let rows=await res.json();if(!rows?.[0]?.payload)throw new Error("Nenhum backup online foi encontrado para este código.");let localAi=aiConfig().apiKey,localCloud={...cfg},data=await cloudDecrypt(rows[0].payload,cfg);D=normalizeState(data,false);D.settings.ai.apiKey=localAi;D.settings.cloud=localCloud;save();closeM();render();toast("Dados online restaurados neste dispositivo.","success","Sincronização concluída")}
let cloudSyncTimer=0;function scheduleCloudSync(){let cfg=cloudCfg();if(!cfg.enabled||!cfg.autoSync)return;clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>cloudPush(false).catch(e=>console.warn("Sincronização automática",e)),5000)}
function cloudModal(){let c=cloudCfg();if(!c.syncId)c.syncId=randomSyncId();modal(`<div class="mh"><div><span class="kicker">SINCRONIZAÇÃO CRIPTOGRAFADA</span><h2>Smart Life Online</h2><p class="sub">Use um projeto Supabase próprio. O conteúdo é criptografado antes de sair do aparelho.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>URL do projeto Supabase</label><input id="cloudUrl" class="field" value="${esc(c.url)}" placeholder="https://seu-projeto.supabase.co"><label>Chave anon/publishable</label><input id="cloudAnonKey" class="field" type="password" value="${esc(c.anonKey)}"><label>Código de sincronização</label><input id="cloudId" class="field" value="${esc(c.syncId)}"><label>Frase secreta de criptografia</label><input id="cloudPass" class="field" type="password" value="${esc(c.passphrase)}" placeholder="Use a mesma frase no PC e celular"><label class="settingRow"><span><b>Sincronizar automaticamente</b><small class="sub">Envia alterações alguns segundos após salvar.</small></span><input id="cloudAuto" type="checkbox" ${c.autoSync?"checked":""}></label><div class="modalActions"><button class="pill" id="cloudSave">Salvar configuração</button><button class="pill" id="cloudPull">Baixar da nuvem</button><button class="btn" id="cloudPush">Enviar agora</button></div><p class="sub">A frase secreta nunca é enviada ao servidor. Se esquecê-la, o conteúdo online não poderá ser aberto.</p></div>`);let persist=()=>{let next={enabled:true,url:byId("cloudUrl").value.trim(),anonKey:byId("cloudAnonKey").value.trim(),syncId:byId("cloudId").value.trim(),passphrase:byId("cloudPass").value,autoSync:byId("cloudAuto").checked,lastSync:c.lastSync||""};if(!next.url||!next.anonKey||!next.syncId||next.passphrase.length<8)throw new Error("Preencha URL, chave, código e uma frase secreta com pelo menos 8 caracteres.");D.settings.cloud=next;localStorage.setItem(KEY,JSON.stringify(D));return next};byId("cloudSave").onclick=()=>{try{persist();toast("Configuração online salva somente neste dispositivo.","success")}catch(e){toast(e.message,"warn")}};byId("cloudPush").onclick=async()=>{try{persist();await cloudPush(true)}catch(e){toast(e.message,"error","Sincronização falhou")}};byId("cloudPull").onclick=async()=>{try{persist();await cloudPull()}catch(e){toast(e.message,"error","Sincronização falhou")}}}

function notificationCenterModal(){let cfg=D.settings.notifications||{},list=cfg.dueAlerts===false?[]:notices();modal(`<div class="mh"><div><span class="kicker">CENTRAL DE ALERTAS</span><h2>Notificações</h2><p class="sub">Pendências, vencimentos e lembretes configurados.</p></div><button class="x" id="cx">×</button></div><div class="card notificationPreferences"><label class="settingRow"><span><b>Resumo diário às 20h</b><small class="sub">Mostra hábitos, missões e compromissos.</small></span><input id="dailySummaryToggle" type="checkbox" ${cfg.dailySummary!==false?"checked":""}></label><label class="settingRow"><span><b>Alertas de vencimento</b><small class="sub">Mantém pendências e contas na central.</small></span><input id="dueAlertsToggle" type="checkbox" ${cfg.dueAlerts!==false?"checked":""}></label><div class="formGrid2"><div><label>Silenciar a partir de</label><input id="quietStart" class="field" type="time" value="${esc(cfg.quietStart||"22:00")}"></div><div><label>Reativar às</label><input id="quietEnd" class="field" type="time" value="${esc(cfg.quietEnd||"07:00")}"></div></div><button class="pill" id="notificationPreferencesSave">Salvar preferências</button></div><div class="notificationCenterList">${list.length?list.map((n,i)=>`<div class="item ${n.k}"><span>🔔</span><div class="grow"><b>${esc(n.t)}</b><small>${esc(n.s)}</small></div><button class="pill" data-notification-open="${i}">Abrir</button></div>`).join(""):`<div class="card sub">Nada urgente por enquanto.</div>`}</div><div class="modalActions"><button class="pill" data-close>Fechar</button></div>`);byId("notificationPreferencesSave").onclick=async()=>{D.settings.notifications={...cfg,dailySummary:byId("dailySummaryToggle").checked,dueAlerts:byId("dueAlertsToggle").checked,quietStart:byId("quietStart").value||"22:00",quietEnd:byId("quietEnd").value||"07:00"};save();await scheduleDailySummary();toast("Preferências de notificação atualizadas.","success","Notificações salvas")};document.querySelectorAll("[data-notification-open]").forEach(b=>b.onclick=()=>{let n=list[Number(b.dataset.notificationOpen)];closeM();nav=n.nav;render()})}
async function scheduleDailySummary(){let p=nativeNotifPlugin(),cfg=D.settings.notifications||{};if(!p||!nativePlatform()||!D.onboarded)return;let nid=notifHash("smart-life-daily-summary");try{await p.cancel({notifications:[{id:nid}]});if(!cfg.dailySummary||!await ensureNotifPermission())return;await p.schedule({notifications:[{id:nid,title:"Smart Life • Resumo do dia",body:"Confira hábitos, missões e compromissos antes de encerrar o dia.",smallIcon:NOTIF_SMALL_ICON,iconColor:NOTIF_ICON_COLOR,schedule:{on:{hour:20,minute:0},allowWhileIdle:true},extra:{nav:"home"}}]})}catch(e){console.warn("Resumo diário",e)}}
async function initNativeNotificationsV47(){let p=nativeNotifPlugin();if(!p||!nativePlatform())return;try{await p.registerActionTypes?.({types:[{id:"HABIT_ACTIONS",actions:[{id:"DONE",title:"Concluir"},{id:"SNOOZE",title:"Adiar 10 min"}]}]});await p.addListener?.("localNotificationActionPerformed",async ev=>{let extra=ev?.notification?.extra||{},hid=extra.habitId,action=ev?.actionId;if(action==="DONE"&&hid){let h=D.habits.find(x=>sameId(x.id,hid));if(h&&!done(h))toggle(h.id);return}if(action==="SNOOZE"&&hid){let h=D.habits.find(x=>sameId(x.id,hid));if(h)await p.schedule({notifications:[{id:notifHash(`snooze:${hid}:${Date.now()}`),title:`Smart Life • ${h.title}`,body:"Lembrete adiado: hora de concluir este hábito.",smallIcon:NOTIF_SMALL_ICON,iconColor:NOTIF_ICON_COLOR,actionTypeId:"HABIT_ACTIONS",schedule:{at:new Date(Date.now()+600000),allowWhileIdle:true},extra:{habitId:hid,nav:"habits"}}]});return}nav=extra.nav||"habits";render();scrollTo(0,0)});await syncAllHabitNotifications();await scheduleDailySummary()}catch(e){console.warn("Inicialização avançada de notificações",e)}}
function settingsV47(){let c=cloudCfg(),last=c.lastSync?new Date(c.lastSync).toLocaleString("pt-BR"):"Nunca";return settingsV46().replace('<div class="card" style="margin-top:15px"><h2>Backup e dados</h2>',`<div class="card settingsFeatureGrid" style="margin-top:15px"><button data-week-review><span>▥</span><b>Revisão semanal</b><small>Progresso dos últimos sete dias</small></button><button data-open-trash><span>⌫</span><b>Lixeira (${D.trash.length})</b><small>Restauração por até 30 dias</small></button><button data-cloud-settings><span>☁</span><b>Smart Life Online</b><small>${c.enabled?`Última sincronização: ${esc(last)}`:"Configurar Supabase opcional"}</small></button><button data-notification-center><span>🔔</span><b>Central de notificações</b><small>Alertas e vencimentos</small></button></div><div class="card" style="margin-top:15px"><h2>Backup e dados</h2>`)}

const views={home:homeV53,agenda,habits:habitsV46,evolution,tools:toolsV48,missions,projects:projectsV48,finance,organize:organizeV46,profile,settings:settingsV47};function render(){if(nav!==lastRenderedNav){if(!handlingAppBack){appNavHistory.push(lastRenderedNav);appNavHistory=appNavHistory.slice(-30)}lastRenderedNav=nav}if(D.onboarded)ensureSmartDaily();evaluateTitles(false);let root=byId("view");if(!root){console.error("Smart Life: área principal #view não encontrada");return}try{root.innerHTML=(views[nav]||homeV53)();wireIdGlobals(root);document.querySelectorAll("[data-nav]").forEach(b=>b.classList.toggle("on",b.dataset.nav===nav));bind();sync();renderTopUI()}catch(e){console.error("Smart Life: erro ao renderizar",e);root.innerHTML=`<div class="card errorCard"><h2>Não foi possível carregar esta tela</h2><p class="sub">Recarregue a página. Se continuar, exporte o backup e envie o erro abaixo.</p><code>${esc(e?.message||String(e))}</code></div>`}}
