  document.querySelectorAll(".projectMini [data-open-project]").forEach(b=>{let area=b.closest(".projectMini")?.querySelector(".grow");if(!area)return;area.classList.add("contextOpenArea");area.tabIndex=0;area.title="Abrir e destacar este projeto";area.onclick=()=>openProjectTarget(b.dataset.openProject)});
  document.querySelectorAll("[data-h]").forEach(b=>{b.onclick=()=>toggle(b.dataset.h,b.dataset.date||iso());b.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();b.click()}}});
