function proto(days){let labels={7:"Adaptação",21:"Consolidação",30:"Consistência",90:"Transformação"};modal(`<div class="mh"><div><div class="kicker">PROTOCOLO ${days} DIAS</div><h2>${labels[days]||"Protocolo pessoal"}</h2></div><button class="x" id="cx">×</button></div><div class="protocolIntro"><b>Como funciona</b><p>Cria uma missão principal com prazo e um hábito diário ligado ao objetivo. Você acompanha o progresso no Planner.</p></div><div class="form"><label>Objetivo</label><input id="prt" class="field" placeholder="Ex.: Voltar a estudar inglês"><label>Ação diária</label><input id="pra" class="field" placeholder="Ex.: Estudar inglês por 20 minutos"><div class="modalActions"><button class="pill" id="prCancel">Cancelar</button><button class="btn" id="prs">Criar protocolo</button></div></div>`);cx.onclick=closeM;prCancel.onclick=closeM;prs.onclick=()=>{let goal=prt.value.trim(),daily=pra.value.trim();if(!goal)return toast("Informe o objetivo principal.","warn");if(!daily)daily=`Avançar em: ${goal}`;let due=new Date();due.setDate(due.getDate()+days);D.missions.push({id:id(),title:`Protocolo ${days}d — ${goal}`,desc:`${labels[days]||"Protocolo"}: ${daily}`,due:iso(due),xp:Math.min(500,Math.max(100,days*8)),done:false,protocol:days});D.habits.push({id:id(),title:daily,desc:`Etapa diária do protocolo de ${days} dias: ${goal}`,xp:50,bonus:[{k:"discipline",n:1}],rest:[],log:{},xpLog:{},protocol:days});evaluateTitles(true);save();closeM();render();toast(`Protocolo de ${days} dias criado com missão e hábito diário.`,"success","Protocolo ativado")}}
function titles(){let metrics=titleMetrics();modal(`<div class="mh"><div><h2>130 Títulos</h2><p class="sub">${D.titles.filter(t=>t.unlocked).length} conquistados • novos títulos são equipados automaticamente</p></div><button class="x" id="cx">×</button></div><div class="titleLegend"><span>🏆 Conquistado</span><span>🔒 Meta ainda não atingida</span><span>⚡ Autoequipar ao desbloquear</span></div><div class="grid2 titleGrid">${D.titles.map(t=>{let rule=titleRule(t.name,metrics);return`<div class="card titleCard ${t.unlocked?"unlocked":"locked"} ${t.equipped?"equipped":""}"><div class="titleCardHead"><b>${t.unlocked?"🏆":"🔒"} ${esc(t.name)}</b>${t.equipped?`<span class="titleEquipped">EQUIPADO</span>`:""}</div><p class="sub titleRule">${esc(rule.desc)}</p>${t.unlocked&&!t.equipped?`<button class="pill" data-tt="${t.id}">Equipar manualmente</button>`:t.equipped?`<span class="titleAuto">⚡ Título ativo</span>`:`<span class="titlePending">Continue evoluindo</span>`}</div>`}).join("")}</div>`);let c=byId("cx");if(c)c.onclick=closeM;document.querySelectorAll("[data-tt]").forEach(b=>b.onclick=()=>{D.titles.forEach(t=>t.equipped=t.id===b.dataset.tt);save();closeM();titles();toast("Título equipado no seu perfil.","success","Título alterado")})}
function drawRadar(){let c=document.querySelector("#radar");if(!c)return;let r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;let x=c.getContext("2d");x.scale(d,d);let cx=r.width/2,cy=r.height/2,R=Math.min(r.width,r.height)*.34,N=ATTR.length,max=Math.max(20,...ATTR.map(a=>D.attrs[a[0]]||0));for(let z=1;z<=5;z++){x.beginPath();ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N,rr=R*z/5,px=cx+Math.cos(g)*rr,py=cy+Math.sin(g)*rr;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.strokeStyle="#202823";x.stroke()}ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N;x.fillStyle="#dce5df";x.font="11px sans-serif";let px=cx+Math.cos(g)*(R+32),py=cy+Math.sin(g)*(R+22);x.textAlign=px<cx-10?"right":px>cx+10?"left":"center";x.fillText(a[1],px,py)});x.beginPath();ATTR.forEach((a,i)=>{let g=-Math.PI/2+i*2*Math.PI/N,rr=R*((D.attrs[a[0]]||0)/max),px=cx+Math.cos(g)*rr,py=cy+Math.sin(g)*rr;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.fillStyle="#23da6744";x.strokeStyle="#35ef79";x.lineWidth=2;x.fill();x.stroke()}
async function photoData(file){return new Promise((resolve,reject)=>{if(!file)return resolve("");if(!file.type.startsWith("image/"))return reject(new Error("Escolha uma imagem válida."));if(file.size>8*1024*1024)return reject(new Error("A imagem deve ter no máximo 8 MB."));let fr=new FileReader();fr.onerror=()=>reject(new Error("Não foi possível ler a imagem."));fr.onload=()=>{let img=new Image();img.onerror=()=>reject(new Error("Imagem inválida."));img.onload=()=>{let size=320,c=document.createElement("canvas"),ctx=c.getContext("2d"),scale=Math.min(1,size/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));c.width=w;c.height=h;ctx.drawImage(img,0,0,w,h);resolve(c.toDataURL("image/jpeg",.86))};img.src=fr.result};fr.readAsDataURL(file)})}
function editProfileModal(){let pendingPhoto=D.profile.photo||"";modal(`<div class="mh"><div><h2>Editar perfil</h2><p class="sub">Personalize sua identidade no Smart Life.</p></div><button class="x" id="cx">×</button></div><div class="profileEditor"><div class="photoEditor"><div class="avatar profilePreview" id="profilePreview">${pendingPhoto?`<img class="profilePhoto" src="${pendingPhoto}">`:esc((D.profile.avatar||"SL").slice(0,3))}</div><div><label class="fileBtn" for="profilePhotoInput">▣ Escolher foto</label><input id="profilePhotoInput" type="file" accept="image/*" hidden><button class="linkBtn" id="removePhoto" type="button">Remover foto</button><p class="sub">A foto é reduzida e salva no próprio backup.</p></div></div><div class="profileEditGrid form"><div><label>Nome exibido</label><input id="epName" class="field" maxlength="60" value="${esc(D.profile.name)}"></div><div><label>Nome de usuário</label><input id="epUser" class="field" maxlength="32" value="${esc(D.profile.username)}"></div></div><div class="form"><label>Iniciais (usadas quando não houver foto)</label><input id="epAvatar" class="field" maxlength="3" value="${esc(D.profile.avatar||"SL")}"></div><div class="modalActions"><button class="pill" id="epBack">← Voltar</button><button class="btn" id="epSave">Salvar perfil</button></div></div>`);cx.onclick=closeM;epBack.onclick=closeM;removePhoto.onclick=()=>{pendingPhoto="";profilePreview.innerHTML=esc((epAvatar.value||"SL").slice(0,3).toUpperCase());toast("A foto será removida ao salvar.","info")};profilePhotoInput.onchange=async()=>{try{pendingPhoto=await photoData(profilePhotoInput.files?.[0]);profilePreview.innerHTML=`<img class="profilePhoto" src="${pendingPhoto}">`;toast("Foto pronta para salvar.","info","Foto selecionada")}catch(e){toast(e.message||"Não foi possível carregar a foto.","error")}};epAvatar.oninput=()=>{if(!pendingPhoto)profilePreview.textContent=(epAvatar.value||"SL").slice(0,3).toUpperCase()};epSave.onclick=()=>{let nextName=epName.value.trim(),nextUser=epUser.value.trim();if(nextName.length<2)return toast("Informe um nome de exibição válido.","error","Perfil não alterado");let updated=window.SmartLifeAuth?.updateCurrentAccount?.({accountId:currentAccount?.id||"",displayName:nextName,username:nextUser,email:currentAccount?.email||""});if(!updated?.ok)return toast(updated?.message||"Não foi possível atualizar a conta.","error","Perfil não alterado");currentAccount=updated.account;window.__smartLifeAccount=updated.account;D.profile.name=updated.account.displayName;D.profile.username=updated.account.username;D.profile.avatar=(epAvatar.value.trim()||"SL").slice(0,3).toUpperCase();D.profile.photo=pendingPhoto;save();closeM();render();toast("As alterações foram salvas nesta conta e continuarão após reabrir o aplicativo.","success","Perfil atualizado")}}
let smartLifeDownloadsPlugin;
function getSmartLifeDownloadsPlugin(){if(smartLifeDownloadsPlugin)return smartLifeDownloadsPlugin;let cap=window.Capacitor;if(!cap?.registerPlugin)return null;smartLifeDownloadsPlugin=cap.registerPlugin("SmartLifeDownloads");return smartLifeDownloadsPlugin}
async function shareBackupFallback(name,json){let encoded=b64(new TextEncoder().encode(json)),fs=capacitorPlugin("Filesystem","__smartLifeFilesystem"),share=capacitorPlugin("Share","__smartLifeShare");if(!fs||!share)throw new Error("Rotas nativas de arquivo indisponíveis");let written=await fs.writeFile({path:name,data:encoded,directory:"CACHE",recursive:true}),uri=written?.uri||(await fs.getUri({path:name,directory:"CACHE"}))?.uri;if(!uri)throw new Error("O Android não criou o arquivo temporário");await share.share({title:"Backup do Smart Life",text:"Salve este backup em Downloads ou no local de sua preferência.",files:[uri],dialogTitle:"Salvar backup do Smart Life"});toast("Escolha Arquivos e a pasta Downloads para guardar o backup.","success","Backup preparado")}
async function exportBackup(){let safeData=JSON.parse(JSON.stringify(D));safeData.settings=safeData.settings||{};safeData.settings.ai=Object.assign({},safeData.settings.ai||{},{apiKey:""});safeData.settings.cloud=Object.assign({},safeData.settings.cloud||{},{enabled:false,url:"",anonKey:"",syncId:"",passphrase:"",lastSync:"",autoSync:false});let payload={format:"smart-life-backup",schema:3,app:"Smart Life",version:"0.6.1",platform:nativePlatform()?"android":"computer",exportedAt:new Date().toISOString(),security:{apiKeyIncluded:false,cloudCredentialsIncluded:false},account:{displayName:currentAccount?.displayName||D.profile.name,username:currentAccount?.username||D.profile.username,email:currentAccount?.email||""},data:safeData},json=JSON.stringify(payload,null,2),name=`smart-life-backup-${iso()}.smartlife.json`;if(nativePlatform()){try{let result=await getSmartLifeDownloadsPlugin()?.saveFile({filename:name,base64:b64(new TextEncoder().encode(json)),mimeType:"application/json"});if(!result?.filename&&!result?.path)throw new Error("Integração direta não respondeu");let path=result.path||`Downloads/${result.filename||name}`;toast(`Arquivo salvo em ${path}.`,"success","Backup baixado");return}catch(error){console.warn("Download direto indisponível; abrindo rota segura",error);try{await shareBackupFallback(name,json);return}catch(fallbackError){console.error("Falha nas duas rotas de backup",fallbackError);toast("Não foi possível abrir o salvamento nativo. O backup será baixado pelo navegador interno.","warn","Usando rota de emergência")}}}downloadBackup(new File([json],name,{type:"application/json"}),name)}
function downloadBackup(file,name){let a=document.createElement("a"),url=URL.createObjectURL(file);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(`Download iniciado: ${name}.`,"success","Backup baixado")}
function backupSummary(data,meta={}){let f=normalizeFinance(data.finance),owner=Number(f.selectedOwnerId||0),own=(r)=>!owner||Number(r.owner_id)===owner;return{version:meta.version||"versão anterior",habits:Array.isArray(data.habits)?data.habits.length:0,missions:Array.isArray(data.missions)?data.missions.length:0,projects:Array.isArray(data.projects)?data.projects.length:0,expenses:f.expenses.filter(own).length,incomes:f.incomes.filter(own).length}}
function backupIdentity(parsed,data){let a=parsed?.format==="smart-life-backup"&&parsed.account&&typeof parsed.account==="object"?parsed.account:{},p=data?.profile||{};return{displayName:String(a.displayName||p.name||"").trim(),username:String(a.username||p.username||"").trim(),email:String(a.email||"").trim().toLowerCase()}}
function identityDiffers(a,b){if(!a||!b)return false;return!!((a.username&&String(b.username||"").toLowerCase()!==a.username.toLowerCase())||(a.email&&String(b.email||"").toLowerCase()!==a.email.toLowerCase())||(a.displayName&&String(b.displayName||"")!==a.displayName))}
function importBackup(){
 let f=document.createElement("input");f.type="file";f.accept=".json,.smartlife,.smartlife.json,application/json";
 f.onchange=()=>{let file=f.files?.[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{
  let parsed=JSON.parse(r.result),data=parsed?.format==="smart-life-backup"?parsed.data:parsed;
  if(!data||typeof data!=="object"||!Array.isArray(data.habits)||!data.profile)throw new Error("Formato não reconhecido");
  let sm=backupSummary(data,parsed||{}),backupAccount=backupIdentity(parsed,data),active=window.__smartLifeAccount||currentAccount,different=identityDiffers(backupAccount,active);
  let identityBox=different?`<div class="backupIdentityCompare"><div><small>CONTA ATUAL</small><b>${esc(active?.displayName||"Conta local")}</b><span>@${esc(active?.username||"")}${active?.email?` • ${esc(active.email)}`:""}</span></div><strong>→</strong><div><small>IDENTIDADE DO BACKUP</small><b>${esc(backupAccount.displayName||data.profile.name||"Jogador")}</b><span>@${esc(backupAccount.username||data.profile.username||"")}${backupAccount.email?` • ${esc(backupAccount.email)}`:""}</span></div></div>`:"";
  let warning=different?"Este backup pertence a outra identidade. Ao confirmar, a conta local atual será atualizada para a identidade do backup. A senha criada neste dispositivo será preservada.":"Os dados atuais desta conta serão substituídos. A conta, a senha e a chave Gemini salva neste dispositivo serão preservadas.";
  modal(`<div class="mh"><div><h2>Importar backup?</h2><p class="sub">Confira o conteúdo e a identidade antes de substituir os dados.</p></div><button class="x" id="cx">×</button></div><div class="card"><div class="kicker">BACKUP ${esc(sm.version)}</div><div class="grid2 backupPreview"><div><small>Hábitos</small><b>${sm.habits}</b></div><div><small>Missões</small><b>${sm.missions}</b></div><div><small>Projetos</small><b>${sm.projects}</b></div><div><small>Finanças</small><b>${sm.expenses} despesas • ${sm.incomes} receitas</b></div></div></div>${identityBox}<div class="dangerBox" style="margin-top:12px"><p>${esc(warning)}</p></div><div class="modalActions"><button class="pill" id="backupCancel">Cancelar</button><button class="btn" id="backupConfirm">${different?"Usar identidade do backup":"Importar backup"}</button></div>`);
  byId("backupCancel").onclick=closeM;
  byId("backupConfirm").onclick=async()=>{
   let account=active;
   if(different){let adopted=window.SmartLifeAuth?.adoptBackupIdentity?.(backupAccount);if(!adopted?.ok)return toast(adopted?.message||"Não foi possível vincular a identidade do backup.","error","Conta não alterada");account=adopted.account;currentAccount=account;window.__smartLifeAccount=account}
   let localKey=String(aiConfig().apiKey||"");D=normalizeState(data,false);D.settings=D.settings||{};let importedAi=D.settings.ai||{},defaults=aiDefaults();D.settings.ai=Object.assign(defaults,importedAi,{apiKey:localKey,permissions:Object.assign(defaults.permissions,importedAi.permissions||{})});
   if(account){D.profile.name=account.displayName||D.profile.name;D.profile.username=account.username||D.profile.username}
   save();applyTheme();closeM();render();if(nativePlatform())await syncAllHabitNotifications();toast(different?"Backup restaurado e conta local vinculada à identidade correta.":"Personagem, progresso e configurações foram restaurados; a chave Gemini local foi preservada.","success","Backup importado")
  }
 }catch(e){console.error(e);toast("Esse arquivo não parece ser um backup válido do Smart Life.","error","Importação falhou")}};r.readAsText(file)};f.click()
}

function stats(){
  let doneN=D.history.filter(x=>x.type==="habit_done").length;
  let rate=D.habits.length?Math.round(doneN/Math.max(1,D.habits.length*30)*100):0;
  modal(`<div class="mh"><div><h2>Estatísticas</h2><p class="sub">Visão geral dos seus hábitos</p></div><button class="x" id="cx">×</button></div><div class="stats"><div class="stat">⊙ Hábitos Ativos<b style="color:var(--green)">${D.habits.length}</b></div><div class="stat">🔥 Melhor Streak<b style="color:var(--warn)">${D.bestStreak}</b></div><div class="stat">▥ Taxa Média<b>${rate}%</b></div><div class="stat">▦ Dias Completos<b>${D.history.filter(x=>x.type==="perfect").length}</b></div></div><div class="card" style="margin-top:14px"><h3>Progresso de Hoje</h3><p class="metric">${D.habits.filter(h=>done(h)).length}/${D.habits.length}<small> hábitos</small></p><p class="metric">${todayXP()}/500<small> XP</small></p></div><div class="card" style="margin-top:14px"><h3>Detalhes individuais</h3><div class="list">${D.habits.map(h=>`<div class="item"><div class="grow"><b>${esc(h.title)}</b><p class="sub">${Object.values(h.log||{}).filter(Boolean).length} conclusões</p></div></div>`).join("")}</div></div>`);
  let c=byId("cx");if(c)c.onclick=closeM;
}
