function buildSimplePdfV56(lines){let pages=[];for(let i=0;i<lines.length;i+=48)pages.push(lines.slice(i,i+48));let objs=[null,null,null],pageIds=[],contentIds=[],next=4;pages.forEach(()=>{pageIds.push(next++);contentIds.push(next++)});objs[1]=`<< /Type /Catalog /Pages 2 0 R >>`;objs[2]=`<< /Type /Pages /Count ${pages.length} /Kids [${pageIds.map(id=>`${id} 0 R`).join(" ")}] >>`;objs[3]=`<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>`;pages.forEach((page,i)=>{let content=`BT /F1 10 Tf 48 800 Td 14 TL ${page.map(x=>`(${pdfAsciiV56(x)}) Tj T*`).join(" ")} ET`;objs[pageIds[i]]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentIds[i]} 0 R >>`;objs[contentIds[i]]=`<< /Length ${content.length} >>\nstream\n${content}\nendstream`});let pdf="%PDF-1.4\n",offsets=[0];for(let i=1;i<objs.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`}let xref=pdf.length;pdf+=`xref\n0 ${objs.length}\n0000000000 65535 f \n`;for(let i=1;i<objs.length;i++)pdf+=`${String(offsets[i]).padStart(10,"0")} 00000 n \n`;pdf+=`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:"application/pdf"})}
