/* Smart Life v0.5.7 — meta de leitura incremental */
const normalizeStateBeforeV57=normalizeState;
function normalizeStateV57(raw,seedFinance=false){
  let state=normalizeStateBeforeV57(raw,seedFinance);
  state.projects=Array.isArray(state.projects)?state.projects:[];
  state.projects.forEach(p=>{
    if(p.type==="reading"){
      p.target=Math.max(0,Number(p.target||0));
      p.current=Math.max(0,Number(p.current||0));
      p.unit="páginas";
      p.updates=Array.isArray(p.updates)?p.updates:[];
      p.done=p.target>0&&p.current>=p.target;
    }
  });
  return state;
}
normalizeState=normalizeStateV57;

function projectPctV57(p){
  let target=Number(p?.target||0),current=Number(p?.current||0);
  if((p?.type==="money"||p?.type==="count"||p?.type==="reading")&&target>0)return Math.max(0,Math.min(100,current/target*100));
  return Math.max(0,Math.min(100,Number(p?.progress||0)));
}
projectPct=projectPctV57;

