function addProjectValueV57(p,amount){amount=Number(amount);if(!p||!Number.isFinite(amount)||amount<=0)return toast("Informe um valor maior que zero.","warn");if(p.type==="reading"){let remaining=Math.max(0,Number(p.target||0)-Number(p.current||0));if(remaining<=0)return toast("Esta meta de leitura já foi concluída.","info");amount=Math.min(amount,remaining)}p.current=Number(p.current||0)+amount;p.updates=Array.isArray(p.updates)?p.updates:[];p.updates.unshift({id:id(),amount,date:new Date().toLocaleDateString("pt-BR"),time:new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})});p.updates=p.updates.slice(0,100);p.done=Number(p.target||0)>0&&p.current>=Number(p.target||0);hist("project_add",{project:p.title,amount,type:p.type});evaluateTitles(true);save();render();let msg=p.type==="money"?`${amount.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})} adicionados. Total: ${Number(p.current).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}.`:p.type==="reading"?`+${amount.toLocaleString("pt-BR")} página(s). Você está em ${Number(p.current).toLocaleString("pt-BR")} de ${Number(p.target||0).toLocaleString("pt-BR")} páginas (${pctText(projectPct(p))}%).`:`+${amount.toLocaleString("pt-BR")} ${p.unit||"unidades"}. Total: ${Number(p.current).toLocaleString("pt-BR")} de ${Number(p.target||0).toLocaleString("pt-BR")}.`;toast(msg,"success",p.type==="reading"?"Leitura adicionada":"Progresso adicionado")}
