/* Smart Life v0.6.1 — leitura integrada com metas e ritmo diário */
function readingNormV58(value){return String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("pt-BR").replace(/[^a-z0-9]+/g," ").trim()}
function readingKeyV58(value){let stop=new Set(["ler","leitura","livro","meta","projeto","terminar","concluir","o","a","os","as","um","uma","de","do","da","dos","das","meu","minha"]);return readingNormV58(value).split(/\s+/).filter(w=>w&&!stop.has(w)).join(" ")}
function readingKeysMatchV58(a,b){let x=readingKeyV58(a),y=readingKeyV58(b);if(!x||!y)return false;if(x===y)return true;if(Math.min(x.length,y.length)>=6&&(x.includes(y)||y.includes(x)))return true;let xa=new Set(x.split(" ")),ya=new Set(y.split(" ")),common=[...xa].filter(w=>ya.has(w)).length,base=Math.max(1,Math.min(xa.size,ya.size));return common/base>=.75}
function activeReadingGoalsV58(includeDone=false){return(D.projects||[]).filter(p=>p.type==="reading"&&(includeDone||!p.done)&&Number(p.target||0)>0)}
function readingGoalMatchV58(book){let goals=activeReadingGoalsV58(false),exact=goals.filter(p=>readingKeysMatchV58(book,p.readingBook||p.title));return exact.length===1?exact[0]:null}
function readingGoalByIdV58(projectId){return(D.projects||[]).find(p=>p.type==="reading"&&sameId(p.id,projectId))||null}
function readingGoalRecentPagesV58(project,days=7){let start=addDaysISO(-(days-1)),key=project?.readingBook||project?.title||"";return(D.tools.reading||[]).filter(r=>String(r.date||"")>=start&&String(r.date||"")<=iso()).filter(r=>sameId(r.readingGoalProgress?.projectId,project?.id)||readingKeysMatchV58(r.book,key)).reduce((s,r)=>s+Number(r.pages||0),0)}
function readingPaceV58(project){let target=Math.max(0,Number(project?.target||0)),current=Math.max(0,Number(project?.current||0)),remaining=Math.max(0,target-current),d=project?.due?daysUntil(project.due):null,days=d==null?null:Math.max(1,d),required=remaining&&days?remaining/days:0,recent=readingGoalRecentPagesV58(project,7),avg=recent/7,status="";if(project?.done||remaining<=0)status="Meta concluída";else if(d!=null&&d<0)status="Prazo vencido";else if(!recent)status="Comece hoje";else if(required<=0||avg>=required)status="No ritmo";else if(avg>=required*.75)status="Quase no ritmo";else status="Precisa acelerar";return{target,current,remaining,days,required,recent,avg,status}}
function readingPaceBlockV58(project){let r=readingPaceV58(project);if(project.done)return`<div class="readingPaceCard done"><div><span>RITMO DE LEITURA</span><b>✓ Meta concluída</b></div><small>${r.target.toLocaleString("pt-BR")} páginas finalizadas.</small></div>`;let dueText=r.days==null?"Sem prazo definido":`${r.days} dia(s) até o prazo`,required=r.days!=null?`${Math.max(.1,r.required).toLocaleString("pt-BR",{maximumFractionDigits:1})} pág./dia`:`${r.avg.toLocaleString("pt-BR",{maximumFractionDigits:1})} pág./dia`;return`<div class="readingPaceCard"><div><span>RITMO NECESSÁRIO</span><b>${required}</b></div><div><span>MÉDIA 7 DIAS</span><b>${r.avg.toLocaleString("pt-BR",{maximumFractionDigits:1})} pág./dia</b></div><small>${esc(r.status)} • ${dueText} • sincroniza com Registros de Leitura.</small></div>`}
function readingGoalHintV58(project){if(!project)return`<div class="readingGoalHint neutral"><b>Sem meta vinculada</b><small>O registro ficará no histórico. Se o nome do livro combinar com uma meta ativa, o Smart Life tenta vinculá-la automaticamente.</small></div>`;let r=readingPaceV58(project),req=r.days!=null&&r.remaining?`${Math.max(.1,r.required).toLocaleString("pt-BR",{maximumFractionDigits:1})} pág./dia`:`ritmo livre`;return`<div class="readingGoalHint"><b>◆ ${esc(project.title)}</b><small>${r.current.toLocaleString("pt-BR")}/${r.target.toLocaleString("pt-BR")} páginas • ${req} • ${esc(r.status)}</small></div>`}
function readingGoalOptionsV58(selectedId=""){let goals=activeReadingGoalsV58(false);return`<option value="">Somente registrar</option>${goals.map(p=>`<option value="${esc(p.id)}" ${sameId(p.id,selectedId)?"selected":""}>${esc(p.title)} • ${Number(p.current||0).toLocaleString("pt-BR")}/${Number(p.target||0).toLocaleString("pt-BR")}</option>`).join("")}`}
function defaultReadingGoalIdV58(book,lastRecord=null){let remembered=D.toolSettings?.readingProjectId,p=readingGoalByIdV58(lastRecord?.readingGoalProgress?.projectId||lastRecord?.readingProjectId||remembered);if(p&&!p.done&&(readingKeysMatchV58(book,p.readingBook||p.title)||activeReadingGoalsV58(false).length===1))return p.id;let match=readingGoalMatchV58(book);if(match)return match.id;let goals=activeReadingGoalsV58(false);return goals.length===1?goals[0].id:""}
function removeReadingUpdateV58(project,recordId){if(!project)return;project.updates=Array.isArray(project.updates)?project.updates:[];project.updates=project.updates.filter(u=>!(u.source==="reading-record"&&sameId(u.recordId,recordId)))}
function rollbackReadingGoalProgressV58(record){let gp=record?.readingGoalProgress;if(!gp||gp.absorbed||!Number(gp.amount||0))return null;let p=readingGoalByIdV58(gp.projectId);if(!p)return null;let amount=Math.max(0,Number(gp.amount||0));p.current=Math.max(0,Number(p.current||0)-amount);p.done=Number(p.target||0)>0&&p.current>=Number(p.target||0);removeReadingUpdateV58(p,record.id);gp.rolledBack=true;return{project:p,amount}}
function syncReadingGoalProgressV58(record,preferredProjectId=""){if(!record||Number(record.pages||0)<=0)return null;let p=readingGoalByIdV58(preferredProjectId||record.readingProjectId)||readingGoalMatchV58(record.book);if(!p||p.done)return null;let remaining=Math.max(0,Number(p.target||0)-Number(p.current||0)),amount=Math.min(Math.max(0,Number(record.pages||0)),remaining);if(amount<=0)return null;let before=Number(p.current||0);p.current=before+amount;p.done=Number(p.target||0)>0&&p.current>=Number(p.target||0);p.readingBook=p.readingBook||record.book||p.title;p.updates=Array.isArray(p.updates)?p.updates:[];removeReadingUpdateV58(p,record.id);p.updates.unshift({id:id(),amount,date:new Date().toLocaleDateString("pt-BR"),time:new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}),source:"reading-record",recordId:record.id});p.updates=p.updates.slice(0,100);record.readingProjectId=p.id;record.readingGoalProgress={projectId:p.id,amount,beforeCurrent:before,day:record.date||iso(),absorbed:false};D.toolSettings=D.toolSettings||{};D.toolSettings.readingProjectId=p.id;hist("reading_goal_sync",{projectId:p.id,project:p.title,recordId:record.id,amount,book:record.book});evaluateTitles(true);return{project:p,amount,before,after:p.current}}
function absorbReadingGoalLinksV58(projectId){(D.tools.reading||[]).forEach(r=>{if(sameId(r.readingGoalProgress?.projectId,projectId)&&!r.readingGoalProgress.absorbed)r.readingGoalProgress.absorbed=true})}

const normalizeStateBeforeV58=normalizeState;
function normalizeStateV58(raw,seedFinance=false){let state=normalizeStateBeforeV58(raw,seedFinance);state.toolSettings=state.toolSettings||{};state.projects=Array.isArray(state.projects)?state.projects:[];state.projects.forEach(p=>{if(p.type==="reading"){p.target=Math.max(0,Number(p.target||0));p.current=Math.max(0,Math.min(Number(p.target||Infinity),Number(p.current||0)));p.unit="páginas";p.readingBook=String(p.readingBook||"").trim();p.updates=Array.isArray(p.updates)?p.updates:[];p.done=p.target>0&&p.current>=p.target}});state.tools=state.tools||{};state.tools.reading=Array.isArray(state.tools.reading)?state.tools.reading:[];return state}
