const toolRecordBeforeV58=toolRecord;
function toolRecordV58(type,entry,attr,source){let record=toolRecordBeforeV58(type,entry,attr,source);if(type==="reading"){syncReadingGoalProgressV58(record,entry?.readingProjectId||"");save()}return record}
