function toolDeleteV58(type,recordId,reopen){let arr=D.tools[type]||[],record=arr.find(x=>x.id===recordId);if(!record)return;confirmDialog({title:"Excluir registro?",message:type==="reading"?"O registro, a recompensa, as automações e a meta de leitura vinculada serão recalculados.":"O registro, sua recompensa e o progresso das automações serão recalculados.",danger:true,confirmText:"Excluir registro",onConfirm:()=>{let reward=record.attributeReward;if(reward&&Number(reward.n||0)>0){undoAttr(reward.k,Number(reward.n));hist("tool_attr_undo",{k:reward.k,amount:Number(reward.n),source:record.id})}let links=[...(record.automationProgress||[]),...(record.linkedProgress?[record.linkedProgress]:[])];links.forEach(lp=>{let target=agendaTarget(lp.targetType,lp.targetId);if(!target)return;target.toolProgress=target.toolProgress||{};target.toolProgress[lp.day]=Math.max(0,Number(target.toolProgress[lp.day]||0)-Number(lp.amount||0));if(target.toolProgress[lp.day]<Number(target.toolGoal||0)&&target.autoCompletedByTool?.[lp.day]){if(lp.targetType==="habit"&&done(target,lp.day)){toggle(target.id,lp.day);delete target.autoCompletedByTool[lp.day]}else if(lp.targetType==="mission")rollbackToolMission(target,lp.day)}});let readingRollback=type==="reading"?rollbackReadingGoalProgressV58(record):null;D.tools[type]=arr.filter(x=>x.id!==recordId);evaluateTitles(true);save();reopen();let msg=reward?.n?`Registro removido e -${reward.n} ${toolRewardInfo(reward.k).name}.`:"Registro e progresso removidos.";if(readingRollback)msg+=` Meta “${readingRollback.project.title}” voltou ${readingRollback.amount} página(s).`;toast(msg,"info","Registro excluído")}})}
