const V59_HOME_WIDGETS=[
  ["attention","Atenção agora"],["habits","Hábitos de hoje"],["missions","Missões"],["reading","Leitura"],["finance","Finanças"],["focus","Fixados"],["checkin","Check-in diário"],["week","Resumo semanal"]
];
const V59_PROJECT_STAGES=["Planejamento","Em andamento","Revisão","Concluído"];
const V59_CHALLENGE_TYPES={habits:"Conclusões de hábitos",pages:"Páginas lidas",books:"Livros concluídos",workouts:"Treinos",savings:"Valor reservado",custom:"Progresso manual"};
const V59_QUANT_SOURCES={manual:"Manual",nutrition:"Água (ml)",reading:"Leitura (páginas)",study:"Estudo (min)",exercise:"Exercício (min)",sleep:"Sono (h)",organization:"Organização (min)"};
const normalizeStateBeforeV59=normalizeState;
normalizeState=function(raw,seedFinance=false){
  let s=normalizeStateBeforeV59(raw,seedFinance);
  s.library=ensureStableIds(Array.isArray(s.library)?s.library:[]);
  s.challenges=ensureStableIds(Array.isArray(s.challenges)?s.challenges:[]);
  s.checkins=ensureStableIds(Array.isArray(s.checkins)?s.checkins:[]);
  s.compositeGoals=ensureStableIds(Array.isArray(s.compositeGoals)?s.compositeGoals:[]);
  s.financeReserves=ensureStableIds(Array.isArray(s.financeReserves)?s.financeReserves:[]);
  s.dailyReviews=ensureStableIds(Array.isArray(s.dailyReviews)?s.dailyReviews:[]);
  s.settings=Object.assign({},s.settings||{});
  s.settings.homeWidgets=Array.isArray(s.settings.homeWidgets)&&s.settings.homeWidgets.length?s.settings.homeWidgets.filter(k=>V59_HOME_WIDGETS.some(x=>x[0]===k)):V59_HOME_WIDGETS.map(x=>x[0]);
  V59_HOME_WIDGETS.forEach(([k])=>{if(!s.settings.homeWidgets.includes(k))s.settings.homeWidgets.push(k)});
  s.settings.homeHidden=Array.isArray(s.settings.homeHidden)?s.settings.homeHidden:[];
  s.settings.focusPins=Array.isArray(s.settings.focusPins)?s.settings.focusPins.slice(0,3):[];
  s.library.forEach(b=>{b.status=b.status||"Quero ler";b.currentPage=Math.max(0,Number(b.currentPage||0));b.totalPages=Math.max(0,Number(b.totalPages||0));b.attachments=Array.isArray(b.attachments)?b.attachments:[]});
  s.challenges.forEach(c=>{c.type=c.type||"custom";c.target=Math.max(1,Number(c.target||1));c.current=Math.max(0,Number(c.current||0));c.startDate=c.startDate||iso();c.endDate=c.endDate||""});
  s.projects.forEach(p=>{p.stage=V59_PROJECT_STAGES.includes(p.stage)?p.stage:(p.done?"Concluído":"Em andamento");p.linkedReserveId=p.linkedReserveId||""});
  s.habits.forEach(h=>{h.quantitative=h.quantitative&&typeof h.quantitative==="object"?Object.assign({enabled:false,target:1,unit:"",source:"manual",log:{}},h.quantitative):{enabled:false,target:1,unit:"",source:"manual",log:{}};h.quantitative.log=h.quantitative.log&&typeof h.quantitative.log==="object"?h.quantitative.log:{}});
  Object.values(s.tools||{}).forEach(arr=>(arr||[]).forEach(r=>{r.attachments=Array.isArray(r.attachments)?r.attachments:[]}));
  return s;
};
if(D&&typeof D==="object")D=normalizeState(D,false);

