function rollbackReadingGoalProgressV59(record){let info=rollbackReadingGoalProgressV58BeforeV59(record);if(info?.project){let b=D.library?.find(x=>sameId(x.projectId,info.project.id)||readingKeysMatchV58(x.title,info.project.readingBook||info.project.title));if(b){b.projectId=info.project.id;b.currentPage=Math.max(0,Number(info.project.current||0));if(Number(b.totalPages||0)&&b.currentPage<Number(b.totalPages||0)&&b.status==="Concluído"){b.status="Lendo";b.finishedAt=""}}}return info}
