function librarySyncV59(){let changed=false;D.library.forEach(b=>{let p=D.projects.find(x=>x.type==="reading"&&(sameId(x.id,b.projectId)||searchNormV56(x.title)===searchNormV56(b.title)));if(p){if(!b.projectId){b.projectId=p.id;changed=true}let cur=Math.max(Number(b.currentPage||0),Number(p.current||0)),tot=Math.max(Number(b.totalPages||0),Number(p.target||0));if(cur!==Number(b.currentPage||0)){b.currentPage=cur;changed=true}if(tot!==Number(b.totalPages||0)){b.totalPages=tot;changed=true}if(p.done&&b.status!=="Concluído"){b.status="Concluído";b.finishedAt=b.finishedAt||iso();changed=true}}});if(changed)v59SaveSilent();return changed}
function libraryReadingStatsV59(book){let rec=(D.tools.reading||[]).filter(r=>searchNormV56(r.book||"")===searchNormV56(book.title||"")).sort((a,b)=>String(a.date||"").localeCompare(String(b.date||""))),last7=rec.filter(r=>{let d=v59Date(r.date);return d&&Date.now()-d.getTime()<=7*86400000}).reduce((s,r)=>s+Number(r.pages||0),0),avg=last7/7,remain=Math.max(0,Number(book.totalPages||0)-Number(book.currentPage||0)),days=avg>0?Math.ceil(remain/avg):null,finish=days!=null?new Date(Date.now()+days*86400000):null;return{last7,avg,remain,days,finish,records:rec.length}}
function libraryPctV59(b){return b.totalPages>0?Math.max(0,Math.min(100,b.currentPage/b.totalPages*100)):0}
function libraryViewV59(){librarySyncV59();let statuses=["Quero ler","Lendo","Pausado","Concluído"],counts=Object.fromEntries(statuses.map(s=>[s,D.library.filter(b=>b.status===s).length]));return header("Biblioteca","Livros, leitura, notas e metas conectados em um só lugar",`<div class="row"><button class="pill" data-library-goal>🏆 Meta anual</button><button class="btn" data-library-new>＋ Livro</button></div>`)+`<div class="lifeStatGrid"><div class="lifeStat"><small>LENDO</small><b>${counts["Lendo"]}</b></div><div class="lifeStat"><small>QUERO LER</small><b>${counts["Quero ler"]}</b></div><div class="lifeStat"><small>CONCLUÍDOS</small><b>${counts["Concluído"]}</b></div><div class="lifeStat"><small>PÁGINAS</small><b>${D.tools.reading.reduce((s,r)=>s+Number(r.pages||0),0).toLocaleString("pt-BR")}</b></div></div><div class="libraryGrid">${D.library.length?D.library.map(b=>{let st=libraryReadingStatsV59(b),pct=libraryPctV59(b),forecast=st.finish&&st.remain?`Ritmo atual: termina por volta de ${st.finish.toLocaleDateString("pt-BR")}`:st.remain?"Registre leituras para calcular a previsão.":"Leitura concluída.";return`<article class="card libraryCard"><div class="libraryCover">${b.coverData?`<img src="${b.coverData}" alt="Capa">`:"📚"}</div><div class="libraryBody"><div class="row between"><span class="kicker">${esc(b.status)}</span>${v59Traffic(b.status==="Concluído"?"green":b.status==="Lendo"?"yellow":"neutral",b.status)}</div><h2>${esc(b.title)}</h2><p class="sub">${esc(b.author||"Autor não informado")}</p>${b.totalPages?`<div class="label"><span>${Number(b.currentPage||0)} / ${Number(b.totalPages)} páginas</span><b>${pctText(pct)}%</b></div><div class="bar"><i style="width:${pct}%"></i></div>`:""}<small class="libraryForecast">${esc(forecast)}</small>${b.notes?`<p class="libraryNote">${esc(b.notes)}</p>`:""}<div class="projectActions"><button class="pill" data-library-progress="${b.id}">＋ páginas</button><button class="pill" data-library-attach="${b.id}">▣ Anexo</button><button class="pill" data-library-edit="${b.id}">Editar</button><button class="iconAction danger" data-library-del="${b.id}">×</button></div></div></article>`}).join(""):`<div class="card lifeEmpty"><span>📚</span><h2>Sua biblioteca começa aqui</h2><p>Adicione um livro. Se estiver lendo, o Smart Life pode criar e vincular uma Meta de Leitura automaticamente.</p><button class="btn" data-library-new>Adicionar primeiro livro</button></div>`}</div>`}
views.library=libraryViewV59;
function libraryModalV59(book=null){let b=book||{id:id(),title:"",author:"",totalPages:0,currentPage:0,status:"Quero ler",rating:0,notes:"",projectId:"",coverData:"",attachments:[]},pendingCover=b.coverData||"";modal(`<div class="mh"><div><span class="kicker">BIBLIOTECA</span><h2>${book?"Editar livro":"Novo livro"}</h2></div><button class="x" id="cx">×</button></div><div class="form"><div class="libraryCoverEdit"><div id="libCoverPreview" class="libraryCoverPreview">${pendingCover?`<img src="${pendingCover}" alt="Capa">`:"📚"}</div><div><label>Capa opcional</label><input id="libCoverFile" class="field" type="file" accept="image/*"><small class="sub">A imagem é reduzida e salva localmente junto com seu backup.</small>${pendingCover?`<button type="button" class="pill" id="libCoverRemove">Remover capa</button>`:""}</div></div><label>Título</label><input id="libTitle" class="field" maxlength="120" value="${esc(b.title)}"><label>Autor</label><input id="libAuthor" class="field" maxlength="100" value="${esc(b.author||"")}"><div class="formGrid2"><div><label>Total de páginas</label><input id="libTotal" class="field" type="number" min="0" value="${Number(b.totalPages||0)}"></div><div><label>Página atual</label><input id="libCurrent" class="field" type="number" min="0" value="${Number(b.currentPage||0)}"></div></div><div class="formGrid2"><div><label>Status</label><select id="libStatus" class="field">${["Quero ler","Lendo","Pausado","Concluído"].map(s=>`<option ${b.status===s?"selected":""}>${s}</option>`).join("")}</select></div><div><label>Avaliação</label><select id="libRating" class="field"><option value="0">Sem nota</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(b.rating)===n?"selected":""}>${"★".repeat(n)}</option>`).join("")}</select></div></div><label>Notas do livro</label><textarea id="libNotes" class="field" maxlength="3000">${esc(b.notes||"")}</textarea><label class="settingRow"><span><b>Criar/vincular Meta de Leitura</b><small class="sub">Ao salvar como “Lendo”, o progresso poderá ser atualizado pelos registros de leitura.</small></span><input id="libGoal" type="checkbox" ${b.projectId?"checked":""}></label><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="libSave">Salvar livro</button></div></div>`);let preview=()=>{let el=byId("libCoverPreview");if(el)el.innerHTML=pendingCover?`<img src="${pendingCover}" alt="Capa">`:"📚"};let file=byId("libCoverFile");if(file)file.onchange=async()=>{try{pendingCover=await photoData(file.files?.[0]);preview();toast("Capa pronta para salvar.","success","Biblioteca")}catch(e){toast(e.message||"Não foi possível usar essa imagem.","warn")}};let rm=byId("libCoverRemove");if(rm)rm.onclick=()=>{pendingCover="";preview();rm.remove()};byId("libSave").onclick=()=>{let title=byId("libTitle").value.trim(),total=Math.max(0,Number(byId("libTotal").value||0)),current=Math.max(0,Number(byId("libCurrent").value||0)),status=byId("libStatus").value;if(!title)return toast("Informe o título do livro.","warn");if(total&&current>total)return toast("A página atual não pode ultrapassar o total.","warn");let obj={...b,title,author:byId("libAuthor").value.trim(),totalPages:total,currentPage:current,status,rating:Number(byId("libRating").value||0),notes:byId("libNotes").value.trim(),coverData:pendingCover,updatedAt:new Date().toISOString(),createdAt:b.createdAt||new Date().toISOString()};if(status==="Concluído"&&!obj.finishedAt)obj.finishedAt=iso();if(byId("libGoal").checked&&(status==="Lendo"||status==="Concluído")&&total>0){let p=D.projects.find(x=>sameId(x.id,obj.projectId))||D.projects.find(x=>x.type==="reading"&&searchNormV56(x.title)===searchNormV56(title));if(!p){p={id:id(),title,desc:`Leitura de ${title}`,type:"reading",target:total,current,unit:"páginas",due:"",progress:0,done:current>=total,updates:[],subtasks:[],stage:current>=total?"Concluído":"Em andamento"};D.projects.push(p)}else{p.target=total;p.current=Math.max(Number(p.current||0),current);p.done=p.current>=p.target;p.stage=p.done?"Concluído":p.stage||"Em andamento"}obj.projectId=p.id}else if(!byId("libGoal").checked)obj.projectId="";let i=D.library.findIndex(x=>sameId(x.id,obj.id));i>=0?D.library[i]=obj:D.library.unshift(obj);save();closeM();render();toast("Livro salvo e conectado à sua leitura.","success","Biblioteca atualizada")}}
function libraryProgressV59(b){let st=libraryReadingStatsV59(b);modal(`<div class="mh"><div><span class="kicker">${esc(b.title)}</span><h2>Adicionar páginas</h2><p class="sub">Página atual: ${Number(b.currentPage||0)}${b.totalPages?` de ${b.totalPages}`:""}</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Quantidade lida agora</label><input id="libPagesAdd" class="field" type="number" min="1" step="1" value="10"><label>Tempo (min, opcional)</label><input id="libMinutesAdd" class="field" type="number" min="0" step="1" value="0"><p class="sub">Isso também cria um Registro de Leitura e atualiza a Meta de Leitura vinculada.</p><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="libPagesSave">Registrar leitura</button></div></div>`);byId("libPagesSave").onclick=()=>{let pages=Math.max(1,Number(byId("libPagesAdd").value||0)),minutes=Math.max(0,Number(byId("libMinutesAdd").value||0));if(b.totalPages&&b.currentPage+pages>b.totalPages)pages=b.totalPages-b.currentPage;if(pages<=0)return toast("Este livro já chegou ao total de páginas.","info");let start=Math.max(1,Number(b.currentPage||0)+1),end=Number(b.currentPage||0)+pages,r={id:id(),date:iso(),createdAt:new Date().toISOString(),kind:"reading",book:b.title,pages,minutes,startPage:start,endPage:end,currentPage:end,totalPages:Number(b.totalPages||0),percent:b.totalPages?Math.min(100,end/Number(b.totalPages)*100):0,note:"Registrado pela Biblioteca",readingProjectId:b.projectId||"",attachments:[]};D.tools.reading.unshift(r);let info=syncReadingGoalProgressV58(r,b.projectId||"");b.currentPage=Math.max(Number(b.currentPage||0),end,Number(info?.project?.current||0));if(b.totalPages&&b.currentPage>=b.totalPages){b.currentPage=b.totalPages;b.status="Concluído";b.finishedAt=iso()}if(info?.project){info.project.stage=info.project.done?"Concluído":info.project.stage||"Em andamento";b.projectId=info.project.id}save();closeM();render();toast(info?`+${pages} páginas em ${b.title}. Meta atualizada para ${info.project.current}/${info.project.target}.`:`+${pages} páginas em ${b.title}.`,"success","Leitura registrada")}}
function annualReadingGoalModalV59(){let year=new Date().getFullYear(),done=D.library.filter(b=>b.status==="Concluído"&&String(b.finishedAt||"").startsWith(String(year))).length,target=Number(D.settings.readingAnnualGoal||12);modal(`<div class="mh"><div><span class="kicker">META ANUAL DE LEITURA</span><h2>${done}/${target} livros em ${year}</h2></div><button class="x" id="cx">×</button></div><div class="form"><label>Livros que quero concluir no ano</label><input id="annualBooks" class="field" type="number" min="1" max="365" value="${target}"><div class="label"><span>Progresso atual</span><b>${pctText(Math.min(100,done/Math.max(1,target)*100))}%</b></div><div class="bar"><i style="width:${Math.min(100,done/Math.max(1,target)*100)}%"></i></div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="annualBooksSave">Salvar meta</button></div></div>`);byId("annualBooksSave").onclick=()=>{D.settings.readingAnnualGoal=Math.max(1,Number(byId("annualBooks").value||12));save();closeM();render();toast("Meta anual de leitura atualizada.","success")}}

function challengeCurrentV59(c){let start=String(c.startDate||"0000-00-00"),end=String(c.endDate||"9999-99-99"),inRange=d=>{let x=String(d||"").slice(0,10);return(!start||x>=start)&&(!end||x<=end)};if(c.type==="habits")return D.history.filter(x=>x.type==="habit_done"&&inRange(x.date)).length;if(c.type==="pages")return D.tools.reading.filter(x=>inRange(x.date)).reduce((s,x)=>s+Number(x.pages||0),0);if(c.type==="books")return D.library.filter(b=>b.status==="Concluído"&&inRange(b.finishedAt)).length;if(c.type==="workouts")return D.tools.exercise.filter(x=>inRange(x.date)).length;if(c.type==="savings")return D.financeReserves.reduce((s,r)=>s+Number(r.amount||0),0);return Number(c.current||0)}
function challengePctV59(c){return Math.min(100,challengeCurrentV59(c)/Math.max(1,Number(c.target||1))*100)}
function challengesViewV59(){let active=D.challenges.filter(c=>challengePctV59(c)<100),done=D.challenges.filter(c=>challengePctV59(c)>=100);return header("Desafios","Transforme períodos de foco em objetivos mensuráveis",`<button class="btn" data-challenge-new>＋ Novo desafio</button>`)+`<div class="lifeStatGrid"><div class="lifeStat"><small>ATIVOS</small><b>${active.length}</b></div><div class="lifeStat"><small>CONCLUÍDOS</small><b>${done.length}</b></div><div class="lifeStat"><small>EM RISCO</small><b>${active.filter(c=>c.endDate&&v59Days(c.endDate)<=3).length}</b></div><div class="lifeStat"><small>TOTAL</small><b>${D.challenges.length}</b></div></div><div class="lifeGrid">${D.challenges.length?D.challenges.map(c=>{let cur=challengeCurrentV59(c),pct=challengePctV59(c),d=c.endDate?v59Days(c.endDate):null,level=pct>=100?"green":d!=null&&d<0?"red":d!=null&&d<=3?"yellow":"neutral";return`<div class="card challengeCard"><div class="row between"><span class="kicker">${esc(V59_CHALLENGE_TYPES[c.type]||"Desafio")}</span>${v59Traffic(level,pct>=100?"Concluído":d!=null&&d<0?"Prazo vencido":d!=null?`${d} dia(s)`:"Sem prazo")}</div><h2>${esc(c.title)}</h2><p class="sub">${esc(c.desc||"")}</p><div class="label"><span>${Number(cur).toLocaleString("pt-BR")} / ${Number(c.target).toLocaleString("pt-BR")} ${esc(c.unit||"")}</span><b>${pctText(pct)}%</b></div><div class="bar"><i style="width:${pct}%"></i></div><div class="projectActions">${c.type==="custom"?`<button class="pill" data-challenge-add="${c.id}">＋ progresso</button>`:""}<button class="pill" data-challenge-edit="${c.id}">Editar</button><button class="iconAction danger" data-challenge-del="${c.id}">×</button></div></div>`}).join(""):`<div class="card lifeEmpty"><span>🏁</span><h2>Nenhum desafio ativo</h2><p>Ex.: 500 páginas em 30 dias, 20 treinos ou 30 dias de hábitos.</p><button class="btn" data-challenge-new>Criar desafio</button></div>`}</div>`}
