function challengeModalV59(c=null){let x=c||{id:id(),title:"",desc:"",type:"habits",target:30,current:0,unit:"",startDate:iso(),endDate:""};modal(`<div class="mh"><div><span class="kicker">DESAFIO PESSOAL</span><h2>${c?"Editar":"Novo"} desafio</h2></div><button class="x" id="cx">×</button></div><div class="form"><label>Nome</label><input id="chTitle" class="field" maxlength="100" value="${esc(x.title)}"><label>Tipo</label><select id="chType" class="field">${Object.entries(V59_CHALLENGE_TYPES).map(([k,v])=>`<option value="${k}" ${x.type===k?"selected":""}>${v}</option>`).join("")}</select><div class="formGrid2"><div><label>Meta</label><input id="chTarget" class="field" type="number" min="1" step="any" value="${Number(x.target||1)}"></div><div><label>Unidade</label><input id="chUnit" class="field" maxlength="20" value="${esc(x.unit||"")}" placeholder="dias, páginas..."></div></div><div class="formGrid2"><div><label>Início</label><input id="chStart" class="field" type="date" value="${x.startDate||iso()}"></div><div><label>Prazo</label><input id="chEnd" class="field" type="date" value="${x.endDate||""}"></div></div><label>Descrição</label><textarea id="chDesc" class="field" maxlength="500">${esc(x.desc||"")}</textarea><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="chSave">Salvar desafio</button></div></div>`);byId("chSave").onclick=()=>{let title=byId("chTitle").value.trim();if(!title)return toast("Informe o nome do desafio.","warn");let obj={...x,title,type:byId("chType").value,target:Math.max(1,Number(byId("chTarget").value||1)),unit:byId("chUnit").value.trim(),startDate:byId("chStart").value||iso(),endDate:byId("chEnd").value,desc:byId("chDesc").value.trim()};let i=D.challenges.findIndex(v=>sameId(v.id,obj.id));i>=0?D.challenges[i]=obj:D.challenges.unshift(obj);save();closeM();render();toast("Desafio salvo.","success")}}

function habitSmartStreakV59(h){let current=0,best=0,run=0,scheduled=0,completed=0;for(let i=119;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let ds=iso(d);if(rest(h,ds))continue;scheduled++;if(done(h,ds)){completed++;run++;best=Math.max(best,run)}else run=0}for(let i=0;i<120;i++){let d=new Date();d.setDate(d.getDate()-i);let ds=iso(d);if(rest(h,ds))continue;if(done(h,ds))current++;else break}return{current,best,rate:scheduled?completed/scheduled*100:0,scheduled,completed}}
function habitQuantValueV59(h,date=iso()){let q=h.quantitative||{};if(!q.enabled)return 0;if(q.source==="manual")return Number(q.log?.[date]||0);if(q.source==="nutrition")return(D.tools.nutrition||[]).filter(r=>r.date===date&&r.kind==="water").reduce((s,r)=>s+Number(r.ml||0),0);if(q.source==="reading")return(D.tools.reading||[]).filter(r=>r.date===date).reduce((s,r)=>s+Number(r.pages||0),0);if(q.source==="study")return(D.tools.study||[]).filter(r=>r.date===date).reduce((s,r)=>s+Number(r.minutes||0),0);if(q.source==="exercise")return(D.tools.exercise||[]).filter(r=>r.date===date).reduce((s,r)=>s+Number(r.minutes||0),0);if(q.source==="sleep")return(D.tools.sleep||[]).filter(r=>r.date===date).reduce((s,r)=>s+Number(r.hours||0),0);if(q.source==="organization")return(D.tools.organization||[]).filter(r=>r.date===date).reduce((s,r)=>s+Number(r.minutes||0),0);return 0}
function habitsLifePanelV59(){return`<div class="card lifeHabitsPanel"><div class="row between"><div><span class="kicker">HÁBITOS INTELIGENTES</span><h2>Sequência, taxa e metas quantitativas</h2></div><button class="pill" data-auto-connect>⌁ Conectar automaticamente</button></div><div class="lifeHabitRows">${D.habits.length?D.habits.map(h=>{let s=habitSmartStreakV59(h),q=h.quantitative||{},value=habitQuantValueV59(h),pct=q.enabled?Math.min(100,value/Math.max(.01,Number(q.target||1))*100):0;return`<div class="lifeHabitRow"><div class="grow"><b>${esc(h.title)}</b><small>🔥 ${s.current} atual • melhor ${s.best} • ${pctText(s.rate)}% em 120 dias</small>${q.enabled?`<div class="label"><span>${Number(value).toLocaleString("pt-BR",{maximumFractionDigits:1})}/${Number(q.target).toLocaleString("pt-BR",{maximumFractionDigits:1})} ${esc(q.unit||"")}</span><b>${pctText(pct)}%</b></div><div class="bar"><i style="width:${pct}%"></i></div>`:""}</div>${q.enabled&&q.source==="manual"?`<button class="quickValue" data-habit-quant-add="${h.id}">＋</button>`:""}<button class="pill" data-habit-quant="${h.id}">${q.enabled?"Configurar":"Meta quantitativa"}</button></div>`}).join(""):`<p class="sub">Crie um hábito para configurar metas quantitativas.</p>`}</div></div>`}
const habitsBeforeV59=views.habits;
function habitsV59(){return habitsBeforeV59()+habitsLifePanelV59()}
views.habits=habitsV59;
function habitQuantModalV59(h){let q=h.quantitative||{enabled:false,target:1,unit:"",source:"manual",log:{}};modal(`<div class="mh"><div><span class="kicker">${esc(h.title)}</span><h2>Meta quantitativa</h2><p class="sub">Ex.: 3 L de água, 25 páginas, 45 min de treino.</p></div><button class="x" id="cx">×</button></div><div class="form"><label class="settingRow"><span><b>Ativar meta quantitativa</b><small class="sub">Mostra progresso parcial ao longo do dia.</small></span><input id="hqEnabled" type="checkbox" ${q.enabled?"checked":""}></label><label>Fonte do progresso</label><select id="hqSource" class="field">${Object.entries(V59_QUANT_SOURCES).map(([k,v])=>`<option value="${k}" ${q.source===k?"selected":""}>${v}</option>`).join("")}</select><div class="formGrid2"><div><label>Meta diária</label><input id="hqTarget" class="field" type="number" min="0.1" step="0.1" value="${Number(q.target||1)}"></div><div><label>Unidade</label><input id="hqUnit" class="field" maxlength="20" value="${esc(q.unit||"")}" placeholder="ml, páginas, min..."></div></div><p class="sub">Fontes como Água, Leitura e Exercício usam seus registros e podem concluir o hábito automaticamente via integração já existente.</p><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="hqSave">Salvar configuração</button></div></div>`);byId("hqSave").onclick=()=>{let source=byId("hqSource").value,target=Math.max(.1,Number(byId("hqTarget").value||1)),unit=byId("hqUnit").value.trim();h.quantitative={...q,enabled:byId("hqEnabled").checked,source,target,unit,log:q.log||{}};if(h.quantitative.enabled&&source!=="manual"){D.toolSettings.links=D.toolSettings.links||{};D.toolSettings.links[source]={targetType:"habit",targetId:h.id,goal:target,unit}}save();closeM();render();toast("Meta quantitativa atualizada.","success","Hábito inteligente")}}
function habitQuantAddV59(h){let q=h.quantitative||{};modal(`<div class="mh"><div><h2>Adicionar progresso</h2><p class="sub">${esc(h.title)} • ${Number(habitQuantValueV59(h)).toLocaleString("pt-BR",{maximumFractionDigits:1})}/${Number(q.target||1)} ${esc(q.unit||"")}</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Quantidade</label><input id="hqAdd" class="field" type="number" min="0.1" step="0.1" value="1"><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="hqAddSave">Adicionar</button></div></div>`);byId("hqAddSave").onclick=()=>{let n=Math.max(.1,Number(byId("hqAdd").value||0));q.log=q.log||{};q.log[iso()]=Number(q.log[iso()]||0)+n;let reached=q.log[iso()]>=Number(q.target||1);if(reached&&!done(h)){toggle(h.id,iso())}else save();closeM();render();toast(reached?"Meta do dia atingida e hábito concluído.":"Progresso atualizado.","success")}}

function compositeProgressV59(g){let list=Array.isArray(g.components)?g.components:[];if(!list.length)return 0;let vals=list.map(c=>{if(c.type==="project"){let p=D.projects.find(x=>sameId(x.id,c.id));return p?v59ProjectPct(p):0}if(c.type==="habit"){let h=D.habits.find(x=>sameId(x.id,c.id));return h?habitSmartStreakV59(h).rate:0}if(c.type==="challenge"){let x=D.challenges.find(v=>sameId(v.id,c.id));return x?challengePctV59(x):0}return 0});return vals.reduce((a,b)=>a+b,0)/vals.length}
function compositeGoalsBlockV59(){return`<div class="card compositeGoalPanel"><div class="row between"><div><span class="kicker">METAS COMPOSTAS</span><h2>Objetivos com várias frentes</h2><p class="sub">Combine metas, hábitos e desafios. O progresso geral é calculado pela média dos componentes.</p></div><button class="btn" data-composite-new>＋ Meta composta</button></div><div class="lifeGrid compact">${D.compositeGoals.length?D.compositeGoals.map(g=>{let pct=compositeProgressV59(g);return`<div class="compositeMini"><div class="row between"><b>${esc(g.title)}</b>${v59Traffic(pct>=100?"green":pct>=60?"yellow":"neutral",`${pctText(pct)}%`)}</div><div class="bar"><i style="width:${pct}%"></i></div><small>${(g.components||[]).length} componente(s)</small><div><button class="link" data-composite-edit="${g.id}">Editar</button> <button class="link danger" data-composite-del="${g.id}">Excluir</button></div></div>`}).join(""):`<p class="sub">Ex.: “Projeto Saúde” = treinar + dormir bem + meta de peso.</p>`}</div></div>`}
function stageBlockV59(p){let stage=p.done?"Concluído":p.stage||"Em andamento",idx=Math.max(0,V59_PROJECT_STAGES.indexOf(stage));return`<div class="projectStageV59"><div class="row between"><span>ETAPA</span>${v59Traffic(stage==="Concluído"?"green":stage==="Revisão"?"yellow":"neutral",stage)}</div><div class="stageDots">${V59_PROJECT_STAGES.map((s,i)=>`<i class="${i<=idx?"on":""}" title="${s}"></i>`).join("")}</div><button class="link" data-project-stage="${p.id}">Avançar etapa ›</button></div>`}
const projectsBeforeV59=views.projects;
function projectsV59(){let html=projectsBeforeV59();D.projects.forEach(p=>{let marker=`data-project-card="${p.id}">`,start=html.indexOf(marker);if(start<0)return;let action=html.indexOf('<div class="projectActions">',start);if(action<0)return;html=html.slice(0,action)+stageBlockV59(p)+html.slice(action)});return html+compositeGoalsBlockV59()}
views.projects=projectsV59;
function compositeModalV59(g=null){let x=g||{id:id(),title:"",components:[]},options=[...D.projects.map(p=>({type:"project",id:p.id,title:`◆ ${p.title}`})),...D.habits.map(h=>({type:"habit",id:h.id,title:`✓ ${h.title}`})),...D.challenges.map(c=>({type:"challenge",id:c.id,title:`🏁 ${c.title}`}))];modal(`<div class="mh"><div><span class="kicker">META COMPOSTA</span><h2>${g?"Editar":"Nova"} meta composta</h2></div><button class="x" id="cx">×</button></div><div class="form"><label>Nome</label><input id="cgTitle" class="field" maxlength="100" value="${esc(x.title)}"><label>Componentes</label><div class="componentPicker">${options.length?options.map(o=>`<label><input type="checkbox" data-cg-component="${o.type}:${o.id}" ${(x.components||[]).some(c=>c.type===o.type&&sameId(c.id,o.id))?"checked":""}><span>${esc(o.title)}</span></label>`).join(""):`<p class="sub">Crie projetos, hábitos ou desafios primeiro.</p>`}</div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="cgSave">Salvar</button></div></div>`);byId("cgSave").onclick=()=>{let title=byId("cgTitle").value.trim(),components=[...document.querySelectorAll("[data-cg-component]:checked")].map(el=>{let[t,...rid]=el.dataset.cgComponent.split(":");return{type:t,id:rid.join(":")}});if(!title||!components.length)return toast("Informe o nome e escolha pelo menos um componente.","warn");let obj={...x,title,components};let i=D.compositeGoals.findIndex(v=>sameId(v.id,obj.id));i>=0?D.compositeGoals[i]=obj:D.compositeGoals.unshift(obj);save();closeM();render();toast("Meta composta salva.","success")}}

function financeReserveAccountBalanceV59(accountId){let a=D.finance.accounts.find(x=>Number(x.id)===Number(accountId));return a?financeAccountBalanceV56(a):0}
function financeReserveUsedV59(accountId){return D.financeReserves.filter(r=>Number(r.accountId)===Number(accountId)).reduce((s,r)=>s+Number(r.amount||0),0)}
function financeForecastV59(days=30){let end=new Date();end.setDate(end.getDate()+days);let endIso=iso(end),o=financeOwnerId(),accounts=D.finance.accounts.filter(a=>financeOwn(a,o)),balance=accounts.reduce((s,a)=>s+financeAccountBalanceV56(a),0),inc=D.finance.incomes.filter(x=>financeOwn(x,o)&&String(x.status)!=="received"&&String(x.expected_date||"")>=iso()&&String(x.expected_date||"")<=endIso).reduce((s,x)=>s+Number(x.amount_expected||0),0),exp=D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.status)!=="paid"&&String(x.due_date||"")>=iso()&&String(x.due_date||"")<=endIso).reduce((s,x)=>s+Number(x.amount||0),0);return{balance,inc,exp,projected:balance+inc-exp}}
function financeSmartPanelV59(){let f=financeForecastV59(30),reserved=D.financeReserves.reduce((s,r)=>s+Number(r.amount||0),0),available=f.balance-reserved;return`<div class="card financeSmartV59"><div class="row between"><div><span class="kicker">PLANEJAMENTO INTELIGENTE</span><h2>Previsão de 30 dias e reservas</h2></div><button class="btn" data-reserve-new>＋ Reserva</button></div><div class="lifeStatGrid"><div class="lifeStat"><small>SALDO REAL</small><b>${moneyBR(f.balance)}</b></div><div class="lifeStat"><small>RESERVADO</small><b>${moneyBR(reserved)}</b></div><div class="lifeStat"><small>DISPONÍVEL</small><b>${moneyBR(available)}</b></div><div class="lifeStat"><small>PREVISÃO 30D</small><b class="${f.projected<0?"negative":"positive"}">${moneyBR(f.projected)}</b></div></div><p class="sub">Previsão conhecida: +${moneyBR(f.inc)} a receber e −${moneyBR(f.exp)} a pagar nos próximos 30 dias.</p><div class="reserveList">${D.financeReserves.length?D.financeReserves.map(r=>{let pct=Math.min(100,Number(r.amount||0)/Math.max(1,Number(r.target||1))*100),a=D.finance.accounts.find(x=>Number(x.id)===Number(r.accountId));return`<div class="reserveRow"><div class="grow"><b>${esc(r.title)}</b><small>${esc(a?.name||"Sem conta")} • ${moneyBR(r.amount)} / ${moneyBR(r.target)}</small><div class="bar"><i style="width:${pct}%"></i></div></div><button class="pill" data-reserve-add="${r.id}">＋</button><button class="iconAction" data-reserve-edit="${r.id}">✎</button><button class="iconAction danger" data-reserve-del="${r.id}">×</button></div>`}).join(""):`<p class="sub">Crie reservas para emergência, viagem, carro ou qualquer meta. O valor fica separado logicamente sem alterar o saldo real da conta.</p>`}</div></div>`}
const financeBeforeV59=views.finance;
function financeV59(){let html=financeBeforeV59();return(financeTab==="dashboard"||financeTab==="planning")?html+financeSmartPanelV59():html}
views.finance=financeV59;
function reserveModalV59(r=null){let x=r||{id:id(),title:"",target:0,amount:0,accountId:D.finance.accounts.find(a=>financeOwn(a,financeOwnerId()))?.id||null,linkedProjectId:""},accounts=D.finance.accounts.filter(a=>financeOwn(a,financeOwnerId())),moneyProjects=D.projects.filter(p=>p.type==="money");modal(`<div class="mh"><div><span class="kicker">RESERVA FINANCEIRA</span><h2>${r?"Editar":"Nova"} reserva</h2></div><button class="x" id="cx">×</button></div><div class="form"><label>Nome</label><input id="rvTitle" class="field" value="${esc(x.title)}" placeholder="Ex.: Reserva de emergência"><div class="formGrid2"><div><label>Meta</label><input id="rvTarget" class="field" type="number" min="0" step="0.01" value="${Number(x.target||0)}"></div><div><label>Valor reservado</label><input id="rvAmount" class="field" type="number" min="0" step="0.01" value="${Number(x.amount||0)}"></div></div><label>Conta/carteira</label><select id="rvAccount" class="field"><option value="">Sem conta específica</option>${accounts.map(a=>`<option value="${a.id}" ${Number(x.accountId)===Number(a.id)?"selected":""}>${esc(a.name)} • ${moneyBR(financeAccountBalanceV56(a))}</option>`).join("")}</select><label>Vincular a Meta Financeira</label><select id="rvProject" class="field"><option value="">Sem vínculo</option>${moneyProjects.map(p=>`<option value="${p.id}" ${sameId(x.linkedProjectId,p.id)?"selected":""}>${esc(p.title)}</option>`).join("")}</select><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="rvSave">Salvar reserva</button></div></div>`);byId("rvSave").onclick=()=>{let title=byId("rvTitle").value.trim(),target=Math.max(0,Number(byId("rvTarget").value||0)),amount=Math.max(0,Number(byId("rvAmount").value||0)),accountId=Number(byId("rvAccount").value)||null,linkedProjectId=byId("rvProject").value||"";if(!title||target<=0)return toast("Informe nome e meta da reserva.","warn");let accountBal=accountId?financeReserveAccountBalanceV59(accountId):Infinity,other=accountId?financeReserveUsedV59(accountId)-Number(x.amount||0):0;if(amount+other>accountBal)return toast("O total reservado ultrapassa o saldo real dessa conta.","warn","Reserva maior que o saldo");let obj={...x,title,target,amount,accountId,linkedProjectId};let i=D.financeReserves.findIndex(v=>sameId(v.id,obj.id));i>=0?D.financeReserves[i]=obj:D.financeReserves.unshift(obj);let p=D.projects.find(v=>sameId(v.id,linkedProjectId));if(p){p.current=amount;p.target=target;p.done=amount>=target;p.stage=p.done?"Concluído":p.stage||"Em andamento";p.linkedReserveId=obj.id}save();closeM();render();toast("Reserva financeira atualizada.","success")}}
function reserveAddV59(r){modal(`<div class="mh"><div><h2>Adicionar à reserva</h2><p class="sub">${esc(r.title)} • ${moneyBR(r.amount)} de ${moneyBR(r.target)}</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Valor</label><input id="rvAdd" class="field" type="number" min="0.01" step="0.01" value="100"><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="rvAddSave">Adicionar</button></div></div>`);byId("rvAddSave").onclick=()=>{let n=Math.max(.01,Number(byId("rvAdd").value||0)),accountBal=r.accountId?financeReserveAccountBalanceV59(r.accountId):Infinity,other=r.accountId?financeReserveUsedV59(r.accountId)-Number(r.amount||0):0;if(r.amount+n+other>accountBal)return toast("Esse valor deixaria o total reservado acima do saldo real da conta.","warn");r.amount=Math.min(Number(r.target||Infinity),Number(r.amount||0)+n);let p=D.projects.find(v=>sameId(v.id,r.linkedProjectId));if(p){p.current=r.amount;p.done=p.current>=p.target;p.stage=p.done?"Concluído":p.stage}save();closeM();render();toast("Valor reservado.","success")}}

function v59AttentionItems(){let out=[],today=iso(),tom=new Date();tom.setDate(tom.getDate()+1);let tomorrow=iso(tom),pendingHabits=D.habits.filter(h=>!rest(h)&&!done(h));if(pendingHabits.length)out.push({level:pendingHabits.length>3?"yellow":"neutral",title:`${pendingHabits.length} hábito(s) pendente(s)`,sub:"Feche o que foi planejado para hoje.",nav:"habits"});D.missions.filter(m=>!m.done).forEach(m=>{let d=m.due||m.scheduleDate;if(d&&d<=tomorrow)out.push({level:d<today?"red":"yellow",title:m.title,sub:d<today?"Missão atrasada":d===today?"Vence hoje":"Vence amanhã",nav:"missions"})});D.projects.filter(p=>!p.done&&p.due).forEach(p=>{let d=v59Days(p.due);if(d!=null&&d<=3)out.push({level:d<0?"red":"yellow",title:p.title,sub:d<0?"Meta atrasada":`Prazo em ${d} dia(s)`,nav:"projects"})});let o=financeOwnerId();D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.status)!=="paid").forEach(x=>{let d=v59Days(x.due_date);if(d!=null&&d<=3)out.push({level:d<0?"red":"yellow",title:x.description,sub:d<0?"Conta vencida":`Vence em ${d} dia(s)`,nav:"finance"})});D.projects.filter(p=>p.type==="reading"&&!p.done).forEach(p=>{let r=readingPaceV58(p);if(r.status==="Precisa acelerar"||r.status==="Prazo vencido")out.push({level:r.status==="Prazo vencido"?"red":"yellow",title:p.title,sub:`Leitura: ${r.status.toLowerCase()} • ${r.required.toLocaleString("pt-BR",{maximumFractionDigits:1})} pág./dia`,nav:"library"})});return out.slice(0,8)}
function todayWidgetV59(key){let active=D.habits.filter(h=>!rest(h)),doneN=active.filter(h=>done(h)).length,missions=D.missions.filter(m=>!m.done&&(m.due===iso()||m.scheduleDate===iso()||!m.due&&!m.scheduleDate)).slice(0,5),reading=D.library.find(b=>b.status==="Lendo")||D.projects.find(p=>p.type==="reading"&&!p.done),check=D.checkins.find(c=>c.date===iso()),f=financeForecastV59(30);if(key==="attention"){let items=v59AttentionItems();return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">ATENÇÃO AGORA</span><h2>${items.length?"O que merece foco":"Tudo sob controle"}</h2></div><button class="pill" data-notification-center>Central de alertas</button></div>${items.length?`<div class="attentionList">${items.map((x,i)=>`<button data-attention-nav="${x.nav}">${v59Traffic(x.level,x.level==="red"?"Urgente":x.level==="yellow"?"Atenção":"Hoje")}<div><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></div><span>›</span></button>`).join("")}</div>`:`<p class="sub">Nenhuma pendência urgente detectada nos seus dados.</p>`}</section>`}if(key==="habits")return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">HÁBITOS</span><h2>${doneN}/${active.length} concluídos</h2></div><button class="link" data-nav="habits">Abrir ›</button></div><div class="bar"><i style="width:${active.length?doneN/active.length*100:0}%"></i></div><div class="todayMiniRows">${active.slice(0,5).map(h=>`<button data-open-habit="${h.id}"><span>${done(h)?"✓":"○"}</span><b>${esc(h.title)}</b>${h.quantitative?.enabled?`<small>${Number(habitQuantValueV59(h)).toLocaleString("pt-BR",{maximumFractionDigits:1})}/${h.quantitative.target} ${esc(h.quantitative.unit||"")}</small>`:""}</button>`).join("")||`<p class="sub">Nenhum hábito para hoje.</p>`}</div></section>`;if(key==="missions")return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">MISSÕES</span><h2>${missions.length?`${missions.length} para acompanhar`:"Sem missões do dia"}</h2></div><button class="link" data-nav="missions">Abrir ›</button></div><div class="todayMiniRows">${missions.map(m=>`<button data-open-mission="${m.id}"><span>⚑</span><b>${esc(m.title)}</b><small>${m.due?toolDateLabel(m.due):"Sem prazo"}</small></button>`).join("")||`<p class="sub">Você pode usar esse espaço para uma prioridade importante.</p>`}</div></section>`;if(key==="reading"){let title=reading?.title||"Nenhuma leitura ativa",cur=Number(reading?.currentPage??reading?.current??0),target=Number(reading?.totalPages??reading?.target??0),pct=target?Math.min(100,cur/target*100):0;return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">LEITURA</span><h2>${esc(title)}</h2></div><button class="link" data-nav="library">Biblioteca ›</button></div>${target?`<div class="label"><span>${cur}/${target} páginas</span><b>${pctText(pct)}%</b></div><div class="bar"><i style="width:${pct}%"></i></div>`:`<p class="sub">Adicione um livro e marque como Lendo.</p>`}${reading?`<button class="pill" data-library-quick-current>＋ Registrar páginas</button>`:""}</section>`}if(key==="finance")return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">FINANÇAS</span><h2>Previsão de 30 dias</h2></div><button class="link" data-nav="finance">Abrir ›</button></div><div class="financeTodayLine"><div><small>Saldo real</small><b>${moneyBR(f.balance)}</b></div><div><small>Projetado</small><b class="${f.projected<0?"negative":"positive"}">${moneyBR(f.projected)}</b></div></div><p class="sub">${moneyBR(f.inc)} a receber • ${moneyBR(f.exp)} a pagar.</p></section>`;if(key==="checkin")return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">CHECK-IN DIÁRIO</span><h2>${check?"Registrado hoje":"30 segundos sobre seu dia"}</h2></div>${v59Traffic(check?"green":"yellow",check?"Feito":"Pendente")}</div>${check?`<div class="checkinSummary"><span>🙂 ${check.mood}/5</span><span>⚡ ${check.energy}/5</span><span>☾ ${check.sleep||"—"}h</span><span>💧 ${check.water||0}ml</span></div><button class="pill" data-daily-checkin>Editar check-in</button>`:`<p class="sub">Humor, energia, sono, água, peso opcional e uma nota curta.</p><button class="btn" data-daily-checkin>Fazer check-in</button>`}</section>`;if(key==="week"){let start=new Date();start.setDate(start.getDate()-6);let habitDone=D.history.filter(x=>x.type==="habit_done"&&v59Date(x.date)>=start).length,pages=D.tools.reading.filter(x=>v59Date(x.date)>=start).reduce((s,x)=>s+Number(x.pages||0),0),work=D.tools.exercise.filter(x=>v59Date(x.date)>=start).length;return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">ÚLTIMOS 7 DIAS</span><h2>Seu ritmo recente</h2></div><button class="link" data-week-review>Revisão ›</button></div><div class="checkinSummary"><span>✓ ${habitDone} hábitos</span><span>📖 ${pages} pág.</span><span>⚔ ${work} treino(s)</span><span>⚑ ${D.missions.filter(m=>m.done&&v59Date(m.completedAt)>=start).length} missões</span></div></section>`}if(key==="focus"){let pins=D.settings.focusPins.map(v59ResolvePin).filter(Boolean);return`<section class="card todayWidget"><div class="widgetHead"><div><span class="kicker">FIXADOS</span><h2>Seu foco principal</h2></div><button class="link" data-home-customize>Personalizar ›</button></div>${pins.length?`<div class="todayMiniRows">${pins.map(p=>{let pct=p.type==="project"?v59ProjectPct(p.obj):p.type==="book"?libraryPctV59(p.obj):challengePctV59(p.obj);return`<button data-pin-open="${p.type}:${p.obj.id}"><span>${p.type==="project"?"◆":p.type==="book"?"📚":"🏁"}</span><b>${esc(p.obj.title)}</b><small>${pctText(pct)}%</small></button>`}).join("")}</div>`:`<p class="sub">Fixe até 3 metas, livros ou desafios para aparecerem aqui.</p>`}</section>`}return""}
function homeV59(){librarySyncV59();let widgets=(D.settings.homeWidgets||[]).filter(k=>!D.settings.homeHidden.includes(k));return`<div class="lifeHomeTop"><div><span class="sub">${new Date().getHours()<12?"Bom dia":new Date().getHours()<18?"Boa tarde":"Boa noite"},</span><h1>${esc(D.profile.name)}</h1><p>Abra o Smart Life e veja o que merece atenção agora.</p></div><div class="row"><button class="pill" data-life-assistant>✦ Perguntar aos dados</button><button class="pill" data-daily-review>☾ Revisar dia</button><button class="pill" data-home-customize>⚙ Personalizar</button></div></div><div class="lifeHeroStrip"><div><small>STREAK</small><b>🔥 ${D.streak} dias</b></div><div><small>XP HOJE</small><b>ϟ ${todayXP()}</b></div><div><small>ATENÇÃO</small><b>${v59AttentionItems().filter(x=>x.level==="red").length} urgente(s)</b></div><div><small>NÍVEL</small><b>✦ ${D.level}</b></div></div><div class="todayWidgetGrid">${widgets.map(todayWidgetV59).join("")}</div>`}
views.home=homeV59;

function dailyCheckinModalV59(){let c=D.checkins.find(x=>x.date===iso())||{id:id(),date:iso(),mood:3,energy:3,sleep:"",water:"",weight:"",note:""};modal(`<div class="mh"><div><span class="kicker">CHECK-IN DIÁRIO</span><h2>Como foi seu dia?</h2><p class="sub">Leva menos de um minuto e alimenta seus insights sem gerar pontos artificiais.</p></div><button class="x" id="cx">×</button></div><div class="form"><div class="formGrid2"><div><label>Humor</label><select id="ciMood" class="field">${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(c.mood)===n?"selected":""}>${n}/5</option>`).join("")}</select></div><div><label>Energia</label><select id="ciEnergy" class="field">${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(c.energy)===n?"selected":""}>${n}/5</option>`).join("")}</select></div></div><div class="formGrid2"><div><label>Sono (h)</label><input id="ciSleep" class="field" type="number" min="0" max="24" step="0.1" value="${esc(c.sleep)}"></div><div><label>Água (ml)</label><input id="ciWater" class="field" type="number" min="0" step="50" value="${esc(c.water)}"></div></div><label>Peso (kg, opcional)</label><input id="ciWeight" class="field" type="number" min="20" max="500" step="0.1" value="${esc(c.weight)}"><label>Uma frase sobre o dia</label><textarea id="ciNote" class="field" maxlength="500">${esc(c.note||"")}</textarea><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="ciSave">Salvar check-in</button></div></div>`);byId("ciSave").onclick=()=>{let obj={...c,mood:Number(byId("ciMood").value),energy:Number(byId("ciEnergy").value),sleep:byId("ciSleep").value?Number(byId("ciSleep").value):"",water:byId("ciWater").value?Number(byId("ciWater").value):"",weight:byId("ciWeight").value?Number(byId("ciWeight").value):"",note:byId("ciNote").value.trim(),updatedAt:new Date().toISOString()};let i=D.checkins.findIndex(x=>x.date===obj.date);i>=0?D.checkins[i]=obj:D.checkins.unshift(obj);let mood=D.tools.mood.find(x=>x.date===obj.date&&x.source==="daily-checkin");if(mood){mood.mood=obj.mood;mood.energy=obj.energy;mood.note=obj.note}else D.tools.mood.unshift({id:id(),date:obj.date,createdAt:new Date().toISOString(),kind:"mood",mood:obj.mood,energy:obj.energy,note:obj.note,source:"daily-checkin",attachments:[]});if(obj.weight){let w=D.tools.weight.find(x=>x.date===obj.date&&x.source==="daily-checkin");if(w)w.kg=obj.weight;else D.tools.weight.unshift({id:id(),date:obj.date,createdAt:new Date().toISOString(),kind:"weight",kg:obj.weight,source:"daily-checkin",attachments:[]})}save();closeM();render();toast("Check-in salvo. Ele será usado nos relatórios e insights.","success","Dia registrado")}}
function dailyReviewModalV59(){let active=D.habits.filter(h=>!rest(h)),dn=active.filter(h=>done(h)).length,pages=D.tools.reading.filter(x=>x.date===iso()).reduce((s,x)=>s+Number(x.pages||0),0),work=D.tools.exercise.filter(x=>x.date===iso()).length,o=financeOwnerId(),spent=D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.purchase_date||x.due_date||"").slice(0,10)===iso()).reduce((s,x)=>s+Number(x.amount||0),0),old=D.dailyReviews.find(x=>x.date===iso());modal(`<div class="mh"><div><span class="kicker">REVISÃO DO DIA</span><h2>${new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"2-digit",month:"long"})}</h2></div><button class="x" id="cx">×</button></div><div class="lifeReviewNumbers"><span>✓ <b>${dn}/${active.length}</b> hábitos</span><span>📖 <b>${pages}</b> páginas</span><span>⚔ <b>${work}</b> treino(s)</span><span>💰 <b>${moneyBR(spent)}</b> lançado</span></div><div class="form"><label>O que funcionou hoje?</label><textarea id="drWin" class="field" maxlength="700">${esc(old?.win||"")}</textarea><label>O que precisa de atenção amanhã?</label><textarea id="drTomorrow" class="field" maxlength="700">${esc(old?.tomorrow||"")}</textarea><div class="modalActions"><button class="pill" data-daily-checkin>${D.checkins.some(x=>x.date===iso())?"Editar check-in":"Fazer check-in"}</button><button class="btn" id="drSave">Salvar revisão</button></div></div>`);byId("drSave").onclick=()=>{let obj={id:old?.id||id(),date:iso(),win:byId("drWin").value.trim(),tomorrow:byId("drTomorrow").value.trim(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};let i=D.dailyReviews.findIndex(x=>x.date===iso());i>=0?D.dailyReviews[i]=obj:D.dailyReviews.unshift(obj);save();closeM();toast("Revisão do dia salva.","success")}}
function homeCustomizeModalV59(){let order=D.settings.homeWidgets.slice(),hidden=new Set(D.settings.homeHidden||[]),pinOptions=[...D.projects.filter(p=>!p.done).map(p=>({key:v59EntityKey("project",p.id),label:`◆ ${p.title}`})),...D.library.filter(b=>b.status!=="Concluído").map(b=>({key:v59EntityKey("book",b.id),label:`📚 ${b.title}`})),...D.challenges.filter(c=>challengePctV59(c)<100).map(c=>({key:v59EntityKey("challenge",c.id),label:`🏁 ${c.title}`}))];let draw=()=>{byId("homeWidgetEditor").innerHTML=order.map((k,i)=>{let label=V59_HOME_WIDGETS.find(x=>x[0]===k)?.[1]||k;return`<div class="homeWidgetEditRow"><label><input type="checkbox" data-home-widget-show="${k}" ${!hidden.has(k)?"checked":""}><span>${label}</span></label><div><button class="iconAction" data-home-up="${k}" ${i===0?"disabled":""}>↑</button><button class="iconAction" data-home-down="${k}" ${i===order.length-1?"disabled":""}>↓</button></div></div>`}).join("");byId("homeWidgetEditor").querySelectorAll("[data-home-up]").forEach(b=>b.onclick=()=>{let i=order.indexOf(b.dataset.homeUp);[order[i-1],order[i]]=[order[i],order[i-1]];draw()});byId("homeWidgetEditor").querySelectorAll("[data-home-down]").forEach(b=>b.onclick=()=>{let i=order.indexOf(b.dataset.homeDown);[order[i+1],order[i]]=[order[i],order[i+1]];draw()})};modal(`<div class="mh"><div><span class="kicker">HOME PERSONALIZÁVEL</span><h2>Escolha o que aparece primeiro</h2></div><button class="x" id="cx">×</button></div><div id="homeWidgetEditor"></div><div class="form"><label>Fixar até 3 focos</label><div class="componentPicker">${pinOptions.length?pinOptions.map(o=>`<label><input type="checkbox" data-home-pin="${esc(o.key)}" ${D.settings.focusPins.includes(o.key)?"checked":""}><span>${esc(o.label)}</span></label>`).join(""):`<p class="sub">Crie uma meta, livro ou desafio para fixar.</p>`}</div><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="homeWidgetSave">Salvar Home</button></div></div>`);draw();byId("homeWidgetSave").onclick=()=>{let checked=[...document.querySelectorAll("[data-home-pin]:checked")].slice(0,3).map(x=>x.dataset.homePin);D.settings.homeWidgets=order;D.settings.homeHidden=[...document.querySelectorAll("[data-home-widget-show]:not(:checked)")].map(x=>x.dataset.homeWidgetShow);D.settings.focusPins=checked;save();closeM();render();toast("Home personalizada.","success")}}

function monthMetricsV59(month){let prev=v59MonthShift(month,-1),habit=(m)=>D.history.filter(x=>x.type==="habit_done"&&String(x.date||"").startsWith(m)).length,pages=(m)=>D.tools.reading.filter(x=>String(x.date||"").startsWith(m)).reduce((s,x)=>s+Number(x.pages||0),0),work=(m)=>D.tools.exercise.filter(x=>String(x.date||"").startsWith(m)).length,sleep=(m)=>{let a=D.tools.sleep.filter(x=>String(x.date||"").startsWith(m));return a.length?a.reduce((s,x)=>s+Number(x.hours||0),0)/a.length:0},spent=(m)=>{let o=financeOwnerId();return D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.purchase_date||x.due_date||"").startsWith(m)).reduce((s,x)=>s+Number(x.amount||0),0)};return{current:{habit:habit(month),pages:pages(month),work:work(month),sleep:sleep(month),spent:spent(month)},prev:{habit:habit(prev),pages:pages(prev),work:work(prev),sleep:sleep(prev),spent:spent(prev)},prevMonth:prev}}
function deltaTextV59(a,b,invert=false){if(!b&&a)return"novo";if(!b&&!a)return"0%";let d=(a-b)/Math.abs(b)*100;if(invert)d*=-1;return`${d>=0?"+":""}${Math.round(d)}%`}
function insightsLocalV59(){let lines=[],days=[];for(let i=0;i<30;i++){let d=new Date();d.setDate(d.getDate()-i);let ds=iso(d),active=D.habits.filter(h=>!rest(h,ds)),rate=active.length?active.filter(h=>done(h,ds)).length/active.length*100:0,sleep=D.tools.sleep.find(x=>x.date===ds)?.hours??D.checkins.find(x=>x.date===ds)?.sleep,mood=D.tools.mood.find(x=>x.date===ds)?.mood??D.checkins.find(x=>x.date===ds)?.mood,exercise=D.tools.exercise.some(x=>x.date===ds);days.push({ds,rate,sleep:Number(sleep||0),mood:Number(mood||0),exercise})}let slept=days.filter(x=>x.sleep>=7),short=days.filter(x=>x.sleep>0&&x.sleep<7);if(slept.length>=3&&short.length>=3){let a=slept.reduce((s,x)=>s+x.rate,0)/slept.length,b=short.reduce((s,x)=>s+x.rate,0)/short.length;lines.push({icon:"☾",title:"Sono × hábitos",text:`Nos seus registros, dias com 7h+ de sono tiveram ${pctText(a)}% de conclusão de hábitos contra ${pctText(b)}% nos dias com menos sono. É uma associação observada, não uma causa.`})}let ex=days.filter(x=>x.exercise&&x.mood),no=days.filter(x=>!x.exercise&&x.mood);if(ex.length>=3&&no.length>=3){let a=ex.reduce((s,x)=>s+x.mood,0)/ex.length,b=no.reduce((s,x)=>s+x.mood,0)/no.length;lines.push({icon:"⚔",title:"Exercício × humor",text:`Humor médio de ${a.toFixed(1)}/5 nos dias com exercício e ${b.toFixed(1)}/5 nos demais dias registrados.`})}let o=financeOwnerId(),m=financeMonth(),expenses=D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.purchase_date||x.due_date||"").startsWith(m)),cats={};expenses.forEach(x=>{let name=financeCatName(x.category_id)||"Sem categoria";cats[name]=(cats[name]||0)+Number(x.amount||0)});let top=Object.entries(cats).sort((a,b)=>b[1]-a[1])[0];if(top)lines.push({icon:"💰",title:"Maior categoria de gasto",text:`${top[0]} concentra ${moneyBR(top[1])} em lançamentos deste mês.`});let p=D.projects.find(x=>x.type==="reading"&&!x.done);if(p){let r=readingPaceV58(p);lines.push({icon:"📖",title:"Ritmo de leitura",text:`${p.title}: ${r.status}. Para o prazo atual, o ritmo necessário é ${r.required.toLocaleString("pt-BR",{maximumFractionDigits:1})} página(s)/dia.`})}if(!lines.length)lines.push({icon:"✦",title:"Ainda faltam dados",text:"Continue registrando sono, humor, exercícios, hábitos, leitura e finanças. O Smart Life só mostra relações quando há amostra mínima."});return lines}
function achievementListV59(){let year=new Date().getFullYear(),books=D.library.filter(b=>b.status==="Concluído").length,work=D.tools.exercise.length,habit=D.history.filter(x=>x.type==="habit_done").length,days=D.checkins.length,items=[[habit>=100,"✓","100 hábitos concluídos"],[work>=50,"⚔","50 treinos registrados"],[books>=10,"📚","10 livros concluídos"],[D.streak>=30,"🔥","30 dias de sequência"],[days>=30,"☀","30 check-ins diários"],[D.projects.filter(p=>p.done).length>=10,"◆","10 metas/projetos concluídos"],[D.library.filter(b=>b.status==="Concluído"&&String(b.finishedAt||"").startsWith(String(year))).length>=Number(D.settings.readingAnnualGoal||12),"🏆",`Meta de leitura ${year}`]];return items.filter(x=>x[0])}
function insightsViewV59(){let month=financeMonth(),mm=monthMetricsV59(month),ins=insightsLocalV59(),ach=achievementListV59();return header("Insights","Relatórios que cruzam seus dados sem inventar conclusões",`<div class="row"><button class="pill" data-life-assistant>✦ Perguntar aos dados</button><button class="btn" data-week-review>▥ Revisão semanal</button></div>`)+`<div class="card"><span class="kicker">COMPARAÇÃO MENSAL</span><h2>${financeMonthLabel(month)} × ${financeMonthLabel(mm.prevMonth)}</h2><div class="comparisonGrid"><div><small>Hábitos</small><b>${mm.current.habit}</b><span>${deltaTextV59(mm.current.habit,mm.prev.habit)}</span></div><div><small>Páginas</small><b>${mm.current.pages}</b><span>${deltaTextV59(mm.current.pages,mm.prev.pages)}</span></div><div><small>Treinos</small><b>${mm.current.work}</b><span>${deltaTextV59(mm.current.work,mm.prev.work)}</span></div><div><small>Sono médio</small><b>${mm.current.sleep.toFixed(1)}h</b><span>${deltaTextV59(mm.current.sleep,mm.prev.sleep)}</span></div><div><small>Gastos</small><b>${moneyBR(mm.current.spent)}</b><span>${deltaTextV59(mm.current.spent,mm.prev.spent,true)}</span></div></div></div><div class="section"><h2>Relações observadas</h2><span class="sub">O Smart Life exige dados mínimos antes de destacar um padrão.</span></div><div class="lifeGrid">${ins.map(x=>`<div class="card insightCard"><span>${x.icon}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div>`).join("")}</div><div class="card achievementsV59"><span class="kicker">CONQUISTAS SIGNIFICATIVAS</span><h2>Marcos que representam consistência</h2><div>${ach.length?ach.map(x=>`<span>${x[1]} ${esc(x[2])}</span>`).join(""):`<p class="sub">Seus primeiros grandes marcos aparecerão aqui conforme os dados crescerem.</p>`}</div></div>`}
views.insights=insightsViewV59;

function timelineItemsV59(){let out=[];D.history.forEach(x=>{if(x.date)out.push({date:x.date,time:x.time||"",type:"system",title:x.type==="habit_done"?`Hábito concluído${x.title?`: ${x.title}`:""}`:x.type==="mission_done"?`Missão concluída${x.title?`: ${x.title}`:""}`:x.type==="perfect"?"Dia completo":x.title||x.type,icon:x.type==="habit_done"?"✓":x.type==="mission_done"?"⚑":"✦"})});let labels={reading:"📖 Leitura",exercise:"⚔ Exercício",sleep:"☾ Sono",mood:"☀ Humor",nutrition:"💧 Nutrição",study:"📚 Estudo",organization:"▦ Organização",weight:"⚖ Peso",gratitude:"♡ Gratidão",notes:"✎ Nota",appearance:"☆ Autocuidado"};Object.entries(labels).forEach(([type,label])=>(D.tools[type]||[]).forEach(x=>out.push({date:x.date||String(x.createdAt||"").slice(0,10),time:String(x.createdAt||"").slice(11,16),type:`record-${type}`,id:x.id,title:x.book||x.subject||x.type||x.text||x.meal||label,sub:label,icon:label.split(" ")[0]})));D.finance.expenses.forEach(x=>out.push({date:String(x.purchase_date||x.due_date||"").slice(0,10),type:"finance",title:x.description,sub:`Despesa • ${moneyBR(x.amount)}`,icon:"−"}));D.finance.incomes.forEach(x=>out.push({date:String(x.received_date||x.expected_date||"").slice(0,10),type:"finance",title:x.description,sub:`Receita • ${moneyBR(x.amount_received||x.amount_expected)}`,icon:"+"}));D.dailyReviews.forEach(x=>out.push({date:x.date,type:"review",title:"Revisão do dia",sub:x.win||x.tomorrow||"Revisão registrada",icon:"☾"}));return out.filter(x=>x.date).sort((a,b)=>`${b.date} ${b.time}`.localeCompare(`${a.date} ${a.time}`)).slice(0,300)}
function timelineViewV59(){let items=timelineItemsV59();return header("Linha do tempo","Um diário automático do que aconteceu no Smart Life",`<button class="pill" data-daily-review>☾ Revisar hoje</button>`)+`<div class="timelineV59">${items.length?items.map(x=>`<div class="timelineRowV59"><span class="timelineIcon">${x.icon}</span><div class="grow"><small>${toolDateLabel(x.date)}${x.time?` • ${esc(x.time)}`:""}</small><b>${esc(x.title)}</b>${x.sub?`<p>${esc(x.sub)}</p>`:""}</div>${x.type.startsWith("record-")?`<button class="iconAction" data-record-attach="${x.type.slice(7)}:${x.id}" title="Adicionar anexo">▣</button>`:""}</div>`).join(""):`<div class="card sub">A linha do tempo será preenchida conforme você usar o aplicativo.</div>`}</div>`}
views.timeline=timelineViewV59;

let agendaMonthV59=financeMonth();
function calendarEventsV59(ds){let rows=[];D.missions.filter(m=>!m.done&&(m.due===ds||m.scheduleDate===ds)).forEach(m=>rows.push({icon:"⚑",title:m.title,nav:"missions"}));D.projects.filter(p=>!p.done&&p.due===ds).forEach(p=>rows.push({icon:"◆",title:p.title,nav:"projects"}));let o=financeOwnerId();D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.status)!=="paid"&&String(x.due_date||"").slice(0,10)===ds).forEach(x=>rows.push({icon:"▣",title:x.description,nav:"finance"}));return rows}
function monthCalendarV59(){let [y,m]=agendaMonthV59.split("-").map(Number),first=new Date(y,m-1,1,12),last=new Date(y,m,0,12),pad=first.getDay(),cells=[];for(let i=0;i<pad;i++)cells.push(null);for(let d=1;d<=last.getDate();d++){let date=new Date(y,m-1,d,12),ds=iso(date);cells.push({d,ds,events:calendarEventsV59(ds)})}return`<div class="card monthCalendarV59"><div class="row between"><div><span class="kicker">CALENDÁRIO INTEGRADO</span><h2>${first.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</h2></div><div class="row"><button class="iconAction" data-agenda-month-step="-1">‹</button><button class="pill" data-agenda-month-now>Hoje</button><button class="iconAction" data-agenda-month-step="1">›</button></div></div><div class="monthWeekdays">${["DOM","SEG","TER","QUA","QUI","SEX","SÁB"].map(x=>`<span>${x}</span>`).join("")}</div><div class="monthGrid">${cells.map(c=>c?`<button class="monthDay ${c.ds===iso()?"today":""}" data-calendar-day="${c.ds}"><b>${c.d}</b><div>${c.events.slice(0,3).map(e=>`<i title="${esc(e.title)}">${e.icon}</i>`).join("")}</div>${c.events.length>3?`<small>+${c.events.length-3}</small>`:""}</button>`:`<span></span>`).join("")}</div></div>`}
const agendaBeforeV59=views.agenda;
function agendaV59(){return agendaBeforeV59()+monthCalendarV59()}
views.agenda=agendaV59;
function calendarDayModalV59(ds){let ev=calendarEventsV59(ds),active=D.habits.filter(h=>!rest(h,ds));modal(`<div class="mh"><div><span class="kicker">${toolDateLabel(ds)}</span><h2>Agenda do dia</h2></div><button class="x" id="cx">×</button></div><div class="todayMiniRows">${ev.map(e=>`<button data-calendar-open="${e.nav}"><span>${e.icon}</span><b>${esc(e.title)}</b></button>`).join("")}${active.slice(0,8).map(h=>`<button data-calendar-habit="${h.id}"><span>${done(h,ds)?"✓":"○"}</span><b>${esc(h.title)}</b><small>Hábito</small></button>`).join("")||`<p class="sub">Sem itens para este dia.</p>`}</div>`)}

function answerLocalQuestionV59(q){let s=searchNormV56(q),month=financeMonth(),o=financeOwnerId();if(/quanto.*(gaste|gasto|despesa)/.test(s)){let n=D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.purchase_date||x.due_date||"").startsWith(month)).reduce((a,x)=>a+Number(x.amount||0),0);return`Você tem ${moneyBR(n)} em despesas registradas em ${financeMonthLabel(month)}.`}if(/onde.*(mais gasto|gastei)|categoria.*gasto/.test(s)){let cats={};D.finance.expenses.filter(x=>financeOwn(x,o)&&String(x.purchase_date||x.due_date||"").startsWith(month)).forEach(x=>{let k=financeCatName(x.category_id)||"Sem categoria";cats[k]=(cats[k]||0)+Number(x.amount||0)});let top=Object.entries(cats).sort((a,b)=>b[1]-a[1])[0];return top?`Sua maior categoria de gasto no mês é ${top[0]}, com ${moneyBR(top[1])}.`:"Ainda não há despesas suficientes neste mês."}if(/habit.*(deix|pior|menos)/.test(s)){let rows=D.habits.map(h=>({h,rate:habitSmartStreakV59(h).rate})).sort((a,b)=>a.rate-b.rate);return rows[0]?`O hábito com menor taxa nos últimos 120 dias é “${rows[0].h.title}”, com ${pctText(rows[0].rate)}% de conclusão nos dias programados.`:"Você ainda não cadastrou hábitos."}if(/(termin|acaba|final).*livr|ritmo.*leitura/.test(s)){let b=D.library.find(x=>x.status==="Lendo");if(!b)return"Nenhum livro está marcado como Lendo.";let st=libraryReadingStatsV59(b);return st.finish?`Mantendo a média recente de ${st.avg.toLocaleString("pt-BR",{maximumFractionDigits:1})} página(s)/dia, “${b.title}” tende a terminar por volta de ${st.finish.toLocaleDateString("pt-BR")}.`:`Ainda não há leituras recentes suficientes para prever o término de “${b.title}”.`}if(/amanha|amanhã/.test(q)){let d=new Date();d.setDate(d.getDate()+1);let ds=iso(d),m=D.missions.filter(x=>!x.done&&(x.due===ds||x.scheduleDate===ds)),p=D.projects.filter(x=>!x.done&&x.due===ds),e=D.finance.expenses.filter(x=>String(x.status)!=="paid"&&String(x.due_date||"").slice(0,10)===ds);return`Amanhã: ${m.length} missão(ões), ${p.length} meta(s) com prazo e ${e.length} conta(s) vencendo. Seus hábitos programados também aparecem na Agenda.`}return"Consigo responder localmente sobre gastos, categorias, hábitos, ritmo de leitura e agenda de amanhã. Para análises mais abertas, use também o Coordenador Gemini."}
function lifeAssistantModalV59(){modal(`<div class="mh"><div><span class="kicker">ASSISTENTE DOS SEUS DADOS</span><h2>Pergunte ao Smart Life</h2><p class="sub">Perguntas comuns são respondidas localmente, sem enviar dados para a internet.</p></div><button class="x" id="cx">×</button></div><div class="assistantSuggestionsV59"><button data-life-q="Quanto gastei este mês?">Quanto gastei este mês?</button><button data-life-q="Onde eu mais gastei?">Onde eu mais gastei?</button><button data-life-q="Qual hábito estou deixando mais de lado?">Qual hábito estou deixando mais de lado?</button><button data-life-q="Quando termino meu livro?">Quando termino meu livro?</button><button data-life-q="O que tenho amanhã?">O que tenho amanhã?</button></div><div class="form"><textarea id="lifeQuestion" class="field" maxlength="500" placeholder="Pergunte sobre seus próprios dados..."></textarea><button class="btn" id="lifeAsk">Perguntar</button></div><div id="lifeAnswer" class="card lifeAnswerV59"><p class="sub">A resposta aparecerá aqui.</p></div><div class="modalActions"><button class="pill" data-act="coord">Abrir Coordenador Gemini</button></div>`);let ask=()=>{let q=byId("lifeQuestion").value.trim();if(!q)return;byId("lifeAnswer").innerHTML=`<b>Resposta</b><p>${esc(answerLocalQuestionV59(q))}</p>`};byId("lifeAsk").onclick=ask;document.querySelectorAll("[data-life-q]").forEach(b=>b.onclick=()=>{byId("lifeQuestion").value=b.dataset.lifeQ;ask()})}

async function readAttachmentV59(file){if(!file)return null;if(file.size>1200000)throw new Error("Use um arquivo de até 1,2 MB.");return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res({id:id(),name:file.name.slice(0,120),type:file.type||"application/octet-stream",data:r.result,createdAt:new Date().toISOString()});r.onerror=()=>rej(r.error||new Error("Falha ao ler arquivo"));r.readAsDataURL(file)})}
function recordByTypeV59(type,rid){return(D.tools[type]||[]).find(x=>sameId(x.id,rid))}
function attachmentModalV59(target,title="Registro"){target.attachments=Array.isArray(target.attachments)?target.attachments:[];modal(`<div class="mh"><div><span class="kicker">ANEXOS</span><h2>${esc(title)}</h2><p class="sub">Fotos, comprovantes ou referências ficam salvos no backup local.</p></div><button class="x" id="cx">×</button></div><div class="attachmentListV59">${target.attachments.length?target.attachments.map(a=>`<div><span>▣</span><b>${esc(a.name)}</b><a href="${a.data}" download="${esc(a.name)}">Abrir</a><button class="iconAction danger" data-attachment-del="${a.id}">×</button></div>`).join(""):`<p class="sub">Nenhum anexo.</p>`}</div><label class="fileBtn" for="attachInputV59">＋ Adicionar arquivo</label><input id="attachInputV59" type="file" accept="image/*,application/pdf" hidden><p class="sub">Limite: 1,2 MB por arquivo para não deixar o backup pesado.</p>`);byId("attachInputV59").onchange=async()=>{try{let a=await readAttachmentV59(byId("attachInputV59").files?.[0]);if(a){target.attachments.unshift(a);save();attachmentModalV59(target,title);toast("Anexo salvo.","success")}}catch(e){toast(e.message,"warn")}};document.querySelectorAll("[data-attachment-del]").forEach(b=>b.onclick=()=>{target.attachments=target.attachments.filter(a=>a.id!==b.dataset.attachmentDel);save();attachmentModalV59(target,title)})}
const quickSimpleRecordBeforeV59=quickSimpleRecordModal;
quickSimpleRecordModal=function(kind,existing=null){quickSimpleRecordBeforeV59(kind,existing);if(kind!=="notes")return;let actions=byId("quickSimpleSave")?.closest(".modalActions");if(!actions)return;let link=document.createElement("div");link.className="formGrid2 noteLinkV59";link.innerHTML=`<div><label>Vincular a</label><select id="noteLinkType" class="field"><option value="">Sem vínculo</option><option value="project">Projeto/meta</option><option value="book">Livro</option><option value="challenge">Desafio</option></select></div><div><label>Item</label><select id="noteLinkId" class="field"><option value="">Selecione o tipo</option></select></div>`;actions.parentNode.insertBefore(link,actions);let typeEl=byId("noteLinkType"),idEl=byId("noteLinkId"),current=existing?.linkedEntity||null;let fill=()=>{let t=typeEl.value,list=t==="project"?D.projects:t==="book"?D.library:t==="challenge"?D.challenges:[];idEl.innerHTML=`<option value="">Sem vínculo</option>`+list.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join("");if(current&&current.type===t)idEl.value=current.id};if(current)typeEl.value=current.type||"";fill();typeEl.onchange=fill;let old=byId("quickSimpleSave").onclick,before=new Set(D.tools.notes.map(x=>String(x.id)));byId("quickSimpleSave").onclick=()=>{if(existing)existing.linkedEntity=typeEl.value&&idEl.value?{type:typeEl.value,id:idEl.value}:null;old();if(!existing){let rec=D.tools.notes.find(x=>!before.has(String(x.id)));if(rec){rec.linkedEntity=typeEl.value&&idEl.value?{type:typeEl.value,id:idEl.value}:null;save()}}}}
