function autoConnectV59(){let n=0;D.projects.filter(p=>p.type==="reading").forEach(p=>{let b=D.library.find(x=>sameId(x.projectId,p.id)||searchNormV56(x.title)===searchNormV56(p.title));if(!b){D.library.unshift({id:id(),title:p.title,author:"",totalPages:Number(p.target||0),currentPage:Number(p.current||0),status:p.done?"Concluído":"Lendo",rating:0,notes:"",projectId:p.id,attachments:[],createdAt:new Date().toISOString(),finishedAt:p.done?iso():""});n++}else if(!b.projectId){b.projectId=p.id;n++}});let rules=[{re:/água|agua|hidrata/,source:"nutrition",target:2000,unit:"ml"},{re:/ler|leitura|página|pagina/,source:"reading",target:20,unit:"páginas"},{re:/estud|curso|aula/,source:"study",target:30,unit:"min"},{re:/trein|exerc|corrid|caminh/,source:"exercise",target:30,unit:"min"},{re:/sono|dorm/,source:"sleep",target:8,unit:"h"}];D.habits.forEach(h=>{if(h.quantitative?.enabled)return;let r=rules.find(x=>x.re.test(searchNormV56(h.title)));if(r){let inferred=inferGoalFromTitle(h.title,r.source)||r.target;h.quantitative={enabled:true,target:inferred,unit:r.unit,source:r.source,log:{}};D.toolSettings.links[r.source]={targetType:"habit",targetId:h.id,goal:inferred,unit:r.unit};n++}});save();render();toast(n?`${n} conexão(ões) criada(s). Nenhum registro foi duplicado.`:"Não encontrei novas conexões seguras para criar.",n?"success":"info","Automação entre módulos")}
