function financeTransfersForAccountV60(accountId){let o=financeOwnerId(),id=Number(accountId);return (D.finance.internal_transfers||[]).filter(t=>financeOwn(t,o)&&(Number(t.from_account_id)===id||Number(t.to_account_id)===id)&&String(t.status||"completed")!=="cancelled")}
financeAccountBalanceV56=function(a){let o=financeOwnerId(),aid=Number(a.id),opening=Number(a.initial_balance??a.opening_balance??a.balance??0)||0,inc=D.finance.incomes.filter(x=>financeOwn(x,o)&&Number(x.account_id)===aid&&String(x.status)==="received").reduce((s,x)=>s+Number(x.amount_received||x.amount_expected||0),0),exp=D.finance.expenses.filter(x=>financeOwn(x,o)&&Number(x.account_id)===aid&&(String(x.status)==="paid"||x.paid_date)).reduce((s,x)=>s+Number(x.amount||0),0),tin=(D.finance.internal_transfers||[]).filter(x=>financeOwn(x,o)&&Number(x.to_account_id)===aid&&String(x.status||"completed")!=="cancelled").reduce((s,x)=>s+Number(x.amount||0),0),tout=(D.finance.internal_transfers||[]).filter(x=>financeOwn(x,o)&&Number(x.from_account_id)===aid&&String(x.status||"completed")!=="cancelled").reduce((s,x)=>s+Number(x.amount||0),0);return opening+inc-exp+tin-tout}
