function financeLoanDebtV60(){let o=financeOwnerId();return D.finance.loan_installments.filter(i=>financeOwn(i,o)&&String(i.status)!=="paid"&&!i.paid_date).reduce((s,i)=>s+Number(i.amount||0),0)}
function financeCardOpenV60(month=financeMonthSelected){let o=financeOwnerId();return D.finance.expenses.filter(e=>financeOwn(e,o)&&e.card_id&&financeRecordMonth(e,"expense")===month&&String(e.status)!=="paid"&&!e.paid_date).reduce((s,e)=>s+Number(e.amount||0),0)}
function financeSnapshotV60(month=financeMonthSelected){let o=financeOwnerId(),s=financeSummary(month),accounts=D.finance.accounts.filter(a=>financeOwn(a,o)&&Number(a.is_active)!==0),cash=accounts.reduce((n,a)=>n+financeAccountBalanceV56(a),0),reserved=D.financeReserves.reduce((n,r)=>n+Number(r.amount||0),0),loanDebt=financeLoanDebtV60(),cardOpen=financeCardOpenV60(month),overdue=s.exp.filter(x=>financeDueState(x)[0]==="overdue"),today=iso(),week=new Date();week.setDate(week.getDate()+7);let weekIso=iso(week),upcoming=s.exp.filter(x=>String(x.status)!=="paid"&&!x.paid_date&&String(x.due_date||"").slice(0,10)>=today&&String(x.due_date||"").slice(0,10)<=weekIso),savings=s.received?((s.received-s.paid)/s.received*100):0;return{...s,accounts,cash,reserved,available:cash-reserved,loanDebt,cardOpen,net:cash-loanDebt-cardOpen,overdue,upcoming,savings}}
function financeMonthSeriesV60(count=6){let out=[];for(let i=count-1;i>=0;i--){let m=financeShiftMonth(financeMonthSelected,-i),s=financeSummary(m);out.push({month:m,label:financeMonthLabel(m).split(" de ")[0].slice(0,3),received:s.received,paid:s.paid,balance:s.balance})}return out}
function financeCategorySpendV60(month=financeMonthSelected){let o=financeOwnerId(),map={};D.finance.expenses.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"expense")===month).forEach(x=>{let k=financeCatName(x.category_id);map[k]=(map[k]||0)+Number(x.amount||0)});return Object.entries(map).map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value)}
function financeTabsV60(){let tabs=[["dashboard","Visão geral"],["accounts","Contas"],["transactions","Movimentações"],["incomes","Receitas"],["expenses","Despesas"],["cards","Cartões"],["transfers","Transferências"],["loans","Empréstimos"],["recurring","Recorrentes"],["planning","Planejamento"],["reports","Relatórios"]];return`<div class="financeTabs financeTabsV60" role="tablist" aria-label="Seções de finanças">${tabs.map(t=>`<button class="${financeTab===t[0]?"on":""}" data-fin-tab="${t[0]}" role="tab">${t[1]}</button>`).join("")}</div>`}
function financeDashboardV60(){let s=financeSnapshotV60(),cats=financeCategorySpendV60().slice(0,5),series=financeMonthSeriesV60(),max=Math.max(1,...series.flatMap(x=>[x.received,x.paid])),o=financeOwnerId(),budgets=D.finance.budgets.filter(x=>financeOwn(x,o)&&String(x.month)===financeMonthSelected),budgetAlerts=budgets.filter(b=>{let spent=D.finance.expenses.filter(e=>financeOwn(e,o)&&financeRecordMonth(e,"expense")===financeMonthSelected&&Number(e.category_id)===Number(b.category_id)).reduce((n,e)=>n+Number(e.amount||0),0);return Number(b.limit_amount)>0&&spent/Number(b.limit_amount)>=.8}),cards=D.finance.cards.filter(c=>financeOwn(c,o)&&Number(c.is_active)!==0);return `<div class="financeMetrics financeMetricsV60"><div class="financeMetric"><span>Saldo em contas</span><b class="${s.cash>=0?"positive":"negative"}">${moneyBR(s.cash)}</b><small>Disponível após reservas: ${moneyBR(s.available)}</small></div><div class="financeMetric"><span>Resultado do mês</span><b class="${s.balance>=0?"positive":"negative"}">${moneyBR(s.balance)}</b><small>${s.savings.toLocaleString("pt-BR",{maximumFractionDigits:1})}% da renda recebida ficou livre</small></div><div class="financeMetric"><span>A pagar</span><b class="warnText">${moneyBR(s.pending)}</b><small>${s.overdue.length} vencida(s) • ${s.upcoming.length} nos próximos 7 dias</small></div><div class="financeMetric"><span>Dívidas cadastradas</span><b>${moneyBR(s.loanDebt+s.cardOpen)}</b><small>Empréstimos ${moneyBR(s.loanDebt)} • cartões ${moneyBR(s.cardOpen)}</small></div><div class="financeMetric"><span>Patrimônio líquido estimado</span><b class="${s.net>=0?"positive":"negative"}">${moneyBR(s.net)}</b><small>Contas − empréstimos − faturas abertas</small></div></div><div class="financeQuickActionsV60"><button class="btn" data-fin-new="income">＋ Receita</button><button class="btn sec" data-fin-new="expense">− Despesa</button><button class="pill" data-fin-transfer-new>⇄ Transferir</button><button class="pill" data-reserve-new>◇ Reserva</button></div><div class="financeDashboardGridV60"><div class="card"><div class="sectionMini"><div><span class="kicker">FLUXO DE CAIXA</span><h2>Últimos 6 meses</h2></div><button class="link" data-fin-tab="reports">Detalhes</button></div><div class="cashflowChartV60">${series.map(x=>`<div class="cashflowMonthV60"><div class="cashflowBarsV60"><i class="income" style="height:${Math.max(3,x.received/max*100)}%" title="Receitas ${moneyBR(x.received)}"></i><i class="expense" style="height:${Math.max(3,x.paid/max*100)}%" title="Despesas ${moneyBR(x.paid)}"></i></div><small>${esc(x.label)}</small></div>`).join("")}</div><div class="cashflowLegendV60"><span>＋ Recebido</span><span>− Pago</span></div></div><div class="card"><div class="sectionMini"><div><span class="kicker">GASTOS</span><h2>Maiores categorias</h2></div></div><div class="financeCategoryBarsV60">${cats.length?cats.map((c,i)=>{let pct=cats[0]?.value?c.value/cats[0].value*100:0;return`<div><div class="row between"><span>${esc(c.name)}</span><b>${moneyBR(c.value)}</b></div><div class="bar"><i style="width:${pct}%"></i></div></div>`}).join(""):`<p class="sub">Sem despesas categorizadas no mês.</p>`}</div></div><div class="card"><div class="sectionMini"><div><span class="kicker">ATENÇÃO</span><h2>Pontos para revisar</h2></div></div><div class="financeAttentionV60">${s.overdue.length?`<button data-fin-tab="expenses"><b class="negative">${s.overdue.length} despesa(s) vencida(s)</b><small>${moneyBR(s.overdue.reduce((n,x)=>n+Number(x.amount||0),0))} aguardando pagamento</small></button>`:""}${budgetAlerts.length?`<button data-fin-tab="planning"><b class="warnText">${budgetAlerts.length} orçamento(s) em 80%+</b><small>Revise os limites antes do fim do mês.</small></button>`:""}${s.available<0?`<button data-fin-tab="accounts"><b class="negative">Reservas acima do saldo</b><small>Há mais valor reservado do que disponível nas contas.</small></button>`:""}${!s.overdue.length&&!budgetAlerts.length&&s.available>=0?`<div class="financeOkV60"><b>✓ Finanças sem alertas críticos</b><small>Continue acompanhando vencimentos e orçamento.</small></div>`:""}</div></div><div class="card"><div class="sectionMini"><div><span class="kicker">ESTRUTURA</span><h2>Seu módulo financeiro</h2></div></div><div class="financeMiniGrid"><div><span>Contas ativas</span><b>${s.accounts.length}</b></div><div><span>Cartões ativos</span><b>${cards.length}</b></div><div><span>Reservas</span><b>${D.financeReserves.length}</b></div><div><span>Orçamentos</span><b>${budgets.length}</b></div></div></div></div>`}
function financeAccountMovesV60(a){let id=Number(a.id);return [...D.finance.incomes.filter(x=>Number(x.account_id)===id&&String(x.status)==="received").map(x=>({date:x.received_date||x.expected_date,label:x.description,value:Number(x.amount_received||x.amount_expected||0),type:"Receita"})),...D.finance.expenses.filter(x=>Number(x.account_id)===id&&(String(x.status)==="paid"||x.paid_date)).map(x=>({date:x.paid_date||x.due_date,label:x.description,value:-Number(x.amount||0),type:"Despesa"})),...(D.finance.internal_transfers||[]).filter(x=>String(x.status||"completed")!=="cancelled"&&Number(x.to_account_id)===id).map(x=>({date:x.transfer_date,label:x.description||"Transferência recebida",value:Number(x.amount||0),type:"Transferência"})),...(D.finance.internal_transfers||[]).filter(x=>String(x.status||"completed")!=="cancelled"&&Number(x.from_account_id)===id).map(x=>({date:x.transfer_date,label:x.description||"Transferência enviada",value:-Number(x.amount||0),type:"Transferência"}))].sort((x,y)=>String(y.date||"").localeCompare(String(x.date||"")))}
function financeAccountsV60(){let o=financeOwnerId(),rows=D.finance.accounts.filter(x=>financeOwn(x,o)).sort((a,b)=>Number(b.is_active??1)-Number(a.is_active??1)||String(a.name||"").localeCompare(String(b.name||""),"pt-BR")),total=rows.filter(a=>Number(a.is_active)!==0).reduce((s,a)=>s+financeAccountBalanceV56(a),0);return`<div class="financeToolbar"><div><h2>Contas e carteiras</h2><p class="sub">Saldo real com receitas, despesas e transferências internas.</p></div><div class="financeToolbarActions"><button class="pill" data-fin-transfer-new>⇄ Transferir</button><button class="btn" data-fin-account-new>＋ Nova conta</button></div></div><div class="financeAccountSummaryV60"><span>Total em contas ativas</span><b class="${total>=0?"positive":"negative"}">${moneyBR(total)}</b></div><div class="financeAccountGridV60">${rows.length?rows.map(a=>{let bal=financeAccountBalanceV56(a),reserved=D.financeReserves.filter(r=>Number(r.accountId)===Number(a.id)).reduce((s,r)=>s+Number(r.amount||0),0),moves=financeAccountMovesV60(a).slice(0,4);return`<div class="card financeAccountCardV60 ${Number(a.is_active)===0?"inactive":""}"><div class="row between"><div><span class="kicker">${esc(a.type||"CONTA")}</span><h2>${esc(a.name||"Conta")}</h2><p class="sub">${esc(a.bank||a.institution||"")}</p></div><span class="status ${Number(a.is_active)===0?"pending":"paid"}">${Number(a.is_active)===0?"Inativa":"Ativa"}</span></div><div class="accountBalance ${bal>=0?"positive":"negative"}">${moneyBR(bal)}</div><div class="financeAccountFactsV60"><span>Reservado <b>${moneyBR(reserved)}</b></span><span>Disponível <b class="${bal-reserved>=0?"positive":"negative"}">${moneyBR(bal-reserved)}</b></span><span>Saldo inicial <b>${moneyBR(a.initial_balance||0)}</b></span></div><div class="accountMiniMoves">${moves.length?moves.map(m=>`<div><span>${esc(m.label)}<small>${esc(m.type)} • ${toolDateLabel(m.date)}</small></span><b class="${m.value>=0?"positive":"negative"}">${m.value>=0?"+":""}${moneyBR(m.value)}</b></div>`).join(""):`<p class="sub">Sem movimentações vinculadas.</p>`}</div><div class="projectActions"><button class="pill" data-fin-transfer-from="${a.id}">⇄ Transferir</button><button class="pill" data-fin-account-edit="${a.id}">✎ Editar</button></div></div>`}).join(""):`<div class="card sub">Cadastre sua primeira conta ou carteira para acompanhar saldo real.</div>`}</div>`}
function financeTransactionsV60(){let o=financeOwnerId(),month=financeMonthSelected,accounts=D.finance.accounts.filter(a=>financeOwn(a,o)),rows=[...D.finance.incomes.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"income")===month).map(x=>({kind:"income",id:x.id,date:x.received_date||x.expected_date,title:x.description,amount:Number(x.amount_received||x.amount_expected||0),status:String(x.status||"pending"),accountId:x.account_id,categoryId:x.category_id,meta:`Receita • ${financeCatName(x.category_id)}`})),...D.finance.expenses.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"expense")===month).map(x=>({kind:"expense",id:x.id,date:x.paid_date||x.due_date||x.purchase_date,title:x.description,amount:-Number(x.amount||0),status:financeDueState(x)[0],accountId:x.account_id,categoryId:x.category_id,meta:`Despesa • ${financeCatName(x.category_id)}`})),...(D.finance.internal_transfers||[]).filter(x=>financeOwn(x,o)&&String(x.transfer_date||"").slice(0,7)===month).map(x=>({kind:"transfer",id:x.id,date:x.transfer_date,title:x.description||"Transferência",amount:Number(x.amount||0),status:String(x.status||"completed"),accountId:x.from_account_id,categoryId:null,meta:`${financeAccountNameV56(x.from_account_id)} → ${financeAccountNameV56(x.to_account_id)}`}))].sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));let cats=D.finance.categories.filter(c=>financeOwn(c,o));return`<div class="financeToolbar"><div><h2>Movimentações</h2><p class="sub">Receitas, despesas e transferências em uma linha do tempo única.</p></div><div class="financeToolbarActions"><button class="pill" data-fin-transfer-new>⇄ Transferir</button><button class="btn" data-fin-new="income">＋ Receita</button><button class="btn sec" data-fin-new="expense">− Despesa</button></div></div><div class="financeFilters financeFiltersV60"><input id="finTxnSearch" class="field" placeholder="Buscar movimentação..."><select id="finTxnType" class="field"><option value="all">Todos os tipos</option><option value="income">Receitas</option><option value="expense">Despesas</option><option value="transfer">Transferências</option></select><select id="finTxnAccount" class="field"><option value="all">Todas as contas</option>${accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join("")}</select><select id="finTxnCategory" class="field"><option value="all">Todas as categorias</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><span class="financeCount" id="finTxnCount">${rows.length} movimentação(ões)</span></div><div class="financeTransactionListV60" id="finTxnRows">${rows.length?rows.map(x=>`<div class="financeTxnRowV60" data-txn-search="${esc(`${x.title} ${x.meta}`.toLocaleLowerCase("pt-BR"))}" data-txn-kind="${x.kind}" data-txn-account="${x.accountId||""}" data-txn-category="${x.categoryId||""}"><span class="financeTxnIconV60 ${x.kind}">${x.kind==="income"?"+":x.kind==="expense"?"−":"⇄"}</span><div class="grow"><b>${esc(x.title)}</b><small>${esc(x.meta)} • ${toolDateLabel(x.date)}</small></div><div class="financeTxnAmountV60"><b class="${x.kind==="income"?"positive":x.kind==="expense"?"negative":""}">${x.kind==="income"?"+":x.kind==="expense"?"−":""}${moneyBR(Math.abs(x.amount))}</b><span class="status ${x.status}">${x.status==="received"?"Recebida":x.status==="paid"?"Paga":x.status==="overdue"?"Vencida":x.kind==="transfer"?"Transferida":"Pendente"}</span></div><div class="financeTxnActionsV60">${x.kind==="transfer"?`<button class="iconAction" data-fin-transfer-edit="${x.id}" title="Editar">✎</button><button class="iconAction danger" data-fin-transfer-del="${x.id}" title="Excluir">×</button>`:`<button class="iconAction" data-fin-edit="${x.kind}:${x.id}" title="Editar">✎</button>`}</div></div>`).join(""):`<div class="card sub">Nenhuma movimentação neste mês.</div>`}</div><div id="finTxnEmpty" class="card sub" hidden>Nenhuma movimentação corresponde aos filtros.</div>`}
function financeTransfersV60(){let o=financeOwnerId(),rows=(D.finance.internal_transfers||[]).filter(x=>financeOwn(x,o)&&String(x.transfer_date||"").slice(0,7)===financeMonthSelected).sort((a,b)=>String(b.transfer_date||"").localeCompare(String(a.transfer_date||""))),total=rows.reduce((s,x)=>s+Number(x.amount||0),0);return`<div class="financeToolbar"><div><h2>Transferências internas</h2><p class="sub">Movimente dinheiro entre suas contas sem registrar receita ou despesa artificial.</p></div><button class="btn" data-fin-transfer-new>⇄ Nova transferência</button></div><div class="card financeTransferSummaryV60"><span>Movimentado entre contas em ${esc(financeMonthLabel(financeMonthSelected))}</span><b>${moneyBR(total)}</b></div><div class="financeTable">${rows.length?rows.map(x=>`<div class="financeTransferRowV60"><span class="financeTxnIconV60 transfer">⇄</span><div class="grow"><b>${esc(x.description||"Transferência")}</b><small>${esc(financeAccountNameV56(x.from_account_id))} → ${esc(financeAccountNameV56(x.to_account_id))} • ${toolDateLabel(x.transfer_date)}${x.notes?` • ${esc(x.notes)}`:""}</small></div><strong>${moneyBR(x.amount)}</strong><button class="iconAction" data-fin-transfer-edit="${x.id}">✎</button><button class="iconAction danger" data-fin-transfer-del="${x.id}">×</button></div>`).join(""):`<div class="card sub">Nenhuma transferência neste mês.</div>`}</div>`}
const financePlanningBeforeV60=financePlanning;
function financeCategoryManagerV60(){let o=financeOwnerId(),cats=D.finance.categories.filter(c=>financeOwn(c,o)).sort((a,b)=>String(a.kind).localeCompare(String(b.kind))||String(a.name).localeCompare(String(b.name),"pt-BR"));return`<div class="card financeCategoriesV60"><div class="sectionMini"><div><span class="kicker">CATEGORIAS</span><h2>Organização dos lançamentos</h2></div><button class="pill" data-fin-category-new>＋ Categoria</button></div><div class="financeCategoryChipsV60">${cats.length?cats.map(c=>`<span class="financeCategoryChipV60"><i>${c.kind==="income"?"＋":"−"}</i><b>${esc(c.name)}</b><small>${c.kind==="income"?"Receita":"Despesa"}</small><button data-fin-category-edit="${c.id}" title="Editar">✎</button><button data-fin-category-del="${c.id}" title="Excluir">×</button></span>`).join(""):`<p class="sub">Crie categorias para melhorar relatórios e orçamentos.</p>`}</div></div>`}
function financePlanningV60(){return financePlanningBeforeV60()+financeSmartPanelV59()+financeCategoryManagerV60()}
function financeReportsV60(){let s=financeSnapshotV60(),series=financeMonthSeriesV60(6),cats=financeCategorySpendV60(),o=financeOwnerId(),budgets=D.finance.budgets.filter(x=>financeOwn(x,o)&&String(x.month)===financeMonthSelected),budgetRows=budgets.map(b=>{let spent=D.finance.expenses.filter(e=>financeOwn(e,o)&&financeRecordMonth(e,"expense")===financeMonthSelected&&Number(e.category_id)===Number(b.category_id)).reduce((n,e)=>n+Number(e.amount||0),0),limit=Number(b.limit_amount||0),pct=limit?spent/limit*100:0;return{name:financeCatName(b.category_id),spent,limit,pct}});return`<div class="financeToolbar"><div><h2>Relatórios financeiros</h2><p class="sub">Fluxo de caixa, categorias, orçamento e saúde financeira.</p></div><div class="financeToolbarActions"><button class="pill" data-fin-export-transactions>⇩ Extrato CSV</button><button class="btn" data-month-report>▤ Relatório mensal</button></div></div><div class="financeReportMetricsV60"><div class="card"><small>Taxa de sobra</small><b class="${s.savings>=0?"positive":"negative"}">${s.savings.toLocaleString("pt-BR",{maximumFractionDigits:1})}%</b><span>do valor recebido após pagamentos</span></div><div class="card"><small>Comprometimento</small><b>${s.commit.toLocaleString("pt-BR",{maximumFractionDigits:1})}%</b><span>despesas / renda prevista</span></div><div class="card"><small>Reservas</small><b>${moneyBR(s.reserved)}</b><span>${D.financeReserves.length} objetivo(s)</span></div><div class="card"><small>Pendências</small><b class="${s.overdue.length?"negative":""}">${s.overdue.length}</b><span>despesas vencidas</span></div></div><div class="financeReportsGridV60"><div class="card"><span class="kicker">6 MESES</span><h2>Fluxo de caixa</h2><div class="financeReportTableV60"><div class="reportHead"><span>Mês</span><span>Recebido</span><span>Pago</span><span>Resultado</span></div>${series.map(x=>`<div><span>${esc(financeMonthLabel(x.month))}</span><b class="positive">${moneyBR(x.received)}</b><b>${moneyBR(x.paid)}</b><b class="${x.balance>=0?"positive":"negative"}">${moneyBR(x.balance)}</b></div>`).join("")}</div></div><div class="card"><span class="kicker">CATEGORIAS</span><h2>Distribuição de gastos</h2><div class="financeReportTableV60 compact">${cats.length?cats.slice(0,10).map(c=>`<div><span>${esc(c.name)}</span><b>${moneyBR(c.value)}</b><span>${s.totalExp?Math.round(c.value/s.totalExp*100):0}%</span></div>`).join(""):`<p class="sub">Sem dados para o mês.</p>`}</div></div><div class="card"><span class="kicker">ORÇAMENTO</span><h2>Execução por categoria</h2><div class="budgetList">${budgetRows.length?budgetRows.map(b=>`<div class="budgetRow"><div class="grow"><b>${esc(b.name)}</b><small>${moneyBR(b.spent)} de ${moneyBR(b.limit)}</small><div class="bar"><i style="width:${Math.min(100,b.pct)}%"></i></div></div><strong class="${b.pct>100?"negative":b.pct>=80?"warnText":""}">${b.pct.toFixed(0)}%</strong></div>`).join(""):`<p class="sub">Nenhum orçamento definido neste mês.</p>`}</div></div><div class="card"><span class="kicker">PROJEÇÃO</span><h2>Próximos 30 dias</h2>${(()=>{let f=financeForecastV59(30);return`<div class="financeProjectionV60"><span>Saldo atual <b>${moneyBR(f.balance)}</b></span><span>A receber <b class="positive">+${moneyBR(f.inc)}</b></span><span>A pagar <b class="negative">−${moneyBR(f.exp)}</b></span><span>Saldo projetado <b class="${f.projected>=0?"positive":"negative"}">${moneyBR(f.projected)}</b></span></div>`})()}</div></div>`}
function financeV60(){let owner=financeOwnerId(),added=ensureFinanceRecurringForMonth(financeMonthSelected);if(added)try{localStorage.setItem(KEY,JSON.stringify(D))}catch{}let s=financeSnapshotV60(),top=header("Finanças","Central financeira completa do Smart Life",`<div class="row financeHeadActions"><button class="pill" data-fin-export-transactions>⇩ Extrato</button><button class="pill" data-fin-export>Backup financeiro</button><button class="pill" data-fin-import>Importar</button></div>`)+`<div class="financeSource financeSourceV60"><span>Saldo em contas: <b>${moneyBR(s.cash)}</b> <i>•</i> Disponível: <b>${moneyBR(s.available)}</b></span><small>Os saldos consideram receitas recebidas, despesas pagas e transferências internas. Reservas não removem dinheiro da conta.</small></div><div class="financeTopRow">${financeMonthControls()}<span class="financeMonthLabel">${esc(financeMonthLabel(financeMonthSelected))}</span></div>${financeTabsV60()}`;let body=financeTab==="dashboard"?financeDashboardV60():financeTab==="accounts"?financeAccountsV60():financeTab==="transactions"?financeTransactionsV60():financeTab==="incomes"?financeIncomes():financeTab==="expenses"?financeExpenses():financeTab==="cards"?financeCards():financeTab==="transfers"?financeTransfersV60():financeTab==="loans"?financeLoans():financeTab==="recurring"?financeRecurring():financeTab==="planning"?financePlanningV60():financeReportsV60();return top+body}
